declare
  v_id uuid;
  v_content jsonb := $content${"questions":[{"id":"q1","text":"假設你是負責管理香港熱門旅遊景點的政府官員，面對遊客違規餵飼及捕捉野鴿的情況，你會如何制定有效的管理方案，在有限執法資源下改善公共衞生、保障動物福利，同時維持良好的旅遊體驗？","for_label":"具體政策與管理方案","against_label":"反對意見、限制與執行難題","for":[{"id":"arg:for:1","number":1,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"在泳灘入口以一眼讀懂的圖文列明禁餵與罰則 [教育][資訊提醒]","description":"誰負責／怎樣做：康文署在淺水灣主要入口設「不餵鴿／5,000元定額罰款」圖像告示，漁護署提供統一法律文字。  作用／限制：在行為發生前提醒，比事後追人更省人手；罰則須區分定額罰款與法院最高刑罰。","glossary":[{"id":"gloss:for:1:1","english":"entry sign","chinese":"入口標示"},{"id":"gloss:for:1:2","english":"feeding ban","chinese":"餵飼禁令"},{"id":"gloss:for:1:3","english":"fixed penalty","chinese":"定額罰款"},{"id":"gloss:for:1:4","english":"visitor rules","chinese":"遊客規則"},{"id":"gloss:for:1:5","english":"clear message","chinese":"清晰訊息"}]},{"id":"arg:for:2","number":2,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"把「不捉鳥拍照」與「不餵飼」分開提示 [教育][動物保護]","description":"誰負責／怎樣做：康文署以兩幅簡單插圖展示「不給食物」及「不抓起雀鳥」，漁護署核對法律和動物福利文字。  作用／限制：有人可能知道禁餵卻以為可以抱鳥合照；兩種行為的法律判斷仍須分開。","glossary":[{"id":"gloss:for:2:1","english":"do not touch","chinese":"不要觸碰"},{"id":"gloss:for:2:2","english":"catch a bird","chinese":"捕捉雀鳥"},{"id":"gloss:for:2:3","english":"safe photos","chinese":"安全拍照"},{"id":"gloss:for:2:4","english":"animal care","chinese":"動物照顧"},{"id":"gloss:for:2:5","english":"follow the rules","chinese":"遵守規則"}]},{"id":"arg:for:3","number":3,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"將告示設在遊客真正停下來的位置 [場地設計][資訊提醒]","description":"誰負責／怎樣做：康文署先觀察遊客在哪些涼亭、長椅及拍照點撒糧，再把小型告示放在相關路線而非僅在辦公室入口。  作用／限制：提高看見機會而不需要新增大量人員；標示不能阻塞逃生或行動不便人士通道。","glossary":[{"id":"gloss:for:3:1","english":"popular spot","chinese":"熱門位置"},{"id":"gloss:for:3:2","english":"easy to notice","chinese":"容易留意"},{"id":"gloss:for:3:3","english":"walking path","chinese":"步行路徑"},{"id":"gloss:for:3:4","english":"visitor stop","chinese":"遊客停留點"},{"id":"gloss:for:3:5","english":"open access","chinese":"暢通通道"}]},{"id":"arg:for:4","number":4,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"按假日人流移動便攜式提示牌 [時間管理][試行]","description":"誰負責／怎樣做：康文署於周末及長假按巡場紀錄移動可重用提示牌，平日移回真正有需要的位置。  作用／限制：避免在人少時長期佔用設施；需防海風推倒牌架。","glossary":[{"id":"gloss:for:4:1","english":"holiday crowd","chinese":"假日人潮"},{"id":"gloss:for:4:2","english":"portable sign","chinese":"可移動告示"},{"id":"gloss:for:4:3","english":"move the sign","chinese":"移動告示"},{"id":"gloss:for:4:4","english":"busy period","chinese":"繁忙時段"},{"id":"gloss:for:4:5","english":"safe position","chinese":"安全位置"}]},{"id":"arg:for:5","number":5,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"用繁簡中文與英文配合圖示提醒 [教育][平等]","description":"誰負責／怎樣做：康文署與旅發局製作可讀的繁體、簡體中文及英文短句，並以圖像照顧不熟悉文字的遊客。  作用／限制：針對語言障礙而非猜測任何人的國籍；不同版本必須表達相同法律要求。","glossary":[{"id":"gloss:for:5:1","english":"language choice","chinese":"語言選擇"},{"id":"gloss:for:5:2","english":"simple English","chinese":"簡單英文"},{"id":"gloss:for:5:3","english":"picture signs","chinese":"圖像標示"},{"id":"gloss:for:5:4","english":"read the notice","chinese":"閱讀告示"},{"id":"gloss:for:5:5","english":"equal access","chinese":"平等獲取資訊"}]},{"id":"arg:for:6","number":6,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"在沙灘近食物區提醒先收好食物 [衞生][資訊提醒]","description":"誰負責／怎樣做：康文署與相關食肆營辦者在外賣及休憩區張貼「食物不要放在鴿子可取之處」提示。  作用／限制：減少食物落地與意外引來鴿群；不能把所有正常進食一律視為非法餵飼。","glossary":[{"id":"gloss:for:6:1","english":"cover your food","chinese":"蓋好食物"},{"id":"gloss:for:6:2","english":"food leftovers","chinese":"食物殘渣"},{"id":"gloss:for:6:3","english":"keep the area clean","chinese":"保持地方清潔"},{"id":"gloss:for:6:4","english":"avoid attracting birds","chinese":"避免吸引雀鳥"},{"id":"gloss:for:6:5","english":"picnic area","chinese":"野餐區"}]},{"id":"arg:for:7","number":7,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"以三步驟口號取代密集法例文字 [教育][資訊提醒]","description":"誰負責／怎樣做：漁護署與康文署統一用「看鳥、拍照、不餵不捉」作旅客語言，再在旁附正式法例連結。  作用／限制：短訊容易記住；口號不可取代完整法定告示或扭曲相關法律。","glossary":[{"id":"gloss:for:7:1","english":"watch from afar","chinese":"從遠處觀看"},{"id":"gloss:for:7:2","english":"enjoy the view","chinese":"欣賞景色"},{"id":"gloss:for:7:3","english":"keep your distance","chinese":"保持距離"},{"id":"gloss:for:7:4","english":"easy steps","chinese":"簡單步驟"},{"id":"gloss:for:7:5","english":"remember the rule","chinese":"記住規則"}]},{"id":"arg:for:8","number":8,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"在高峰時段安排短而固定的廣播 [資訊提醒][時間管理]","description":"誰負責／怎樣做：康文署如現場設備合適，可在下午人潮高峰播放15秒普通話、粵語及英文提醒，不循環轟炸遊客。  作用／限制：能同時通知較多人；廣播太密會損害泳灘寧靜及景點體驗。","glossary":[{"id":"gloss:for:8:1","english":"short message","chinese":"簡短訊息"},{"id":"gloss:for:8:2","english":"public announcement","chinese":"公眾廣播"},{"id":"gloss:for:8:3","english":"busy hours","chinese":"繁忙時間"},{"id":"gloss:for:8:4","english":"too much noise","chinese":"過量噪音"},{"id":"gloss:for:8:5","english":"quiet beach","chinese":"寧靜泳灘"}]},{"id":"arg:for:9","number":9,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"一線員工使用統一而有禮貌的提醒句 [培訓][程序公平]","description":"誰負責／怎樣做：康文署培訓場地職員先保持安全距離、指出規則、邀請停止行為，再按職權通知獲委任執法人員。  作用／限制：減少衝突和前線員工自行作法律裁判；遇威脅即退出並尋求支援。","glossary":[{"id":"gloss:for:9:1","english":"polite reminder","chinese":"有禮貌提醒"},{"id":"gloss:for:9:2","english":"frontline staff","chinese":"前線員工"},{"id":"gloss:for:9:3","english":"calm voice","chinese":"平靜語氣"},{"id":"gloss:for:9:4","english":"ask for help","chinese":"尋求協助"},{"id":"gloss:for:9:5","english":"avoid conflict","chinese":"避免衝突"}]},{"id":"arg:for:10","number":10,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"設立「一分鐘懂禁餵」官方網頁連結 [科技][資訊提醒]","description":"誰負責／怎樣做：康文署在場地告示附漁護署官方短連結及 QR 碼，內容同時介紹罰則、衞生與安全拍照方法。  作用／限制：讓有需要的人自行查詳情；基本禁令仍須在牌面可見，不能強迫使用手機。","glossary":[{"id":"gloss:for:10:1","english":"official website","chinese":"官方網站"},{"id":"gloss:for:10:2","english":"QR code","chinese":"二維碼"},{"id":"gloss:for:10:3","english":"more details","chinese":"更多資料"},{"id":"gloss:for:10:4","english":"phone access","chinese":"手機存取"},{"id":"gloss:for:10:5","english":"no app needed","chinese":"不需安裝應用程式"}]},{"id":"arg:for:11","number":11,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"對殘缺或被遮擋的告示採用固定檢查表 [場地管理][評估]","description":"誰負責／怎樣做：康文署讓現有巡場人員每周檢查告示是否被樹葉遮擋、風雨損壞或褪色，集中一次維修。  作用／限制：資訊有效程度取決於能否看見；避免只計設置數量。","glossary":[{"id":"gloss:for:11:1","english":"weekly check","chinese":"每周檢查"},{"id":"gloss:for:11:2","english":"broken sign","chinese":"損壞告示"},{"id":"gloss:for:11:3","english":"clear view","chinese":"清楚視野"},{"id":"gloss:for:11:4","english":"repair quickly","chinese":"盡快維修"},{"id":"gloss:for:11:5","english":"checklist","chinese":"檢查清單"}]},{"id":"arg:for:12","number":12,"angle":"A｜現場標示與即時勸導：在決定餵飼之前介入","title":"設立小型「文明觀鳥」流動攤位 [教育][試行]","description":"誰負責／怎樣做：漁護署、康文署與合資格自然教育團體在少數假日設30分鐘簡介點，向家庭示範遠距觀鳥。  作用／限制：把規則轉為愉快體驗；先試高峰日，不宜全年長期占用人手。","glossary":[{"id":"gloss:for:12:1","english":"short talk","chinese":"短講"},{"id":"gloss:for:12:2","english":"bird watching","chinese":"觀鳥"},{"id":"gloss:for:12:3","english":"family learning","chinese":"家庭學習"},{"id":"gloss:for:12:4","english":"weekend activity","chinese":"周末活動"},{"id":"gloss:for:12:5","english":"helpful advice","chinese":"實用建議"}]},{"id":"arg:for:13","number":13,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"把禁餵提醒放進旅行社的出發前訊息 [教育][旅遊協作]","description":"誰負責／怎樣做：持牌旅行社在行程確認電郵或集合通知加入一行「香港公共地方不要餵野鴿」；旅監局可向業界發參考指引。  作用／限制：讓旅客到場前已知規則；新強制牌照義務須另按法律程序審議。","glossary":[{"id":"gloss:for:13:1","english":"travel plan","chinese":"旅行計劃"},{"id":"gloss:for:13:2","english":"trip message","chinese":"行程訊息"},{"id":"gloss:for:13:3","english":"before arrival","chinese":"抵達前"},{"id":"gloss:for:13:4","english":"travel agency","chinese":"旅行社"},{"id":"gloss:for:13:5","english":"know the rules","chinese":"了解規則"}]},{"id":"arg:for:14","number":14,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"導遊抵達景點前作30秒示範說明 [培訓][旅遊協作]","description":"誰負責／怎樣做：持牌導遊在旅遊巴駛近淺水灣前，以簡短口語指出禁餵、切勿抱鳥合照，以及垃圾投放位置。  作用／限制：比到場後多人同時解釋有效率；導遊只是提醒者，不是執法人員。","glossary":[{"id":"gloss:for:14:1","english":"tour guide","chinese":"導遊"},{"id":"gloss:for:14:2","english":"group talk","chinese":"團體簡介"},{"id":"gloss:for:14:3","english":"short reminder","chinese":"簡短提醒"},{"id":"gloss:for:14:4","english":"bus journey","chinese":"巴士旅程"},{"id":"gloss:for:14:5","english":"safe visit","chinese":"安全遊覽"}]},{"id":"arg:for:15","number":15,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"導遊收到官方一頁式景點規則卡 [資訊提醒][合作]","description":"誰負責／怎樣做：旅監局與漁護署、康文署合作提供可打印圖卡給業界，由導遊向團員轉發。  作用／限制：降低每位導遊自行查法例的成本；須按最新法例更新版本。","glossary":[{"id":"gloss:for:15:1","english":"one-page guide","chinese":"一頁指引"},{"id":"gloss:for:15:2","english":"printable card","chinese":"可列印卡片"},{"id":"gloss:for:15:3","english":"travel group","chinese":"旅行團"},{"id":"gloss:for:15:4","english":"updated information","chinese":"更新資訊"},{"id":"gloss:for:15:5","english":"share the guide","chinese":"分享指引"}]},{"id":"arg:for:16","number":16,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"在旅行團集合點明確告知家長兒童禁抓野鳥 [兒童教育][旅遊協作]","description":"誰負責／怎樣做：旅行團領隊於下車前提醒家長看顧孩子，並說明抓鳥玩耍會嚇怕動物和帶來接觸風險。  作用／限制：把注意力放在看顧和安全；不得對未確認涉事兒童作公開指責。","glossary":[{"id":"gloss:for:16:1","english":"watch your child","chinese":"看顧子女"},{"id":"gloss:for:16:2","english":"young visitors","chinese":"年幼遊客"},{"id":"gloss:for:16:3","english":"do not catch birds","chinese":"不要抓鳥"},{"id":"gloss:for:16:4","english":"parent reminder","chinese":"家長提醒"},{"id":"gloss:for:16:5","english":"animal safety","chinese":"動物安全"}]},{"id":"arg:for:17","number":17,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"旅發局在熱門景點介紹頁附「守護景點」資訊 [旅遊協作][資訊公開]","description":"誰負責／怎樣做：旅發局在淺水灣旅遊網頁或合適宣傳材料列出三個易明守則，連到漁護署正式資料。  作用／限制：訪客規劃行程時先接收資訊；旅發局負責宣傳，並非罰款執行。","glossary":[{"id":"gloss:for:17:1","english":"visitor website","chinese":"遊客網頁"},{"id":"gloss:for:17:2","english":"place guide","chinese":"景點指南"},{"id":"gloss:for:17:3","english":"plan a trip","chinese":"規劃旅程"},{"id":"gloss:for:17:4","english":"visitor advice","chinese":"遊客建議"},{"id":"gloss:for:17:5","english":"travel information","chinese":"旅遊資訊"}]},{"id":"arg:for:18","number":18,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"在酒店前台提供小型安全旅遊卡 [合作][資訊提醒]","description":"誰負責／怎樣做：淺水灣及港島酒店可自願把主要景點的禁餵、環保及求助資料放在前台或電子入住訊息。  作用／限制：接觸不參團的遊客；不可假定所有酒店願意無成本承擔宣傳。","glossary":[{"id":"gloss:for:18:1","english":"hotel desk","chinese":"酒店前台"},{"id":"gloss:for:18:2","english":"welcome card","chinese":"迎賓卡"},{"id":"gloss:for:18:3","english":"guest information","chinese":"住客資訊"},{"id":"gloss:for:18:4","english":"local advice","chinese":"本地建議"},{"id":"gloss:for:18:5","english":"helpful tips","chinese":"實用提示"}]},{"id":"arg:for:19","number":19,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"在跨境交通接觸點延續已有禁餵宣傳 [資訊提醒][合作]","description":"誰負責／怎樣做：漁護署已曾在口岸、港鐵及跨境巴士刊登相關訊息；可與運輸業界檢討應在哪些假期重播。  作用／限制：將資源投向新增遊客高峰，而非誤稱這項宣傳尚未出現。","glossary":[{"id":"gloss:for:19:1","english":"border point","chinese":"邊境口岸"},{"id":"gloss:for:19:2","english":"holiday travel","chinese":"假期旅遊"},{"id":"gloss:for:19:3","english":"public transport","chinese":"公共交通"},{"id":"gloss:for:19:4","english":"remind visitors","chinese":"提醒遊客"},{"id":"gloss:for:19:5","english":"seasonal message","chinese":"季節性訊息"}]},{"id":"arg:for:20","number":20,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"旅遊巴公司在常去景點的車窗貼提示 [合作][資訊提醒]","description":"誰負責／怎樣做：旅遊巴營辦商可自願在車門內側放小貼紙，提醒團員下車後不餵鳥、不留下零食。  作用／限制：在下車的一刻提醒；須避免遮擋車窗視線。","glossary":[{"id":"gloss:for:20:1","english":"coach bus","chinese":"旅遊巴"},{"id":"gloss:for:20:2","english":"door notice","chinese":"車門提示"},{"id":"gloss:for:20:3","english":"before getting off","chinese":"下車之前"},{"id":"gloss:for:20:4","english":"safe travel","chinese":"安全旅行"},{"id":"gloss:for:20:5","english":"keep windows clear","chinese":"保持車窗清晰"}]},{"id":"arg:for:21","number":21,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"在旅遊行程中加入「遠距看野鳥」替代活動 [旅遊設計][教育]","description":"誰負責／怎樣做：旅行社與自然教育導遊可安排望遠鏡觀鳥及海灘景觀解說，取代以餵食吸引鳥隻的拍照玩法。  作用／限制：保留自然接觸的吸引力；避免動物被過量人流追逐。","glossary":[{"id":"gloss:for:21:1","english":"bird watching","chinese":"觀鳥"},{"id":"gloss:for:21:2","english":"use binoculars","chinese":"使用望遠鏡"},{"id":"gloss:for:21:3","english":"seaside view","chinese":"海濱景色"},{"id":"gloss:for:21:4","english":"nature tour","chinese":"自然導賞"},{"id":"gloss:for:21:5","english":"watch from a distance","chinese":"遠距觀看"}]},{"id":"arg:for:22","number":22,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"為自由行遊客準備可下載的景點規則地圖 [公共服務][資訊公開]","description":"誰負責／怎樣做：康文署與旅發局提供簡單地圖，標示公共廁所、洗手處、垃圾桶及官方禁餵資訊。  作用／限制：不只服務旅行團；地圖應保留離線可讀版本。","glossary":[{"id":"gloss:for:22:1","english":"free map","chinese":"免費地圖"},{"id":"gloss:for:22:2","english":"public toilet","chinese":"公廁"},{"id":"gloss:for:22:3","english":"washing area","chinese":"洗手位置"},{"id":"gloss:for:22:4","english":"download a map","chinese":"下載地圖"},{"id":"gloss:for:22:5","english":"independent visitor","chinese":"自由行遊客"}]},{"id":"arg:for:23","number":23,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"在社交平台景點介紹中放置不餵鳥拍照提示 [平台協作][教育]","description":"誰負責／怎樣做：旅發局與願意合作的旅遊內容創作者發布不餵鳥也能拍出美照的短片，附官方禁餵資訊。  作用／限制：回應遊客想拍照的動機；宣傳內容不得暗示觸摸野鴿很安全。","glossary":[{"id":"gloss:for:23:1","english":"travel video","chinese":"旅遊短片"},{"id":"gloss:for:23:2","english":"photo advice","chinese":"拍照建議"},{"id":"gloss:for:23:3","english":"social media","chinese":"社交媒體"},{"id":"gloss:for:23:4","english":"share good habits","chinese":"分享良好習慣"},{"id":"gloss:for:23:5","english":"official link","chinese":"官方連結"}]},{"id":"arg:for:24","number":24,"angle":"B｜旅遊旅程：旅行社、導遊、酒店與旅發局","title":"以實際旅客提問改進多語言旅遊訊息 [評估][服務設計]","description":"誰負責／怎樣做：旅發局與旅監局定期收集導遊及訪客最常問的三個問題，交漁護署核對答案再更新材料。  作用／限制：以真實理解困難修訂資訊；勿為調查收集不必要的身分資料。","glossary":[{"id":"gloss:for:24:1","english":"visitor questions","chinese":"遊客問題"},{"id":"gloss:for:24:2","english":"common mistakes","chinese":"常見錯誤"},{"id":"gloss:for:24:3","english":"clear answers","chinese":"清楚答案"},{"id":"gloss:for:24:4","english":"improve the guide","chinese":"改善指引"},{"id":"gloss:for:24:5","english":"protect details","chinese":"保護個人資料"}]},{"id":"arg:for:25","number":25,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"用兒童語言說明「好心餵鳥也可能傷害鳥」 [兒童教育][動物保護]","description":"誰負責／怎樣做：學校、家長和自然教育團體以簡單圖畫解釋野鴿會自行找食物，並非需要遊客餵養。  作用／限制：處理兒童可能源於好奇和善意的動機；不把所有孩子視為故意違規者。","glossary":[{"id":"gloss:for:25:1","english":"good intentions","chinese":"好意"},{"id":"gloss:for:25:2","english":"find food","chinese":"尋找食物"},{"id":"gloss:for:25:3","english":"wild bird","chinese":"野鳥"},{"id":"gloss:for:25:4","english":"simple drawing","chinese":"簡單圖畫"},{"id":"gloss:for:25:5","english":"care for animals","chinese":"愛護動物"}]},{"id":"arg:for:26","number":26,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"親子遊覽前訂立「看得到、不摸到」約定 [家長責任][預防]","description":"誰負責／怎樣做：家長在沙灘入口與孩子約定保持距離、不追逐、不抓鳥，並說明遇鳥靠近時慢慢退後。  作用／限制：在突發興奮之前訂規則更容易執行；成人須以自身行為示範。","glossary":[{"id":"gloss:for:26:1","english":"family agreement","chinese":"家庭約定"},{"id":"gloss:for:26:2","english":"keep a distance","chinese":"保持距離"},{"id":"gloss:for:26:3","english":"do not chase","chinese":"不要追逐"},{"id":"gloss:for:26:4","english":"step back","chinese":"向後退"},{"id":"gloss:for:26:5","english":"set an example","chinese":"以身作則"}]},{"id":"arg:for:27","number":27,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"讓兒童用望遠鏡或畫畫代替抓鳥 [活動替代][教育]","description":"誰負責／怎樣做：自然教育團體與康文署合作舉辦短時段免費繪鳥活動或借出觀鳥工具。  作用／限制：回應「想靠近動物」的好奇心；設備借用須有管理與維護安排。","glossary":[{"id":"gloss:for:27:1","english":"draw a bird","chinese":"畫鳥"},{"id":"gloss:for:27:2","english":"look closely","chinese":"仔細觀察"},{"id":"gloss:for:27:3","english":"borrow equipment","chinese":"借用器材"},{"id":"gloss:for:27:4","english":"creative activity","chinese":"創意活動"},{"id":"gloss:for:27:5","english":"learn about nature","chinese":"學習自然知識"}]},{"id":"arg:for:28","number":28,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"家長主動阻止以雀鳥作真人拍照道具 [家長責任][動物保護]","description":"誰負責／怎樣做：家長及同行成人在有人試圖捉鳥時先勸孩子放手、退後，必要時請場地職員協助。  作用／限制：成年人的即場引導可阻止繼續傷害；不要以暴力搶奪雀鳥或圍觀刺激。","glossary":[{"id":"gloss:for:28:1","english":"object for photos","chinese":"拍照道具"},{"id":"gloss:for:28:2","english":"ask a child to stop","chinese":"請孩子停止"},{"id":"gloss:for:28:3","english":"adult guidance","chinese":"成人指導"},{"id":"gloss:for:28:4","english":"stay calm","chinese":"保持冷靜"},{"id":"gloss:for:28:5","english":"get staff help","chinese":"尋求職員協助"}]},{"id":"arg:for:29","number":29,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"學校戶外考察前加入一分鐘野鳥禮儀 [校本教育][預防]","description":"誰負責／怎樣做：學校和戶外教育機構在出發清單加入不餵飼、不觸碰、帶走垃圾三項守則。  作用／限制：讓守規則成為校外學習一部分；校方不能保證每位家庭遊客已接受教育。","glossary":[{"id":"gloss:for:29:1","english":"school trip","chinese":"學校考察"},{"id":"gloss:for:29:2","english":"field visit","chinese":"戶外參觀"},{"id":"gloss:for:29:3","english":"group rules","chinese":"團體守則"},{"id":"gloss:for:29:4","english":"take litter home","chinese":"帶走垃圾"},{"id":"gloss:for:29:5","english":"outdoor learning","chinese":"戶外學習"}]},{"id":"arg:for:30","number":30,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"以家庭遊戲卡教孩子辨識安全與不安全行為 [兒童教育][活動替代]","description":"誰負責／怎樣做：旅發局可與教育團體提供免費圖卡，讓孩子選出「遠距拍照」「撒糧」「抱鳥」的不同後果。  作用／限制：用參與式學習代替訓斥；答案須與實際法律及衞生建議一致。","glossary":[{"id":"gloss:for:30:1","english":"learning game","chinese":"學習遊戲"},{"id":"gloss:for:30:2","english":"picture card","chinese":"圖像卡"},{"id":"gloss:for:30:3","english":"safe action","chinese":"安全行為"},{"id":"gloss:for:30:4","english":"make a choice","chinese":"作出選擇"},{"id":"gloss:for:30:5","english":"explain the answer","chinese":"解釋答案"}]},{"id":"arg:for:31","number":31,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"對涉事兒童採取尊重而不公開羞辱的處理 [程序公平][兒童保障]","description":"誰負責／怎樣做：前線職員先制止有風險的行為、尋找同行成人並記錄必要事實；涉嫌違法交依法有權的部門處理。  作用／限制：保護兒童尊嚴與程序公平；不能以網上「人肉搜尋」代替調查。","glossary":[{"id":"gloss:for:31:1","english":"respect children","chinese":"尊重兒童"},{"id":"gloss:for:31:2","english":"private talk","chinese":"私下交談"},{"id":"gloss:for:31:3","english":"adult support","chinese":"成人支援"},{"id":"gloss:for:31:4","english":"fair process","chinese":"公平程序"},{"id":"gloss:for:31:5","english":"avoid public shame","chinese":"避免公開羞辱"}]},{"id":"arg:for:32","number":32,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"教育同行成人不要以動物掙扎為娛樂 [教育][動物保護]","description":"誰負責／怎樣做：動物福利團體與導遊在家長短講中說明羽毛脫落、驚嚇及不當抓握可能造成風險，並建議改拍自然景觀。  作用／限制：同時處理拍照者和拍照協助者的行為；不憑一段影片診斷實際傷勢。","glossary":[{"id":"gloss:for:32:1","english":"bird movement","chinese":"雀鳥動作"},{"id":"gloss:for:32:2","english":"rough handling","chinese":"粗暴抓握"},{"id":"gloss:for:32:3","english":"animal stress","chinese":"動物受驚"},{"id":"gloss:for:32:4","english":"safe photo","chinese":"安全照片"},{"id":"gloss:for:32:5","english":"change the activity","chinese":"改變活動方式"}]},{"id":"arg:for:33","number":33,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"由青少年義工設計同齡人喜歡的「不餵鳥」創意海報 [公眾參與][教育]","description":"誰負責／怎樣做：學校、青年中心與康文署舉辦小型設計活動，評選後在獲批准場地展示。  作用／限制：增強年輕人的參與感；海報必須提供正確規則，而非嘲弄遊客。","glossary":[{"id":"gloss:for:33:1","english":"young volunteers","chinese":"青年義工"},{"id":"gloss:for:33:2","english":"poster design","chinese":"海報設計"},{"id":"gloss:for:33:3","english":"creative message","chinese":"創意訊息"},{"id":"gloss:for:33:4","english":"school project","chinese":"學校項目"},{"id":"gloss:for:33:5","english":"respect visitors","chinese":"尊重遊客"}]},{"id":"arg:for:34","number":34,"angle":"C｜家庭、兒童、教育與無接觸拍照","title":"為有特殊學習需要的家庭提供圖像指引 [無障礙][兒童保障]","description":"誰負責／怎樣做：康文署與特殊教育及社福團體調整圖片大小和句子長度，方便不同能力兒童理解保持距離。  作用／限制：改善真正的資訊可達性；不應假定某類兒童更容易違規。","glossary":[{"id":"gloss:for:34:1","english":"visual guide","chinese":"視覺指引"},{"id":"gloss:for:34:2","english":"different needs","chinese":"不同需要"},{"id":"gloss:for:34:3","english":"simple pictures","chinese":"簡單圖片"},{"id":"gloss:for:34:4","english":"easy instructions","chinese":"易明指示"},{"id":"gloss:for:34:5","english":"include everyone","chinese":"照顧所有人"}]},{"id":"arg:for:35","number":35,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"把巡查集中在有實際證據的餵飼黑點 [巡查][資源分配]","description":"誰負責／怎樣做：漁護署與康文署以1823投訴、現場觀察、鳥群聚集和鳥糞情況，選出需要加強處理的泳灘位置。  作用／限制：用相同準則分配有限人手；單次網上影片不足以代表全年問題。","glossary":[{"id":"gloss:for:35:1","english":"problem area","chinese":"問題地點"},{"id":"gloss:for:35:2","english":"risk level","chinese":"風險程度"},{"id":"gloss:for:35:3","english":"local reports","chinese":"地區報告"},{"id":"gloss:for:35:4","english":"site check","chinese":"現場檢查"},{"id":"gloss:for:35:5","english":"limited staff","chinese":"有限人手"}]},{"id":"arg:for:36","number":36,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"採短時段機動巡查而非全天駐守 [時間管理][巡查]","description":"誰負責／怎樣做：康文署獲委任人員在周末旅遊團抵達及下午聚集時段巡查，漁護署按情報支援特別行動。  作用／限制：把人員放在違規較可能發生時；時間安排應定期改變以防被刻意避開。","glossary":[{"id":"gloss:for:36:1","english":"short patrol","chinese":"短時巡查"},{"id":"gloss:for:36:2","english":"peak hours","chinese":"高峰時間"},{"id":"gloss:for:36:3","english":"change shifts","chinese":"調整更次"},{"id":"gloss:for:36:4","english":"use staff wisely","chinese":"善用人手"},{"id":"gloss:for:36:5","english":"site visits","chinese":"實地巡查"}]},{"id":"arg:for:37","number":37,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"把泳灘管理與法定執法角色寫成雙層流程 [培訓][程序公平]","description":"誰負責／怎樣做：康文署一般場地員工可提示及通報；只有適用及獲委任的執法人員按現行法例調查及處理。  作用／限制：避免普通清潔員或救生員被誤要求開罰單；各自權限須在值勤卡上清楚。","glossary":[{"id":"gloss:for:37:1","english":"staff role","chinese":"員工角色"},{"id":"gloss:for:37:2","english":"legal powers","chinese":"法定權力"},{"id":"gloss:for:37:3","english":"report a case","chinese":"通報個案"},{"id":"gloss:for:37:4","english":"clear duties","chinese":"清晰職責"},{"id":"gloss:for:37:5","english":"proper action","chinese":"恰當行動"}]},{"id":"arg:for:38","number":38,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"在多次發生同類事件時安排漁護署與康文署聯合行動 [合作][執法]","description":"誰負責／怎樣做：漁護署可提供法例及鳥類知識，康文署提供泳灘現場動線與管理資料，雙方按需要排班。  作用／限制：以聯合行動處理較複雜黑點；不是每一次餵飼都要召集多部門。","glossary":[{"id":"gloss:for:38:1","english":"joint visit","chinese":"聯合巡查"},{"id":"gloss:for:38:2","english":"share information","chinese":"分享資料"},{"id":"gloss:for:38:3","english":"work together","chinese":"合作"},{"id":"gloss:for:38:4","english":"special patrol","chinese":"特別巡查"},{"id":"gloss:for:38:5","english":"clear task","chinese":"清晰任務"}]},{"id":"arg:for:39","number":39,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"只在跨越泳灘管理邊界時與食環署交接 [跨部門合作][資源分配]","description":"誰負責／怎樣做：康文署處理其泳灘內問題，食環署依自身管轄處理毗鄰食物及公眾環境衞生，雙方建立轉介聯絡點。  作用／限制：防止因「這地方不歸我管」而延誤；也避免同一位置兩隊重複巡查。","glossary":[{"id":"gloss:for:39:1","english":"area boundary","chinese":"區域界線"},{"id":"gloss:for:39:2","english":"shared work","chinese":"共同工作"},{"id":"gloss:for:39:3","english":"nearby street","chinese":"附近街道"},{"id":"gloss:for:39:4","english":"avoid overlap","chinese":"避免重複"},{"id":"gloss:for:39:5","english":"contact person","chinese":"聯絡人"}]},{"id":"arg:for:40","number":40,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"向房屋署借鑑屋邨禁餵經驗而不借錯職權 [部門合作][培訓]","description":"誰負責／怎樣做：漁護署在跨部門工作組分享房屋署屋邨黑點標示、執法時間等經驗，由康文署按泳灘條件改用。  作用／限制：重用已有經驗節省設計成本；房屋署不因此成為淺水灣泳灘的主責機關。","glossary":[{"id":"gloss:for:40:1","english":"learn from others","chinese":"向他人學習"},{"id":"gloss:for:40:2","english":"housing estate","chinese":"公共屋邨"},{"id":"gloss:for:40:3","english":"useful ideas","chinese":"實用做法"},{"id":"gloss:for:40:4","english":"adapt the plan","chinese":"調整方案"},{"id":"gloss:for:40:5","english":"different setting","chinese":"不同場景"}]},{"id":"arg:for:41","number":41,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"將「目擊疑似餵飼」與「證據足以採取行動」分開 [執法][程序公平]","description":"誰負責／怎樣做：獲委任執法人員按法律記錄時間、地點及可見行為，核實是否涉及實際餵飼，再採取合適程序。  作用／限制：保障公平並減少爭議；鳥隻靠近旅客不等於旅客一定餵飼。","glossary":[{"id":"gloss:for:41:1","english":"check the facts","chinese":"核實事實"},{"id":"gloss:for:41:2","english":"actual action","chinese":"實際行為"},{"id":"gloss:for:41:3","english":"fair decision","chinese":"公平決定"},{"id":"gloss:for:41:4","english":"possible mistake","chinese":"可能誤判"},{"id":"gloss:for:41:5","english":"clear record","chinese":"清楚紀錄"}]},{"id":"arg:for:42","number":42,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"執法當場提供簡明語言解釋與書面資料 [處罰][程序公平][資訊提醒]","description":"誰負責／怎樣做：獲委任執法人員依法發出通知書時，同時提供可取得的繁簡中文、英文求助及程序資訊。  作用／限制：讓遊客理解下一步而非因語言差異失去公平；不得隨意承諾可豁免罰款。","glossary":[{"id":"gloss:for:42:1","english":"written notice","chinese":"書面通知"},{"id":"gloss:for:42:2","english":"understand the rule","chinese":"理解規則"},{"id":"gloss:for:42:3","english":"language help","chinese":"語言協助"},{"id":"gloss:for:42:4","english":"next step","chinese":"下一步"},{"id":"gloss:for:42:5","english":"legal process","chinese":"法律程序"}]},{"id":"arg:for:43","number":43,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"將預防勸導與違規後執法清楚分開 [教育][執法][處罰]","description":"誰負責／怎樣做：康文署在入口先做公眾教育；對已發現的非法餵飼，獲授權人員按自2024年9月起的現行安排依法處理。  作用／限制：避免錯教「首次只會警告」；亦保留在事前友善提醒的空間。","glossary":[{"id":"gloss:for:43:1","english":"prevent problems","chinese":"預防問題"},{"id":"gloss:for:43:2","english":"give a reminder","chinese":"作出提醒"},{"id":"gloss:for:43:3","english":"break the rule","chinese":"違反規則"},{"id":"gloss:for:43:4","english":"official action","chinese":"官方行動"},{"id":"gloss:for:43:5","english":"different stages","chinese":"不同階段"}]},{"id":"arg:for:44","number":44,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"投訴先按「正在發生」或「事後影片」分流 [案件分流][公共服務]","description":"誰負責／怎樣做：1823把即時目擊、事後片段及清潔投訴分開轉介，康文署與漁護署按風險決定跟進優先次序。  作用／限制：減少多部門收到同一堆資料；影片仍要核對時地與真偽。","glossary":[{"id":"gloss:for:44:1","english":"live report","chinese":"即時報告"},{"id":"gloss:for:44:2","english":"old video","chinese":"過往影片"},{"id":"gloss:for:44:3","english":"sort cases","chinese":"分類個案"},{"id":"gloss:for:44:4","english":"urgent case","chinese":"緊急個案"},{"id":"gloss:for:44:5","english":"follow-up action","chinese":"跟進行動"}]},{"id":"arg:for:45","number":45,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"遇現場威脅或暴力才按需要請警方支援 [執法][人員安全]","description":"誰負責／怎樣做：康文署場地職員如面對恐嚇或衝突，應離開危險位置並通知警方；平常禁餵問題先走合適部門程序。  作用／限制：保護前線人員並避免把簡單告示工作警務化；警方仍依個案與權力處理。","glossary":[{"id":"gloss:for:45:1","english":"staff safety","chinese":"員工安全"},{"id":"gloss:for:45:2","english":"call the police","chinese":"聯絡警方"},{"id":"gloss:for:45:3","english":"serious threat","chinese":"嚴重威脅"},{"id":"gloss:for:45:4","english":"stay safe","chinese":"保持安全"},{"id":"gloss:for:45:5","english":"avoid fighting","chinese":"避免打鬥"}]},{"id":"arg:for:46","number":46,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"依行為而非口音或旅行團外觀決定巡查 [平等][程序公平]","description":"誰負責／怎樣做：各部門以客觀行為、時間及地點作依據，不對特定國籍、語言或年齡群體預設違規。  作用／限制：提高執法可信度；也避免忽略本地居民的非法餵飼。","glossary":[{"id":"gloss:for:46:1","english":"same rules for all","chinese":"人人適用同一規則"},{"id":"gloss:for:46:2","english":"fair treatment","chinese":"公平對待"},{"id":"gloss:for:46:3","english":"no unfair bias","chinese":"沒有不公平偏見"},{"id":"gloss:for:46:4","english":"watch actions","chinese":"觀察行為"},{"id":"gloss:for:46:5","english":"local and foreign visitors","chinese":"本地及外地遊客"}]},{"id":"arg:for:47","number":47,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"為被錯誤識別的人提供簡明查詢與覆核指引 [程序公平][資訊公開]","description":"誰負責／怎樣做：相關執法部門清楚告知法定通知書上的查詢、爭議處理和適用程序，而非由場地員工自行撤銷處分。  作用／限制：減少誤會及不合理投訴成本；必須按法律既有程序作決定。","glossary":[{"id":"gloss:for:47:1","english":"ask a question","chinese":"提出查詢"},{"id":"gloss:for:47:2","english":"check a decision","chinese":"覆核決定"},{"id":"gloss:for:47:3","english":"wrong report","chinese":"錯誤報告"},{"id":"gloss:for:47:4","english":"supporting facts","chinese":"相關事實"},{"id":"gloss:for:47:5","english":"right process","chinese":"正確程序"}]},{"id":"arg:for:48","number":48,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"不以罰款數量作前線員工的唯一績效 [評估][誘因]","description":"誰負責／怎樣做：漁護署、康文署同時衡量違規觀察率、清潔負擔、遊客理解及投訴處理，不設定必須開單的數量目標。  作用／限制：避免為求數字而過度執法；又可監察是否完全沒有跟進。","glossary":[{"id":"gloss:for:48:1","english":"performance measure","chinese":"表現指標"},{"id":"gloss:for:48:2","english":"fair target","chinese":"合理目標"},{"id":"gloss:for:48:3","english":"number of cases","chinese":"個案數量"},{"id":"gloss:for:48:4","english":"better results","chinese":"更佳結果"},{"id":"gloss:for:48:5","english":"avoid pressure","chinese":"避免壓力"}]},{"id":"arg:for:49","number":49,"angle":"D｜有限人手下的巡查、執法與程序公平","title":"定期比較假日和非假日巡查效果 [評估][資源配置]","description":"誰負責／怎樣做：漁護署與康文署在相近時段記錄每百名遊客的疑似餵飼情況，分辨人流增加與行為增加。  作用／限制：防止只看總投訴數便錯分配人手；抽樣方法與誤差要公開。","glossary":[{"id":"gloss:for:49:1","english":"weekend pattern","chinese":"周末模式"},{"id":"gloss:for:49:2","english":"weekday visit","chinese":"平日到訪"},{"id":"gloss:for:49:3","english":"fair comparison","chinese":"公平比較"},{"id":"gloss:for:49:4","english":"visitor numbers","chinese":"遊客人數"},{"id":"gloss:for:49:5","english":"check results","chinese":"檢查結果"}]},{"id":"arg:for:50","number":50,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"為餵飼、抓鳥與可能造成痛苦的行為建立不同處理路徑 [動物保護][程序公平]","description":"誰負責／怎樣做：漁護署與警方分別核實相關行為在第170章或第169章下是否符合法律要件，康文署保存現場基本資料。  作用／限制：避免錯把禁餵罰款直接套到所有捉鳥行為；調查前不宣布有人已犯虐待罪。","glossary":[{"id":"gloss:for:50:1","english":"different actions","chinese":"不同行為"},{"id":"gloss:for:50:2","english":"animal harm","chinese":"動物受害"},{"id":"gloss:for:50:3","english":"legal check","chinese":"法律核實"},{"id":"gloss:for:50:4","english":"clear evidence","chinese":"清楚證據"},{"id":"gloss:for:50:5","english":"separate cases","chinese":"分開處理個案"}]},{"id":"arg:for:51","number":51,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"設立發現疑似受傷野鳥的簡短轉介流程 [動物保護][公共服務]","description":"誰負責／怎樣做：康文署職員遠距記錄雀鳥是否無法站立、持續流血或飛行困難，按漁護署指引聯絡合適救援渠道。  作用／限制：減少圍觀者反覆抓起檢查；前線不應自行診斷或治療。","glossary":[{"id":"gloss:for:51:1","english":"injured bird","chinese":"受傷雀鳥"},{"id":"gloss:for:51:2","english":"keep a distance","chinese":"保持距離"},{"id":"gloss:for:51:3","english":"call for help","chinese":"致電求助"},{"id":"gloss:for:51:4","english":"trained rescue","chinese":"受訓救援"},{"id":"gloss:for:51:5","english":"do not handle","chinese":"不要自行觸碰"}]},{"id":"arg:for:52","number":52,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"由合資格動物救援者而非遊客處理受傷雀鳥 [動物保護][合作]","description":"誰負責／怎樣做：漁護署與愛護動物協會及其他合資格救援團體協調適用轉介資料，確保救援者按個案安全處理。  作用／限制：降低二次傷害與接觸風險；民間團體資源有限，不應當作免費常駐政府人手。","glossary":[{"id":"gloss:for:52:1","english":"qualified help","chinese":"合資格協助"},{"id":"gloss:for:52:2","english":"rescue service","chinese":"救援服務"},{"id":"gloss:for:52:3","english":"animal first aid","chinese":"動物急救"},{"id":"gloss:for:52:4","english":"safe handling","chinese":"安全處理"},{"id":"gloss:for:52:5","english":"limited support","chinese":"有限支援"}]},{"id":"arg:for:53","number":53,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"不讓普通場地職員為趕走鴿群而追捕牠們 [員工培訓][動物保護]","description":"誰負責／怎樣做：康文署寫明職員以清理食物來源及提醒遊客為主；涉及捉鳥、移走受傷動物時交專業人員。  作用／限制：避免由錯誤處理衍生新傷害；也維持工作安全。","glossary":[{"id":"gloss:for:53:1","english":"chase birds","chinese":"追逐雀鳥"},{"id":"gloss:for:53:2","english":"remove food","chinese":"清走食物"},{"id":"gloss:for:53:3","english":"staff instructions","chinese":"員工指示"},{"id":"gloss:for:53:4","english":"avoid injuries","chinese":"避免受傷"},{"id":"gloss:for:53:5","english":"expert support","chinese":"專業支援"}]},{"id":"arg:for:54","number":54,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"對捉鳥合照行為提供替代拍照方式 [教育][動物保護]","description":"誰負責／怎樣做：康文署、導遊及商戶引導遊客拍攝自然飛翔的鴿子或沙灘景色，而不是把鳥抓起供擺姿勢。  作用／限制：保留拍照樂趣並減少驚嚇；不鼓勵靠餵食令鳥隻集中。","glossary":[{"id":"gloss:for:54:1","english":"natural photo","chinese":"自然照片"},{"id":"gloss:for:54:2","english":"birds in flight","chinese":"飛翔雀鳥"},{"id":"gloss:for:54:3","english":"without touching","chinese":"不需觸碰"},{"id":"gloss:for:54:4","english":"safe memory","chinese":"安全回憶"},{"id":"gloss:for:54:5","english":"enjoy nature","chinese":"享受大自然"}]},{"id":"arg:for:55","number":55,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"為動物福利志願者訂明「只教育、不自行執法」 [合作][程序公平]","description":"誰負責／怎樣做：自然團體義工可示範遠距觀鳥與轉介受傷雀鳥，不可強迫查身分、扣留遊客或沒收食物。  作用／限制：善用公民力量又不擴張權力；須訓練面對衝突時退後求助。","glossary":[{"id":"gloss:for:55:1","english":"volunteer role","chinese":"義工角色"},{"id":"gloss:for:55:2","english":"give advice","chinese":"提供建議"},{"id":"gloss:for:55:3","english":"legal limits","chinese":"法律界線"},{"id":"gloss:for:55:4","english":"ask staff for help","chinese":"向職員求助"},{"id":"gloss:for:55:5","english":"respect others","chinese":"尊重他人"}]},{"id":"arg:for:56","number":56,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"拒絕把毒餌或傷害性驅鳥方法當作便宜捷徑 [動物保護][環境管理]","description":"誰負責／怎樣做：康文署與漁護署先研究減少食物殘渣、自然覓食和人群接觸，任何特殊控制措施都需專業與法律評估。  作用／限制：保護其他鳥類、寵物和孩童；不能因人手不足便採取不人道方法。","glossary":[{"id":"gloss:for:56:1","english":"poison bait","chinese":"毒餌"},{"id":"gloss:for:56:2","english":"safe methods","chinese":"安全方法"},{"id":"gloss:for:56:3","english":"other animals","chinese":"其他動物"},{"id":"gloss:for:56:4","english":"avoid harm","chinese":"避免傷害"},{"id":"gloss:for:56:5","english":"long-term plan","chinese":"長遠計劃"}]},{"id":"arg:for:57","number":57,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"以專業觀察而不是社交影片推斷雀鳥傷勢 [評估][動物保護]","description":"誰負責／怎樣做：漁護署可在必要時請合資格人員評估行為對雀鳥的影響，並只對已取得的資料作結論。  作用／限制：羽毛掉落值得關注，但不等於已證實骨折或患病。","glossary":[{"id":"gloss:for:57:1","english":"check for injury","chinese":"檢查傷勢"},{"id":"gloss:for:57:2","english":"expert opinion","chinese":"專業意見"},{"id":"gloss:for:57:3","english":"video evidence","chinese":"影片證據"},{"id":"gloss:for:57:4","english":"unknown condition","chinese":"未知情況"},{"id":"gloss:for:57:5","english":"careful judgment","chinese":"審慎判斷"}]},{"id":"arg:for:58","number":58,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"將不接觸動物的規則延伸至其他景點 [教育][跨地區合作]","description":"誰負責／怎樣做：漁護署及旅發局把「不餵、不捉、不追逐」原則用於其他野鳥或野生動物出沒的旅遊點，並按物種調整資訊。  作用／限制：建立一致旅遊禮儀；不能把所有動物的法例或風險當作完全相同。","glossary":[{"id":"gloss:for:58:1","english":"other attractions","chinese":"其他景點"},{"id":"gloss:for:58:2","english":"respect wildlife","chinese":"尊重野生動物"},{"id":"gloss:for:58:3","english":"different species","chinese":"不同物種"},{"id":"gloss:for:58:4","english":"travel habits","chinese":"旅遊習慣"},{"id":"gloss:for:58:5","english":"local rules","chinese":"本地規則"}]},{"id":"arg:for:59","number":59,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"先確認雀鳥身分及法定分類才討論捕捉罪名 [程序公平][動物保護]","description":"誰負責／怎樣做：漁護署依法判斷個案涉及的雀鳥是否落入相關條文保護範圍，警方在有足夠證據時協助調查。  作用／限制：禁餵野鴿不自動等於每一種抓鴿方式構成同一罪名；法律用詞須精確。","glossary":[{"id":"gloss:for:59:1","english":"bird type","chinese":"雀鳥種類"},{"id":"gloss:for:59:2","english":"legal status","chinese":"法律地位"},{"id":"gloss:for:59:3","english":"check the law","chinese":"核對法律"},{"id":"gloss:for:59:4","english":"case details","chinese":"個案細節"},{"id":"gloss:for:59:5","english":"avoid assumptions","chinese":"避免假設"}]},{"id":"arg:for:60","number":60,"angle":"E｜野鴿福利、捕捉行為及專業救援","title":"考慮在公眾教育中加入野鳥遇困時的求救方法 [動物保護][教育]","description":"誰負責／怎樣做：漁護署、康文署、動物福利團體在告示提示遊客發現生病、受傷或死亡雀鳥時保持距離及使用官方求助途徑。  作用／限制：避免熱心遊客自行帶走野鳥；不同情況應按專業指示處理。","glossary":[{"id":"gloss:for:60:1","english":"sick bird","chinese":"患病雀鳥"},{"id":"gloss:for:60:2","english":"dead bird","chinese":"死亡雀鳥"},{"id":"gloss:for:60:3","english":"keep away","chinese":"遠離"},{"id":"gloss:for:60:4","english":"report the problem","chinese":"報告問題"},{"id":"gloss:for:60:5","english":"proper help","chinese":"適當協助"}]},{"id":"arg:for:61","number":61,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"把高峰後清理食物殘渣納入固定工作次序 [衞生][時間管理]","description":"誰負責／怎樣做：康文署安排現有清潔承辦商在旅遊巴集中離開後先處理有食物殘渣的區域，再進行一般沙灘清潔。  作用／限制：減少再吸引鴿群；高峰後清潔不能替代即場制止非法餵飼。","glossary":[{"id":"gloss:for:61:1","english":"food scraps","chinese":"食物殘渣"},{"id":"gloss:for:61:2","english":"clean-up time","chinese":"清理時間"},{"id":"gloss:for:61:3","english":"after the crowd","chinese":"人群離開後"},{"id":"gloss:for:61:4","english":"remove leftovers","chinese":"清走剩食"},{"id":"gloss:for:61:5","english":"clean beach","chinese":"清潔沙灘"}]},{"id":"arg:for:62","number":62,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"在小食店附近使用有蓋垃圾桶 [衞生][設施改善]","description":"誰負責／怎樣做：康文署與場地小食店研究在允許的地方放有蓋而易使用的垃圾桶，避免野鴿直接啄到剩食。  作用／限制：減少餵飼以外的食物來源；垃圾桶位置不可阻路或吸引其他害蟲。","glossary":[{"id":"gloss:for:62:1","english":"covered bin","chinese":"有蓋垃圾桶"},{"id":"gloss:for:62:2","english":"food waste","chinese":"食物廢物"},{"id":"gloss:for:62:3","english":"near the shop","chinese":"店舖附近"},{"id":"gloss:for:62:4","english":"keep pests away","chinese":"避免引來蟲鼠"},{"id":"gloss:for:62:5","english":"easy to use","chinese":"容易使用"}]},{"id":"arg:for:63","number":63,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"小食店在售賣外賣時提醒顧客保管食物 [商戶合作][衞生]","description":"誰負責／怎樣做：場地餐飲營辦者可在收據或取餐處貼提醒，請顧客不要把零食撒到地上或故意餵鳥。  作用／限制：從食物來源減少聚集；不會要求食肆職員充當巡邏員。","glossary":[{"id":"gloss:for:63:1","english":"takeaway food","chinese":"外賣食物"},{"id":"gloss:for:63:2","english":"food counter","chinese":"取餐處"},{"id":"gloss:for:63:3","english":"shop reminder","chinese":"商戶提示"},{"id":"gloss:for:63:4","english":"keep food covered","chinese":"把食物蓋好"},{"id":"gloss:for:63:5","english":"avoid litter","chinese":"避免亂丟垃圾"}]},{"id":"arg:for:64","number":64,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"把鳥糞重點清潔和一般垃圾分開安排 [衞生][人員保護]","description":"誰負責／怎樣做：康文署要求承辦商使用合適清潔方法及防護裝備處理鳥糞較多的路段，避免不當掃起塵埃。  作用／限制：既保護遊客也保護清潔工；不靠一般遊客自行清理污染物。","glossary":[{"id":"gloss:for:64:1","english":"bird droppings","chinese":"鳥糞"},{"id":"gloss:for:64:2","english":"cleaning workers","chinese":"清潔工人"},{"id":"gloss:for:64:3","english":"protective clothing","chinese":"防護衣物"},{"id":"gloss:for:64:4","english":"safe cleaning","chinese":"安全清潔"},{"id":"gloss:for:64:5","english":"avoid dust","chinese":"避免塵埃"}]},{"id":"arg:for:65","number":65,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"檢查洗手設施有沒有肥皂及清水 [衞生][公共服務]","description":"誰負責／怎樣做：康文署在泳灘公共洗手間加強日常檢查，將肥皂、供水及水龍頭故障列為即時報修項目。  作用／限制：讓意外接觸鳥隻或環境的人能立即清潔；手部衞生不能取代避免觸碰。","glossary":[{"id":"gloss:for:65:1","english":"soap and water","chinese":"肥皂與清水"},{"id":"gloss:for:65:2","english":"wash your hands","chinese":"洗手"},{"id":"gloss:for:65:3","english":"working tap","chinese":"正常水龍頭"},{"id":"gloss:for:65:4","english":"public toilet","chinese":"公廁"},{"id":"gloss:for:65:5","english":"check supplies","chinese":"檢查物資"}]},{"id":"arg:for:66","number":66,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"在雀鳥聚集點附近設清晰洗手方向指示 [資訊提醒][衞生]","description":"誰負責／怎樣做：康文署在合理位置加簡單路牌，指向現有洗手間，而不是另建大量洗手站。  作用／限制：使用既有設施降低成本；路牌須避免鼓勵遊客靠近雀鳥。","glossary":[{"id":"gloss:for:66:1","english":"washing area","chinese":"洗手位置"},{"id":"gloss:for:66:2","english":"direction sign","chinese":"方向指示"},{"id":"gloss:for:66:3","english":"nearby toilet","chinese":"附近洗手間"},{"id":"gloss:for:66:4","english":"clean hands","chinese":"清潔雙手"},{"id":"gloss:for:66:5","english":"low-cost step","chinese":"低成本措施"}]},{"id":"arg:for:67","number":67,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"避免將鳥糞污染與禽流感確診混為一談 [健康教育][資訊公開]","description":"誰負責／怎樣做：衞生署衞生防護中心提供簡短科學資訊，由康文署與旅遊業轉載「避免接觸、洗手、按需要求醫」等建議。  作用／限制：降低不必要恐慌；不可說新聞個案已出現禽流感。","glossary":[{"id":"gloss:for:67:1","english":"health risk","chinese":"健康風險"},{"id":"gloss:for:67:2","english":"confirmed illness","chinese":"已確診疾病"},{"id":"gloss:for:67:3","english":"health advice","chinese":"健康建議"},{"id":"gloss:for:67:4","english":"stay informed","chinese":"掌握資訊"},{"id":"gloss:for:67:5","english":"avoid panic","chinese":"避免恐慌"}]},{"id":"arg:for:68","number":68,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"按風險安排鳥類疾病監察而非每宗餵飼都抽驗 [公共衞生][資源分配]","description":"誰負責／怎樣做：漁護署依其動物健康監察職能評估何時需要現場檢查或採樣，並按專業程序通知相關部門。  作用／限制：節省檢測與人力；無檢測結果不代表風險為零或已發生感染。","glossary":[{"id":"gloss:for:68:1","english":"health testing","chinese":"健康檢測"},{"id":"gloss:for:68:2","english":"sample collection","chinese":"樣本收集"},{"id":"gloss:for:68:3","english":"expert decision","chinese":"專業決定"},{"id":"gloss:for:68:4","english":"test results","chinese":"檢測結果"},{"id":"gloss:for:68:5","english":"use resources wisely","chinese":"善用資源"}]},{"id":"arg:for:69","number":69,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"清潔員收到疑似受傷或死亡鳥隻資訊時先轉介 [員工培訓][衞生]","description":"誰負責／怎樣做：清潔承辦商收到現場報告，應先按康文署及漁護署程序處理，避免自行徒手拾起雀鳥或屍體。  作用／限制：保障清潔員健康與動物處理安全；不要把救護任務強加給非合資格員工。","glossary":[{"id":"gloss:for:69:1","english":"cleaning team","chinese":"清潔團隊"},{"id":"gloss:for:69:2","english":"report safely","chinese":"安全通報"},{"id":"gloss:for:69:3","english":"dead animal","chinese":"動物屍體"},{"id":"gloss:for:69:4","english":"protect workers","chinese":"保護工人"},{"id":"gloss:for:69:5","english":"trained staff","chinese":"受訓人員"}]},{"id":"arg:for:70","number":70,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"在鄰近街道與泳灘交界設垃圾責任線 [部門合作][衞生]","description":"誰負責／怎樣做：康文署、食環署與有關物業管理人先畫清各自清潔範圍，再設快速通知方法處理跨界食物殘渣。  作用／限制：防止餵飼食物被風帶出管理範圍後無人跟進；不需要重建整套政府架構。","glossary":[{"id":"gloss:for:70:1","english":"street cleaning","chinese":"街道清潔"},{"id":"gloss:for:70:2","english":"beach area","chinese":"泳灘範圍"},{"id":"gloss:for:70:3","english":"shared boundary","chinese":"共同邊界"},{"id":"gloss:for:70:4","english":"quick contact","chinese":"快速聯絡"},{"id":"gloss:for:70:5","english":"clear responsibility","chinese":"明確責任"}]},{"id":"arg:for:71","number":71,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"用固定樣區記錄鳥糞與垃圾變化 [評估][衞生]","description":"誰負責／怎樣做：康文署挑選數個具有代表性的地面位置，每周以同一時段記錄污染程度，而不以有多少照片作判斷。  作用／限制：可檢驗措施是否有效；須考慮天氣與人流變化。","glossary":[{"id":"gloss:for:71:1","english":"regular checks","chinese":"定期檢查"},{"id":"gloss:for:71:2","english":"same location","chinese":"相同地點"},{"id":"gloss:for:71:3","english":"amount of waste","chinese":"廢物數量"},{"id":"gloss:for:71:4","english":"weekly change","chinese":"每周變化"},{"id":"gloss:for:71:5","english":"measure progress","chinese":"衡量進展"}]},{"id":"arg:for:72","number":72,"angle":"F｜環境衞生、食物殘渣和公共健康","title":"把清潔工時和重複污染納入成本分析 [財務安排][評估]","description":"誰負責／怎樣做：康文署在不披露員工個資的前提下，比較新增清潔工時與被避免的污染情況，決定是否需要改變垃圾設施。  作用／限制：幫助在有限預算中選工具；不應因成本壓力令員工無薪加班。","glossary":[{"id":"gloss:for:72:1","english":"cleaning cost","chinese":"清潔成本"},{"id":"gloss:for:72:2","english":"working hours","chinese":"工作時數"},{"id":"gloss:for:72:3","english":"money saved","chinese":"節省金錢"},{"id":"gloss:for:72:4","english":"fair workload","chinese":"合理工作量"},{"id":"gloss:for:72:5","english":"better planning","chinese":"更佳規劃"}]},{"id":"arg:for:73","number":73,"angle":"G｜景點空間、設施及遊客體驗設計","title":"提供不用餵鳥也能拍得好照片的觀景點 [場地設計][旅遊體驗]","description":"誰負責／怎樣做：康文署與旅發局選取遠離鴿群的海景位置，標示適合拍照的方向與時段。  作用／限制：減少以撒糧召集鴿群作拍照道具的誘因；不阻擋其他正常遊客。","glossary":[{"id":"gloss:for:73:1","english":"photo spot","chinese":"拍照點"},{"id":"gloss:for:73:2","english":"sea view","chinese":"海景"},{"id":"gloss:for:73:3","english":"good background","chinese":"好背景"},{"id":"gloss:for:73:4","english":"safe distance","chinese":"安全距離"},{"id":"gloss:for:73:5","english":"visitor enjoyment","chinese":"遊客樂趣"}]},{"id":"arg:for:74","number":74,"angle":"G｜景點空間、設施及遊客體驗設計","title":"以海灘生態小知識牌替代餵鳥互動 [教育][場地設計]","description":"誰負責／怎樣做：康文署、漁護署與鳥類研究團體在主要觀景路線介紹常見海岸雀鳥及正確觀察距離。  作用／限制：讓「看見動物」成為學習體驗；物種介紹必須經專業核對。","glossary":[{"id":"gloss:for:74:1","english":"coastal birds","chinese":"海岸雀鳥"},{"id":"gloss:for:74:2","english":"learning board","chinese":"學習資訊板"},{"id":"gloss:for:74:3","english":"local nature","chinese":"本地自然"},{"id":"gloss:for:74:4","english":"interesting facts","chinese":"有趣知識"},{"id":"gloss:for:74:5","english":"observe birds","chinese":"觀察雀鳥"}]},{"id":"arg:for:75","number":75,"angle":"G｜景點空間、設施及遊客體驗設計","title":"移除容易積聚食物碎屑的角落設計 [衞生][場地改善]","description":"誰負責／怎樣做：康文署在例行維修時檢查椅下、檯邊和垃圾桶後方是否積食物殘渣，選容易清洗的物料替換。  作用／限制：減少無意間吸引鴿群；不需要大規模重建泳灘。","glossary":[{"id":"gloss:for:75:1","english":"food crumbs","chinese":"食物碎屑"},{"id":"gloss:for:75:2","english":"easy to clean","chinese":"容易清潔"},{"id":"gloss:for:75:3","english":"public bench","chinese":"公共長椅"},{"id":"gloss:for:75:4","english":"small repair","chinese":"小型維修"},{"id":"gloss:for:75:5","english":"keep food away","chinese":"清走食物"}]},{"id":"arg:for:76","number":76,"angle":"G｜景點空間、設施及遊客體驗設計","title":"在兒童遊樂區維持清楚的動物觀察界線 [兒童安全][場地設計]","description":"誰負責／怎樣做：康文署以矮標示或地面圖案提醒家長讓孩子遠距觀看鳥隻，不把鳥群引入遊樂區。  作用／限制：降低兒童追捉與鳥糞接觸風險；不得以高圍欄破壞暢通與沙灘空間。","glossary":[{"id":"gloss:for:76:1","english":"play area","chinese":"遊樂區"},{"id":"gloss:for:76:2","english":"ground marking","chinese":"地面標記"},{"id":"gloss:for:76:3","english":"child-friendly sign","chinese":"兒童友善告示"},{"id":"gloss:for:76:4","english":"keep a gap","chinese":"保持距離"},{"id":"gloss:for:76:5","english":"open space","chinese":"開放空間"}]},{"id":"arg:for:77","number":77,"angle":"G｜景點空間、設施及遊客體驗設計","title":"使用短期活動攤位作替代攝影道具 [旅遊體驗][誘因]","description":"誰負責／怎樣做：主辦方可在大型活動日擺放鳥類插畫或海灘造型拍照板，讓旅客與圖案合照而不接觸活鳥。  作用／限制：提供可分享的旅遊照片；避免製造一次性大量廢物。","glossary":[{"id":"gloss:for:77:1","english":"photo board","chinese":"拍照板"},{"id":"gloss:for:77:2","english":"bird picture","chinese":"鳥類圖片"},{"id":"gloss:for:77:3","english":"fun activity","chinese":"趣味活動"},{"id":"gloss:for:77:4","english":"live animal","chinese":"活生生動物"},{"id":"gloss:for:77:5","english":"reusable material","chinese":"可重用物料"}]},{"id":"arg:for:78","number":78,"angle":"G｜景點空間、設施及遊客體驗設計","title":"讓路牌不遮擋海景及無障礙通道 [無障礙][旅遊體驗]","description":"誰負責／怎樣做：康文署在放置禁餵提示牌前，檢查輪椅通道、盲道、沙灘入口及拍照視野。  作用／限制：兼顧公共教育與使用景點權利；不是放越多牌越好。","glossary":[{"id":"gloss:for:78:1","english":"wheelchair access","chinese":"輪椅通道"},{"id":"gloss:for:78:2","english":"clear path","chinese":"暢通路徑"},{"id":"gloss:for:78:3","english":"sea view","chinese":"海景"},{"id":"gloss:for:78:4","english":"sign position","chinese":"路牌位置"},{"id":"gloss:for:78:5","english":"shared space","chinese":"共享空間"}]},{"id":"arg:for:79","number":79,"angle":"G｜景點空間、設施及遊客體驗設計","title":"在鴿群高度集中的時段採柔性人流引導 [人流管理][動物保護]","description":"誰負責／怎樣做：康文署可讓職員以指示牌帶遊客使用附近其他觀景路線，避免一群人同時追逐雀鳥。  作用／限制：減少人鳥擠在同一角落；不得因一般鳥群出現便無限期封閉大片沙灘。","glossary":[{"id":"gloss:for:79:1","english":"crowd movement","chinese":"人流移動"},{"id":"gloss:for:79:2","english":"another route","chinese":"另一條路線"},{"id":"gloss:for:79:3","english":"guide people","chinese":"引導人群"},{"id":"gloss:for:79:4","english":"bird group","chinese":"鳥群"},{"id":"gloss:for:79:5","english":"avoid crowding","chinese":"避免擁擠"}]},{"id":"arg:for:80","number":80,"angle":"G｜景點空間、設施及遊客體驗設計","title":"評估現有欄杆及建築位置是否形成鳥糞落點 [設施檢討][衞生]","description":"誰負責／怎樣做：康文署在定期保養中檢查座位上方的安全與清潔問題；如考慮改善設計，先請漁護署評估是否影響鳥隻。  作用／限制：優化遊人使用空間；任何防鳥設施須安全及不傷鳥。","glossary":[{"id":"gloss:for:80:1","english":"public seating","chinese":"公共座位"},{"id":"gloss:for:80:2","english":"building edge","chinese":"建築邊緣"},{"id":"gloss:for:80:3","english":"safe design","chinese":"安全設計"},{"id":"gloss:for:80:4","english":"clean area","chinese":"潔淨區域"},{"id":"gloss:for:80:5","english":"bird-friendly","chinese":"對雀鳥友善的"}]},{"id":"arg:for:81","number":81,"angle":"G｜景點空間、設施及遊客體驗設計","title":"按季節更改觀鳥與清潔資訊位置 [時間管理][評估]","description":"誰負責／怎樣做：康文署根據不同月份鳥群活動和遊客路線的觀察，調整臨時路牌與清潔重點。  作用／限制：避免同一配置全年不變；不能只靠主觀印象推定季節原因。","glossary":[{"id":"gloss:for:81:1","english":"seasonal change","chinese":"季節變化"},{"id":"gloss:for:81:2","english":"monthly review","chinese":"每月檢討"},{"id":"gloss:for:81:3","english":"visitor route","chinese":"遊客路線"},{"id":"gloss:for:81:4","english":"move information","chinese":"調整資訊位置"},{"id":"gloss:for:81:5","english":"record changes","chinese":"記錄變化"}]},{"id":"arg:for:82","number":82,"angle":"G｜景點空間、設施及遊客體驗設計","title":"設遠觀雀鳥的簡易觀景框而非投餌區 [替代活動][動物保護]","description":"誰負責／怎樣做：康文署與自然教育團體試用不需近距接觸的取景框，讓家庭拍鳥群遠景。  作用／限制：將觀鳥需求轉成不打擾活動；裝置不可引導遊客走進鳥群中心。","glossary":[{"id":"gloss:for:82:1","english":"viewing frame","chinese":"取景框"},{"id":"gloss:for:82:2","english":"long-distance photo","chinese":"遠距照片"},{"id":"gloss:for:82:3","english":"watch quietly","chinese":"安靜觀察"},{"id":"gloss:for:82:4","english":"safe viewpoint","chinese":"安全觀景位置"},{"id":"gloss:for:82:5","english":"no feeding","chinese":"不餵飼"}]},{"id":"arg:for:83","number":83,"angle":"G｜景點空間、設施及遊客體驗設計","title":"讓不熟悉景點的人容易找到場地服務台 [公共服務][場地設計]","description":"誰負責／怎樣做：康文署在泳灘入口及網頁標明查詢位置、洗手間、求助方法，讓遊客遇上鳥群接近時知道找誰。  作用／限制：提高安全感與友善度；服務台不能提供臨床診斷或法定豁免。","glossary":[{"id":"gloss:for:83:1","english":"help desk","chinese":"服務台"},{"id":"gloss:for:83:2","english":"ask for directions","chinese":"查詢方向"},{"id":"gloss:for:83:3","english":"public service","chinese":"公共服務"},{"id":"gloss:for:83:4","english":"easy to find","chinese":"容易找到"},{"id":"gloss:for:83:5","english":"visitor support","chinese":"遊客支援"}]},{"id":"arg:for:84","number":84,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"為願意張貼官方禁餵資訊的商戶提供可重用素材 [非金錢誘因][合作]","description":"誰負責／怎樣做：漁護署和康文署製作電子版圖卡，供附近餐廳、小食店及酒店自願展示。  作用／限制：讓一個訊息在多個地方出現而減少印刷開支；不能強迫未屬相關合約的商戶承擔新法律責任。","glossary":[{"id":"gloss:for:84:1","english":"free materials","chinese":"免費素材"},{"id":"gloss:for:84:2","english":"shop window","chinese":"商店櫥窗"},{"id":"gloss:for:84:3","english":"shared message","chinese":"共同訊息"},{"id":"gloss:for:84:4","english":"save printing costs","chinese":"節省印刷費"},{"id":"gloss:for:84:5","english":"voluntary help","chinese":"自願協助"}]},{"id":"arg:for:85","number":85,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"於政府場地小食亭合約中清晰列出防殘食安排 [合約管理][衞生]","description":"誰負責／怎樣做：康文署在適用的新合約或續約條件中訂明垃圾桶清理、食物殘渣管理及通報方法。  作用／限制：把部分清潔責任落到最容易處理食物的經營者；不得無故追溯更改已訂合約。","glossary":[{"id":"gloss:for:85:1","english":"food stall","chinese":"食物攤檔"},{"id":"gloss:for:85:2","english":"service contract","chinese":"服務合約"},{"id":"gloss:for:85:3","english":"waste control","chinese":"廢物管理"},{"id":"gloss:for:85:4","english":"keep records","chinese":"保留紀錄"},{"id":"gloss:for:85:5","english":"fair terms","chinese":"公平條款"}]},{"id":"arg:for:86","number":86,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"鼓勵旅遊業採用「不接觸野生動物」遊程承諾 [自願守則][旅遊協作]","description":"誰負責／怎樣做：旅行社與導遊協會可自願加入不餵鳥、不誘拍抱鳥合照的旅遊承諾，旅監局提供正確資訊作參考。  作用／限制：建立業界共同做法；自願標誌不可冒稱政府核發安全認證。","glossary":[{"id":"gloss:for:86:1","english":"travel promise","chinese":"旅遊承諾"},{"id":"gloss:for:86:2","english":"responsible travel","chinese":"負責任旅遊"},{"id":"gloss:for:86:3","english":"group rules","chinese":"團體守則"},{"id":"gloss:for:86:4","english":"join a scheme","chinese":"參加計劃"},{"id":"gloss:for:86:5","english":"honest label","chinese":"真實標示"}]},{"id":"arg:for:87","number":87,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"將安全觀鳥活動加入酒店與景點套票 [商業誘因][旅遊設計]","description":"誰負責／怎樣做：酒店與旅遊營辦商可推出自然導賞或遠距觀鳥活動，替代以餵飼吸引鳥群的玩法。  作用／限制：讓遵守禁令仍有產品價值；活動價格要讓一般家庭負擔得起。","glossary":[{"id":"gloss:for:87:1","english":"tour package","chinese":"旅遊套票"},{"id":"gloss:for:87:2","english":"nature walk","chinese":"自然步行"},{"id":"gloss:for:87:3","english":"bird watching","chinese":"觀鳥"},{"id":"gloss:for:87:4","english":"family price","chinese":"家庭價格"},{"id":"gloss:for:87:5","english":"new experience","chinese":"新體驗"}]},{"id":"arg:for:88","number":88,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"讓附近店舖以優惠鼓勵自備水和減少垃圾 [經濟誘因][衞生]","description":"誰負責／怎樣做：商戶可自願在不影響經營的情況下提供可重用水樽補水等優惠，降低一次性食品包裝留在沙灘的機會。  作用／限制：減少垃圾與鴿群食源；優惠應由參與者自願承擔成本。","glossary":[{"id":"gloss:for:88:1","english":"refill a bottle","chinese":"補充水樽"},{"id":"gloss:for:88:2","english":"reuse a cup","chinese":"重用杯子"},{"id":"gloss:for:88:3","english":"small discount","chinese":"小額折扣"},{"id":"gloss:for:88:4","english":"less waste","chinese":"減少廢物"},{"id":"gloss:for:88:5","english":"shop offer","chinese":"商戶優惠"}]},{"id":"arg:for:89","number":89,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"贊助商資助小型教育活動但不得干預法例執行 [財務安排][合作]","description":"誰負責／怎樣做：地方商戶或贊助者可按透明安排提供海報與導賞材料，由康文署或合適主辦方控制內容。  作用／限制：減輕公帑壓力；贊助不能換取特殊放寬、商業獨佔或不公平曝光。","glossary":[{"id":"gloss:for:89:1","english":"local sponsor","chinese":"本地贊助者"},{"id":"gloss:for:89:2","english":"support education","chinese":"支持教育"},{"id":"gloss:for:89:3","english":"public money","chinese":"公帑"},{"id":"gloss:for:89:4","english":"fair access","chinese":"公平參與"},{"id":"gloss:for:89:5","english":"clear agreement","chinese":"清晰協議"}]},{"id":"arg:for:90","number":90,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"給清潔承辦商設「污染改善」而非「罰款數量」指標 [合約管理][評估]","description":"誰負責／怎樣做：康文署在適用合約內以清潔完成時間、食物殘留和工人安全作評核，避免將違規餵飼責任全推予清潔工。  作用／限制：鼓勵真正改善環境；指標須考慮遊客量及意外天氣。","glossary":[{"id":"gloss:for:90:1","english":"cleaning quality","chinese":"清潔質素"},{"id":"gloss:for:90:2","english":"fair target","chinese":"合理指標"},{"id":"gloss:for:90:3","english":"worker safety","chinese":"工人安全"},{"id":"gloss:for:90:4","english":"service review","chinese":"服務檢討"},{"id":"gloss:for:90:5","english":"good results","chinese":"良好成果"}]},{"id":"arg:for:91","number":91,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"與景點攝影服務商共同宣傳不抱鳥合照 [商業合作][動物保護]","description":"誰負責／怎樣做：商業攝影者如在適用場地依法營運，可向客人提供海景、夕陽及無接觸野鳥取景範例。  作用／限制：替代抱鳥擺拍的即時收益動機；不認定現場一定存在持牌商業攝影者。","glossary":[{"id":"gloss:for:91:1","english":"photo service","chinese":"攝影服務"},{"id":"gloss:for:91:2","english":"sunset photo","chinese":"日落照片"},{"id":"gloss:for:91:3","english":"safe picture","chinese":"安全照片"},{"id":"gloss:for:91:4","english":"customer choice","chinese":"顧客選擇"},{"id":"gloss:for:91:5","english":"new photo idea","chinese":"新拍照構思"}]},{"id":"arg:for:92","number":92,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"檢討是否有人在景點售賣供餵鳥使用的食物 [巡查][商戶合作]","description":"誰負責／怎樣做：康文署與食環署按權責確認是否有商販宣傳以餵鴿為用途的商品，先核實事實再依法處理適用營商行為。  作用／限制：處理可能鼓勵違規的銷售訊息；不能假定新聞有商販供應鳥糧。","glossary":[{"id":"gloss:for:92:1","english":"selling food","chinese":"出售食物"},{"id":"gloss:for:92:2","english":"shop product","chinese":"商店商品"},{"id":"gloss:for:92:3","english":"check the facts","chinese":"核實事實"},{"id":"gloss:for:92:4","english":"business rules","chinese":"營商規則"},{"id":"gloss:for:92:5","english":"avoid wrong claims","chinese":"避免錯誤指稱"}]},{"id":"arg:for:93","number":93,"angle":"H｜商戶、旅遊業與非金錢／經濟誘因","title":"先小規模測試商戶合作是否真正減少餵飼 [試行][評估]","description":"誰負責／怎樣做：康文署與商戶協會在少數門店試行收據提示與食物包裝提醒，再觀察接觸點附近的行為變化。  作用／限制：用證據決定是否擴大；不可只憑商戶自評作結論。","glossary":[{"id":"gloss:for:93:1","english":"small trial","chinese":"小型試驗"},{"id":"gloss:for:93:2","english":"shop partners","chinese":"合作店舖"},{"id":"gloss:for:93:3","english":"customer reminder","chinese":"顧客提示"},{"id":"gloss:for:93:4","english":"test the idea","chinese":"測試構思"},{"id":"gloss:for:93:5","english":"review the change","chinese":"檢討變化"}]},{"id":"arg:for:94","number":94,"angle":"I｜市民報告、社區互助與公眾參與","title":"在告示清楚寫明1823是違規餵飼通報途徑 [公共服務][資訊提醒]","description":"誰負責／怎樣做：康文署使用漁護署確認的聯絡資訊，讓居民及旅客知道可透過1823交代位置和發生時間。  作用／限制：把資料送到正確渠道；有即時人身危險須另按情況求救。","glossary":[{"id":"gloss:for:94:1","english":"public hotline","chinese":"公共熱線"},{"id":"gloss:for:94:2","english":"report a case","chinese":"報告個案"},{"id":"gloss:for:94:3","english":"exact location","chinese":"確實位置"},{"id":"gloss:for:94:4","english":"time of event","chinese":"事件時間"},{"id":"gloss:for:94:5","english":"contact details","chinese":"聯絡資料"}]},{"id":"arg:for:95","number":95,"angle":"I｜市民報告、社區互助與公眾參與","title":"為目擊者提供五項以內的簡單報告欄位 [服務設計][程序公平]","description":"誰負責／怎樣做：1823及相關部門若優化表格，只問地點、時間、行為、是否正在發生及可選證據，不要求猜測國籍。  作用／限制：提高報告可用性並減少私隱風險；不要求市民冒險跟蹤涉事者。","glossary":[{"id":"gloss:for:95:1","english":"short form","chinese":"簡短表格"},{"id":"gloss:for:95:2","english":"place and time","chinese":"地點和時間"},{"id":"gloss:for:95:3","english":"what happened","chinese":"發生甚麼事"},{"id":"gloss:for:95:4","english":"optional photo","chinese":"可選相片"},{"id":"gloss:for:95:5","english":"protect privacy","chinese":"保障私隱"}]},{"id":"arg:for:96","number":96,"angle":"I｜市民報告、社區互助與公眾參與","title":"明確呼籲公眾不要與違規者爭吵或追逐 [公眾教育][人身安全]","description":"誰負責／怎樣做：警方、康文署及居民團體提醒市民可通知職員或1823，不應為阻止餵鳥而包圍、推撞遊客。  作用／限制：避免原本的衞生事件演變成肢體衝突；嚴重威脅按情況報警。","glossary":[{"id":"gloss:for:96:1","english":"stay calm","chinese":"保持冷靜"},{"id":"gloss:for:96:2","english":"avoid a fight","chinese":"避免爭執"},{"id":"gloss:for:96:3","english":"tell the staff","chinese":"通知職員"},{"id":"gloss:for:96:4","english":"safe reporting","chinese":"安全通報"},{"id":"gloss:for:96:5","english":"public safety","chinese":"公共安全"}]},{"id":"arg:for:97","number":97,"angle":"I｜市民報告、社區互助與公眾參與","title":"不鼓勵網民公開未成年人的清晰樣貌 [私隱][兒童保障]","description":"誰負責／怎樣做：教育團體與平台使用者可提醒分享者遮蓋兒童面貌和其他可識別資料，讓有關部門依法調查。  作用／限制：防止持續網絡羞辱；保留合法投訴與公共議題討論空間。","glossary":[{"id":"gloss:for:97:1","english":"hide a face","chinese":"遮蓋面貌"},{"id":"gloss:for:97:2","english":"young person","chinese":"未成年人"},{"id":"gloss:for:97:3","english":"online sharing","chinese":"網上分享"},{"id":"gloss:for:97:4","english":"private details","chinese":"私人資料"},{"id":"gloss:for:97:5","english":"avoid shame","chinese":"避免羞辱"}]},{"id":"arg:for:98","number":98,"angle":"I｜市民報告、社區互助與公眾參與","title":"由居民協助指出真正反覆出現問題的地點 [公眾參與][評估]","description":"誰負責／怎樣做：南區居民及商戶透過民政事務處或1823提出反覆出現的時段和位置，供漁護署與康文署交叉核對。  作用／限制：利用在地知識改善巡查；投訴多不一定等於違規率高。","glossary":[{"id":"gloss:for:98:1","english":"local knowledge","chinese":"本地知識"},{"id":"gloss:for:98:2","english":"regular problem","chinese":"反覆問題"},{"id":"gloss:for:98:3","english":"resident feedback","chinese":"居民意見"},{"id":"gloss:for:98:4","english":"check reports","chinese":"核對報告"},{"id":"gloss:for:98:5","english":"better patrols","chinese":"更佳巡查"}]},{"id":"arg:for:99","number":99,"angle":"I｜市民報告、社區互助與公眾參與","title":"成立少量受訓「旅遊友善提醒義工」 [義工合作][教育]","description":"誰負責／怎樣做：社區組織與康文署在合理安排下招募義工，在節慶向遊客派官方資訊，不要求盤問或搜查。  作用／限制：把執法人手留給有法律權力的工作；義工需要清楚撤退和求助規則。","glossary":[{"id":"gloss:for:99:1","english":"trained volunteer","chinese":"受訓義工"},{"id":"gloss:for:99:2","english":"give leaflets","chinese":"派發單張"},{"id":"gloss:for:99:3","english":"help visitors","chinese":"協助遊客"},{"id":"gloss:for:99:4","english":"clear limits","chinese":"清楚界線"},{"id":"gloss:for:99:5","english":"ask for backup","chinese":"尋求支援"}]},{"id":"arg:for:100","number":100,"angle":"I｜市民報告、社區互助與公眾參與","title":"定期與動物福利團體審核教育文字 [合作][動物保護]","description":"誰負責／怎樣做：漁護署邀請合資格動物福利團體檢查「餵鳥造成甚麼改變」等教材，避免恐嚇或錯誤健康說法。  作用／限制：增強資訊準確度；民間團體建議不自動取代政府專業判斷。","glossary":[{"id":"gloss:for:100:1","english":"animal experts","chinese":"動物專家"},{"id":"gloss:for:100:2","english":"check the message","chinese":"檢查訊息"},{"id":"gloss:for:100:3","english":"correct facts","chinese":"正確事實"},{"id":"gloss:for:100:4","english":"public lesson","chinese":"公眾課程"},{"id":"gloss:for:100:5","english":"shared learning","chinese":"共同學習"}]},{"id":"arg:for:101","number":101,"angle":"I｜市民報告、社區互助與公眾參與","title":"邀請旅客為告示做「看懂測試」 [公眾參與][評估]","description":"誰負責／怎樣做：康文署與旅發局在不記名情況下請不同語言遊客用自己的話解釋規則，再修正標示。  作用／限制：重點是理解程度而非海報數目；測試不能造成遊客被迫停留。","glossary":[{"id":"gloss:for:101:1","english":"visitor test","chinese":"遊客測試"},{"id":"gloss:for:101:2","english":"understand signs","chinese":"理解標示"},{"id":"gloss:for:101:3","english":"anonymous answer","chinese":"匿名回答"},{"id":"gloss:for:101:4","english":"change the words","chinese":"修改字句"},{"id":"gloss:for:101:5","english":"easy reading","chinese":"容易閱讀"}]},{"id":"arg:for:102","number":102,"angle":"I｜市民報告、社區互助與公眾參與","title":"讓附近商戶分享「食物殘渣最多何時出現」 [商戶合作][衞生]","description":"誰負責／怎樣做：康文署與食肆、清潔員建立簡單通報，例如午餐後或旅遊巴停靠時段，避免重複人手巡場。  作用／限制：從營運時段預判衞生風險；不把商戶分享誤當成法定違規證據。","glossary":[{"id":"gloss:for:102:1","english":"meal time","chinese":"用餐時間"},{"id":"gloss:for:102:2","english":"busy shop","chinese":"繁忙商店"},{"id":"gloss:for:102:3","english":"food waste","chinese":"食物廢物"},{"id":"gloss:for:102:4","english":"shop report","chinese":"商戶報告"},{"id":"gloss:for:102:5","english":"plan cleaning","chinese":"安排清潔"}]},{"id":"arg:for:103","number":103,"angle":"I｜市民報告、社區互助與公眾參與","title":"讓鳥類觀察者提供非侵入式資料 [公民科學][生態保護]","description":"誰負責／怎樣做：鳥類愛好者可協助記錄特定區域的鴿群大小和活動時間，不追逐、捕捉或誘餌吸引鳥群。  作用／限制：提供觀察角度而非取代正式調查；志願數據需交叉核實。","glossary":[{"id":"gloss:for:103:1","english":"bird count","chinese":"雀鳥點算"},{"id":"gloss:for:103:2","english":"watch quietly","chinese":"安靜觀察"},{"id":"gloss:for:103:3","english":"record time","chinese":"記錄時間"},{"id":"gloss:for:103:4","english":"share findings","chinese":"分享觀察結果"},{"id":"gloss:for:103:5","english":"no bait","chinese":"不使用誘餌"}]},{"id":"arg:for:104","number":104,"angle":"I｜市民報告、社區互助與公眾參與","title":"在高風險節假日加強與居民的事前溝通 [社區協作][時間管理]","description":"誰負責／怎樣做：南區民政事務處協調康文署與居民團體，在長假前公布巡查重點及1823渠道，收集場地管理意見。  作用／限制：減少居民不知向誰反映；討論不應變成排斥遊客。","glossary":[{"id":"gloss:for:104:1","english":"holiday notice","chinese":"節假日通知"},{"id":"gloss:for:104:2","english":"local meeting","chinese":"地區會議"},{"id":"gloss:for:104:3","english":"resident concerns","chinese":"居民關注"},{"id":"gloss:for:104:4","english":"shared plan","chinese":"共同計劃"},{"id":"gloss:for:104:5","english":"welcome visitors","chinese":"歡迎遊客"}]},{"id":"arg:for:105","number":105,"angle":"J｜科技、數據、監控邊界與私隱","title":"只在持續黑點研究限量使用監察設備 [科技][試行]","description":"誰負責／怎樣做：漁護署可參考2025至2026年在其他地點的AI監察試點，先核實淺水灣是否有足夠反覆違規及必要性。  作用／限制：技術應節省巡查時間；不能因單段新聞片就宣稱需全灘密集監控。","glossary":[{"id":"gloss:for:105:1","english":"security camera","chinese":"保安攝錄機"},{"id":"gloss:for:105:2","english":"small trial","chinese":"小型試驗"},{"id":"gloss:for:105:3","english":"repeated cases","chinese":"重複個案"},{"id":"gloss:for:105:4","english":"real need","chinese":"實際需要"},{"id":"gloss:for:105:5","english":"check the plan","chinese":"檢查方案"}]},{"id":"arg:for:106","number":106,"angle":"J｜科技、數據、監控邊界與私隱","title":"把鳥群數量分析與個人身分辨認分開 [私隱][科技]","description":"誰負責／怎樣做：漁護署若採技術輔助，優先研究鳥群聚集或可疑活動的整體訊號，不主動建立遊客人臉名冊。  作用／限制：達到資源規劃目的而減少私隱侵入；任何個人資料處理須符合法律。","glossary":[{"id":"gloss:for:106:1","english":"bird numbers","chinese":"鳥隻數量"},{"id":"gloss:for:106:2","english":"people's faces","chinese":"人們面孔"},{"id":"gloss:for:106:3","english":"private data","chinese":"私人資料"},{"id":"gloss:for:106:4","english":"collect less data","chinese":"收集較少資料"},{"id":"gloss:for:106:5","english":"public safety","chinese":"公共安全"}]},{"id":"arg:for:107","number":107,"angle":"J｜科技、數據、監控邊界與私隱","title":"攝錄區域放明顯告示並公開負責部門 [資訊公開][私隱]","description":"誰負責／怎樣做：如經必要性評估確需錄影，管理者應張貼用途、負責單位及查詢方法，遵守私隱專員相關指引。  作用／限制：讓市民知情；不能把「公開地方」等同可無限制攝錄。","glossary":[{"id":"gloss:for:107:1","english":"camera notice","chinese":"攝錄告示"},{"id":"gloss:for:107:2","english":"who is in charge","chinese":"誰負責"},{"id":"gloss:for:107:3","english":"clear purpose","chinese":"清楚用途"},{"id":"gloss:for:107:4","english":"personal privacy","chinese":"個人私隱"},{"id":"gloss:for:107:5","english":"public place","chinese":"公共地方"}]},{"id":"arg:for:108","number":108,"angle":"J｜科技、數據、監控邊界與私隱","title":"設定保存及刪除影片的合理期限 [私隱][程序公平]","description":"誰負責／怎樣做：負責部門按適用法律及實際調查需要制定影片保存、限制存取及刪除安排，並留下調閱紀錄。  作用／限制：降低資料外洩風險；如涉正式調查須依法保留必要證據。","glossary":[{"id":"gloss:for:108:1","english":"keep records","chinese":"保存紀錄"},{"id":"gloss:for:108:2","english":"delete old files","chinese":"刪除舊檔"},{"id":"gloss:for:108:3","english":"safe storage","chinese":"安全儲存"},{"id":"gloss:for:108:4","english":"access control","chinese":"存取限制"},{"id":"gloss:for:108:5","english":"legal reason","chinese":"法律理由"}]},{"id":"arg:for:109","number":109,"angle":"J｜科技、數據、監控邊界與私隱","title":"技術只提示異常，最終違規判斷保留人工核實 [科技][程序公平]","description":"誰負責／怎樣做：漁護署利用系統協助定位可能餵飼事件，獲委任執法人員再依可核實證據作決定。  作用／限制：避免把投食、正常進食或鳥群靠近誤判為同一回事；技術不可自動開罰單。","glossary":[{"id":"gloss:for:109:1","english":"computer alert","chinese":"電腦警示"},{"id":"gloss:for:109:2","english":"human review","chinese":"人工覆核"},{"id":"gloss:for:109:3","english":"possible error","chinese":"可能錯誤"},{"id":"gloss:for:109:4","english":"real evidence","chinese":"真實證據"},{"id":"gloss:for:109:5","english":"final decision","chinese":"最終決定"}]},{"id":"arg:for:110","number":110,"angle":"J｜科技、數據、監控邊界與私隱","title":"測試監察系統對不同光線與人潮的錯誤率 [評估][科技]","description":"誰負責／怎樣做：漁護署只在批准的試驗中比較陽光、雨天與多人場景的誤報，必要時調整而非直接擴大。  作用／限制：避免浪費執法人手追逐假警報；試驗須披露限制。","glossary":[{"id":"gloss:for:110:1","english":"false alarm","chinese":"錯誤警報"},{"id":"gloss:for:110:2","english":"bright light","chinese":"強光"},{"id":"gloss:for:110:3","english":"rainy day","chinese":"雨天"},{"id":"gloss:for:110:4","english":"crowded area","chinese":"人多地區"},{"id":"gloss:for:110:5","english":"improve the system","chinese":"改善系統"}]},{"id":"arg:for:111","number":111,"angle":"J｜科技、數據、監控邊界與私隱","title":"為市民提供無須拍人臉的通報選項 [私隱][公共服務]","description":"誰負責／怎樣做：1823或相關部門可接受以文字說明地點和時間，必要照片只拍行為及場地，不鼓勵對準兒童面孔。  作用／限制：減少網絡公開與個資風險；有實際刑事調查時由合法程序處理證據。","glossary":[{"id":"gloss:for:111:1","english":"text report","chinese":"文字報告"},{"id":"gloss:for:111:2","english":"no face photo","chinese":"不拍面孔"},{"id":"gloss:for:111:3","english":"child privacy","chinese":"兒童私隱"},{"id":"gloss:for:111:4","english":"necessary proof","chinese":"必要證明"},{"id":"gloss:for:111:5","english":"safe sharing","chinese":"安全分享"}]},{"id":"arg:for:112","number":112,"angle":"J｜科技、數據、監控邊界與私隱","title":"使用不含個人身分的熱點地圖安排巡查 [數據分析][巡查]","description":"誰負責／怎樣做：漁護署與康文署整合時間、位置及類別等統計，定期更新巡查次序，不建立遊客追蹤檔案。  作用／限制：提高資源分配效率；若資料量少須防誤導。","glossary":[{"id":"gloss:for:112:1","english":"simple map","chinese":"簡單地圖"},{"id":"gloss:for:112:2","english":"busy times","chinese":"繁忙時段"},{"id":"gloss:for:112:3","english":"problem spots","chinese":"問題位置"},{"id":"gloss:for:112:4","english":"anonymous figures","chinese":"匿名數字"},{"id":"gloss:for:112:5","english":"plan patrols","chinese":"規劃巡查"}]},{"id":"arg:for:113","number":113,"angle":"J｜科技、數據、監控邊界與私隱","title":"讓遊客可在不開手機程式下取得同樣資訊 [無障礙][資訊提醒]","description":"誰負責／怎樣做：康文署保留實體告示和紙本資訊，數碼地圖只是補充，並非唯一遵守規則的方法。  作用／限制：避免對沒有智能電話的老人或旅客不公平；也減少應用程式資料收集。","glossary":[{"id":"gloss:for:113:1","english":"paper guide","chinese":"紙本指引"},{"id":"gloss:for:113:2","english":"no phone needed","chinese":"不需手機"},{"id":"gloss:for:113:3","english":"equal service","chinese":"平等服務"},{"id":"gloss:for:113:4","english":"easy access","chinese":"容易使用"},{"id":"gloss:for:113:5","english":"digital option","chinese":"數碼選項"}]},{"id":"arg:for:114","number":114,"angle":"J｜科技、數據、監控邊界與私隱","title":"以匿名觀察衡量標示是否真的改變行為 [評估][試行]","description":"誰負責／怎樣做：康文署在相近時段比較改牌前後的餵飼次數及旅客理解，而非採全面個人追蹤。  作用／限制：取得政策效果資訊而減少侵犯私隱；要同時計算人流與天氣。","glossary":[{"id":"gloss:for:114:1","english":"before and after","chinese":"前後比較"},{"id":"gloss:for:114:2","english":"visitor count","chinese":"遊客數目"},{"id":"gloss:for:114:3","english":"track changes","chinese":"追蹤變化"},{"id":"gloss:for:114:4","english":"no names needed","chinese":"不需姓名"},{"id":"gloss:for:114:5","english":"careful study","chinese":"審慎研究"}]},{"id":"arg:for:115","number":115,"angle":"J｜科技、數據、監控邊界與私隱","title":"為監察技術建立停止使用的門檻 [私隱][問責]","description":"誰負責／怎樣做：漁護署與相關資料管理者在試驗開始前訂明如誤報高、成效低或私隱風險過大便停止試行。  作用／限制：避免技術一裝就永久擴張；停用準則與責任人應可查閱。","glossary":[{"id":"gloss:for:115:1","english":"stop the trial","chinese":"停止試驗"},{"id":"gloss:for:115:2","english":"review period","chinese":"檢討期"},{"id":"gloss:for:115:3","english":"privacy risk","chinese":"私隱風險"},{"id":"gloss:for:115:4","english":"poor results","chinese":"成效不佳"},{"id":"gloss:for:115:5","english":"clear limit","chinese":"清楚限制"}]},{"id":"arg:for:116","number":116,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由康文署擔任淺水灣泳灘的現場行動負責方 [部門分工][場地管理]","description":"誰負責／怎樣做：康文署南區場地管理人員維持一張簡易工作表，記錄標示、清潔、巡場與轉介情況。  作用／限制：使遊客及其他部門知道向誰查詢；不將所有法律調查責任轉給一般泳灘員工。","glossary":[{"id":"gloss:for:116:1","english":"site manager","chinese":"場地管理者"},{"id":"gloss:for:116:2","english":"daily tasks","chinese":"每日工作"},{"id":"gloss:for:116:3","english":"clear contact","chinese":"清楚聯絡點"},{"id":"gloss:for:116:4","english":"beach services","chinese":"泳灘服務"},{"id":"gloss:for:116:5","english":"work record","chinese":"工作紀錄"}]},{"id":"arg:for:117","number":117,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由漁護署主導禁餵規則、執法人員訓練與專業支援 [部門分工][執法]","description":"誰負責／怎樣做：漁護署為跨部門人員提供最新法例說明及標準記錄方式，並對有爭議雀鳥案件提供適用專業協助。  作用／限制：減少不同部門用詞及做法不一致；不代表每宗輕微投訴都要派漁護署專員。","glossary":[{"id":"gloss:for:117:1","english":"legal guidance","chinese":"法律指引"},{"id":"gloss:for:117:2","english":"staff training","chinese":"員工培訓"},{"id":"gloss:for:117:3","english":"common rules","chinese":"共同規則"},{"id":"gloss:for:117:4","english":"expert advice","chinese":"專業建議"},{"id":"gloss:for:117:5","english":"fair action","chinese":"公平處理"}]},{"id":"arg:for:118","number":118,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由食環署處理所管轄公眾地方的食物與衞生問題 [部門分工][衞生]","description":"誰負責／怎樣做：食環署按適用職責處理泳灘外附近街道的垃圾、相關環境衞生及商販問題，與康文署互通發現。  作用／限制：防止管理邊界造成清潔漏洞；不得把泳灘內一切設施歸食環署負責。","glossary":[{"id":"gloss:for:118:1","english":"street hygiene","chinese":"街道衞生"},{"id":"gloss:for:118:2","english":"food waste","chinese":"食物廢物"},{"id":"gloss:for:118:3","english":"nearby area","chinese":"毗鄰地區"},{"id":"gloss:for:118:4","english":"share reports","chinese":"分享報告"},{"id":"gloss:for:118:5","english":"clear boundary","chinese":"清楚界線"}]},{"id":"arg:for:119","number":119,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由警方處理有暴力、公共秩序或疑似虐待動物的升級個案 [部門分工][公共安全]","description":"誰負責／怎樣做：康文署及漁護署在遇威脅、阻撓或合理懷疑虐待動物時，按正式途徑聯絡警方依法調查。  作用／限制：把警力留給需警務權力的個案；一般鳥群聚集不等於刑事緊急事故。","glossary":[{"id":"gloss:for:119:1","english":"police support","chinese":"警方支援"},{"id":"gloss:for:119:2","english":"serious conflict","chinese":"嚴重衝突"},{"id":"gloss:for:119:3","english":"possible cruelty","chinese":"疑似殘酷行為"},{"id":"gloss:for:119:4","english":"legal investigation","chinese":"法律調查"},{"id":"gloss:for:119:5","english":"use the right service","chinese":"使用正確服務"}]},{"id":"arg:for:120","number":120,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由環境及生態局定期檢視跨部門成果與整體資源 [政策統籌][評估]","description":"誰負責／怎樣做：環境及生態局可透過既有工作組了解漁護署、康文署、食環署和房屋署的禁餵經驗，研究是否調整全港優次。  作用／限制：處理跨區政策協調，而非由局方直接代替前線執法。","glossary":[{"id":"gloss:for:120:1","english":"overall plan","chinese":"整體計劃"},{"id":"gloss:for:120:2","english":"shared goals","chinese":"共同目標"},{"id":"gloss:for:120:3","english":"department review","chinese":"部門檢討"},{"id":"gloss:for:120:4","english":"public spending","chinese":"公共開支"},{"id":"gloss:for:120:5","english":"long-term results","chinese":"長遠成果"}]},{"id":"arg:for:121","number":121,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由文化體育及旅遊局／旅遊事務署協調旅遊業教育策略 [旅遊統籌][合作]","description":"誰負責／怎樣做：旅遊事務署與旅發局、旅監局及相關業界商討如何在旅遊路線和導遊資訊中加入不餵鳥守則。  作用／限制：把旅遊安全與遊客體驗連起來；不新增未經授權的罰款權。","glossary":[{"id":"gloss:for:121:1","english":"tourism policy","chinese":"旅遊政策"},{"id":"gloss:for:121:2","english":"travel partners","chinese":"旅遊合作夥伴"},{"id":"gloss:for:121:3","english":"visitor advice","chinese":"遊客指引"},{"id":"gloss:for:121:4","english":"protect the image","chinese":"維護形象"},{"id":"gloss:for:121:5","english":"joint planning","chinese":"共同規劃"}]},{"id":"arg:for:122","number":122,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由旅監局按持牌業界制度提供可行培訓指引 [行業規管][培訓]","description":"誰負責／怎樣做：旅監局可向持牌旅行社及導遊發出經漁護署核實的景點守則資料，並研究是否應納入業界專業教育。  作用／限制：向真正陪同團客的人傳遞知識；若新增強制責任須另審法律依據及諮詢。","glossary":[{"id":"gloss:for:122:1","english":"licensed guide","chinese":"持牌導遊"},{"id":"gloss:for:122:2","english":"industry rules","chinese":"行業規則"},{"id":"gloss:for:122:3","english":"guide training","chinese":"導遊培訓"},{"id":"gloss:for:122:4","english":"travel safety","chinese":"旅遊安全"},{"id":"gloss:for:122:5","english":"new duty","chinese":"新增責任"}]},{"id":"arg:for:123","number":123,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由旅發局改善面向散客與境外訪客的訊息 [旅遊宣傳][教育]","description":"誰負責／怎樣做：旅發局在官方旅遊介紹及合適社交宣傳中附上簡明禁餵和自然拍照建議，連接漁護署官方網站。  作用／限制：照顧沒有導遊的自由行旅客；旅發局不處理罰單。","glossary":[{"id":"gloss:for:123:1","english":"independent travellers","chinese":"自由行旅客"},{"id":"gloss:for:123:2","english":"visitor guide","chinese":"旅客指南"},{"id":"gloss:for:123:3","english":"online information","chinese":"網上資訊"},{"id":"gloss:for:123:4","english":"clear link","chinese":"清晰連結"},{"id":"gloss:for:123:5","english":"safe visit","chinese":"安全旅遊"}]},{"id":"arg:for:124","number":124,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"讓房屋署在跨部門小組分享屋邨黑點管理經驗 [跨部門合作][資源分配]","description":"誰負責／怎樣做：房屋署提供其管理場景內的有效告示、居民溝通和巡查經驗，供康文署依泳灘情況參考。  作用／限制：共享方法而不混淆權力；不同場地未必可直接複製。","glossary":[{"id":"gloss:for:124:1","english":"housing team","chinese":"房屋管理團隊"},{"id":"gloss:for:124:2","english":"share lessons","chinese":"分享經驗"},{"id":"gloss:for:124:3","english":"local methods","chinese":"本地方法"},{"id":"gloss:for:124:4","english":"change for the beach","chinese":"因應泳灘調整"},{"id":"gloss:for:124:5","english":"learn together","chinese":"共同學習"}]},{"id":"arg:for:125","number":125,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由衞生防護中心核對所有健康風險宣傳 [科學溝通][公共衞生]","description":"誰負責／怎樣做：衞生署衞生防護中心提供接觸雀鳥、洗手及求醫的科學用語，讓其他部門引用。  作用／限制：避免因網上恐慌而錯誤宣稱疫病已發生；醫療判斷仍依實際情況。","glossary":[{"id":"gloss:for:125:1","english":"health message","chinese":"健康訊息"},{"id":"gloss:for:125:2","english":"science-based advice","chinese":"以科學為本的建議"},{"id":"gloss:for:125:3","english":"wash with soap","chinese":"用肥皂清洗"},{"id":"gloss:for:125:4","english":"medical help","chinese":"醫療協助"},{"id":"gloss:for:125:5","english":"avoid false claims","chinese":"避免錯誤說法"}]},{"id":"arg:for:126","number":126,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由南區民政事務處聯繫居民與旅遊商戶處理地區摩擦 [地區合作][公眾參與]","description":"誰負責／怎樣做：南區民政事務處按其協調角色召集康文署、居民、酒店及商戶代表，收集噪音、人流及清潔方面的意見。  作用／限制：減少只看遊客或居民一方的資訊；不以會議取代實際巡查與法定執法。","glossary":[{"id":"gloss:for:126:1","english":"local meeting","chinese":"地區會議"},{"id":"gloss:for:126:2","english":"resident views","chinese":"居民意見"},{"id":"gloss:for:126:3","english":"shop owners","chinese":"商戶"},{"id":"gloss:for:126:4","english":"visitor needs","chinese":"遊客需要"},{"id":"gloss:for:126:5","english":"find common ground","chinese":"尋找共同點"}]},{"id":"arg:for:127","number":127,"angle":"K｜具名政府分工、跨部門合作與資源配置","title":"由1823和相關部門建立清晰的跨單位轉介回覆 [行政協作][公共服務]","description":"誰負責／怎樣做：1823把疑似非法餵飼送合適執法部門、把泳灘清潔送場地管理者、把疑似虐待動物送適當機關；回覆可用通用狀態說明。  作用／限制：減少重複投訴及迷失在部門間；不得向無關第三方公開調查資料。","glossary":[{"id":"gloss:for:127:1","english":"pass on a case","chinese":"轉介個案"},{"id":"gloss:for:127:2","english":"correct office","chinese":"正確部門"},{"id":"gloss:for:127:3","english":"reply to the public","chinese":"回覆公眾"},{"id":"gloss:for:127:4","english":"shared process","chinese":"共同流程"},{"id":"gloss:for:127:5","english":"protect case details","chinese":"保護個案資料"}]},{"id":"arg:for:128","number":128,"angle":"L｜成效評估、長期改進及生態治理","title":"先做六星期示範試行再決定是否長期化 [試行][評估]","description":"誰負責／怎樣做：康文署和漁護署在淺水灣選定假日安排、現場告示及精準巡查，六星期後與先前資料比較。  作用／限制：降低大規模改革成本；六星期為教學假設，非已公布官方計劃。","glossary":[{"id":"gloss:for:128:1","english":"six-week trial","chinese":"六星期試行"},{"id":"gloss:for:128:2","english":"test period","chinese":"測試期"},{"id":"gloss:for:128:3","english":"start small","chinese":"從小規模開始"},{"id":"gloss:for:128:4","english":"review results","chinese":"檢討結果"},{"id":"gloss:for:128:5","english":"decide later","chinese":"稍後決定"}]},{"id":"arg:for:129","number":129,"angle":"L｜成效評估、長期改進及生態治理","title":"選取一個相近區域作觀察比較 [評估][研究]","description":"誰負責／怎樣做：康文署於人流與環境較相近的泳灘或沙灘區域記錄基本情況，與試點變化比較。  作用／限制：避免將天氣或假日造成的改變錯當政策成果；必須尊重不同場地條件。","glossary":[{"id":"gloss:for:129:1","english":"comparison area","chinese":"比較區域"},{"id":"gloss:for:129:2","english":"similar conditions","chinese":"相似條件"},{"id":"gloss:for:129:3","english":"fair test","chinese":"公平測試"},{"id":"gloss:for:129:4","english":"weather changes","chinese":"天氣變化"},{"id":"gloss:for:129:5","english":"check the cause","chinese":"核查原因"}]},{"id":"arg:for:130","number":130,"angle":"L｜成效評估、長期改進及生態治理","title":"以違規比率而非投訴總數評估成效 [評估][數據]","description":"誰負責／怎樣做：漁護署與康文署用相同時間與觀察方法估算每百名遊客的餵飼次數，而不只比較全部舉報數量。  作用／限制：避免人流增加自然帶來較多投訴的錯覺；數據仍可能受抽樣限制。","glossary":[{"id":"gloss:for:130:1","english":"rate of cases","chinese":"個案比率"},{"id":"gloss:for:130:2","english":"visitor numbers","chinese":"遊客人數"},{"id":"gloss:for:130:3","english":"total complaints","chinese":"投訴總數"},{"id":"gloss:for:130:4","english":"fair measure","chinese":"公平衡量"},{"id":"gloss:for:130:5","english":"data limits","chinese":"資料限制"}]},{"id":"arg:for:131","number":131,"angle":"L｜成效評估、長期改進及生態治理","title":"把雀鳥受傷與受驚報告納入成效評估 [動物保護][評估]","description":"誰負責／怎樣做：漁護署與動物福利專家檢視可核實的受傷轉介及人鳥直接接觸情況，不只看有沒有罰款。  作用／限制：確保政策真正改善動物福利；沒有通報不代表沒有傷害。","glossary":[{"id":"gloss:for:131:1","english":"injury report","chinese":"受傷報告"},{"id":"gloss:for:131:2","english":"bird care","chinese":"雀鳥照顧"},{"id":"gloss:for:131:3","english":"direct contact","chinese":"直接接觸"},{"id":"gloss:for:131:4","english":"animal safety","chinese":"動物安全"},{"id":"gloss:for:131:5","english":"hidden problems","chinese":"隱藏問題"}]},{"id":"arg:for:132","number":132,"angle":"L｜成效評估、長期改進及生態治理","title":"以旅客理解度與整體滿意度一同評估 [旅遊評估][公眾參與]","description":"誰負責／怎樣做：旅發局與康文署用不記名簡短問卷問遊客是否懂得禁餵、能否享受景色及尋得洗手間。  作用／限制：避免只追求阻止違規而忽視友善旅遊；問卷不能冒充全港民意。","glossary":[{"id":"gloss:for:132:1","english":"visitor feedback","chinese":"遊客意見"},{"id":"gloss:for:132:2","english":"enjoy the trip","chinese":"享受旅程"},{"id":"gloss:for:132:3","english":"understand the rule","chinese":"理解規則"},{"id":"gloss:for:132:4","english":"short survey","chinese":"簡短問卷"},{"id":"gloss:for:132:5","english":"balanced results","chinese":"平衡結果"}]},{"id":"arg:for:133","number":133,"angle":"L｜成效評估、長期改進及生態治理","title":"按各部門投入人時比較不同方法的成本 [財務評估][資源分配]","description":"誰負責／怎樣做：康文署與漁護署比較標示、短巡查、教育攤位及清潔改善所用工時，避免無限追加同一措施。  作用／限制：讓有限資源投向有用機制；不能純以最便宜判斷是否保障動物。","glossary":[{"id":"gloss:for:133:1","english":"staff hours","chinese":"員工工時"},{"id":"gloss:for:133:2","english":"total cost","chinese":"總成本"},{"id":"gloss:for:133:3","english":"value for money","chinese":"物有所值"},{"id":"gloss:for:133:4","english":"useful action","chinese":"有效行動"},{"id":"gloss:for:133:5","english":"limited budget","chinese":"有限預算"}]},{"id":"arg:for:134","number":134,"angle":"L｜成效評估、長期改進及生態治理","title":"每季更新標示而不是不斷增添新牌 [資源管理][評估]","description":"誰負責／怎樣做：康文署在既有保養安排中檢視遊客是否看得懂、告示是否損壞，先改文字或位置再考慮新增數量。  作用／限制：防止資訊過多造成忽略；有需要的法律資訊不能省掉。","glossary":[{"id":"gloss:for:134:1","english":"quarterly review","chinese":"每季檢討"},{"id":"gloss:for:134:2","english":"too many signs","chinese":"過多告示"},{"id":"gloss:for:134:3","english":"repair a notice","chinese":"維修告示"},{"id":"gloss:for:134:4","english":"update wording","chinese":"更新字句"},{"id":"gloss:for:134:5","english":"avoid waste","chinese":"避免浪費"}]},{"id":"arg:for:135","number":135,"angle":"L｜成效評估、長期改進及生態治理","title":"訂出試點擴大與停止條件 [問責][試行]","description":"誰負責／怎樣做：環境及生態局與執行部門可事先說明哪些指標改善才擴至其他景點，以及何種成本或私隱問題會令試點終止。  作用／限制：避免措施只增不減；需向公眾交代改變理由。","glossary":[{"id":"gloss:for:135:1","english":"expand a trial","chinese":"擴大試點"},{"id":"gloss:for:135:2","english":"stop a project","chinese":"停止項目"},{"id":"gloss:for:135:3","english":"clear reasons","chinese":"清楚原因"},{"id":"gloss:for:135:4","english":"public report","chinese":"公開報告"},{"id":"gloss:for:135:5","english":"responsible decision","chinese":"負責任決定"}]},{"id":"arg:for:136","number":136,"angle":"L｜成效評估、長期改進及生態治理","title":"把旅遊旺季和季節因素列入人手安排 [時間管理][資源分配]","description":"誰負責／怎樣做：康文署、漁護署按長假、天氣及到訪人流調整宣傳和巡查，不依一宗事件固定全年高強度。  作用／限制：把資源使用與風險相配；熱門時段資料須定期更新。","glossary":[{"id":"gloss:for:136:1","english":"travel season","chinese":"旅遊旺季"},{"id":"gloss:for:136:2","english":"busy weekend","chinese":"繁忙周末"},{"id":"gloss:for:136:3","english":"staff planning","chinese":"人手安排"},{"id":"gloss:for:136:4","english":"weather conditions","chinese":"天氣情況"},{"id":"gloss:for:136:5","english":"flexible plan","chinese":"彈性計劃"}]},{"id":"arg:for:137","number":137,"angle":"L｜成效評估、長期改進及生態治理","title":"公開不包括個人身分的簡短年度成效報告 [資訊公開][問責]","description":"誰負責／怎樣做：漁護署可與相關部門整理巡查、舉報、清潔和教育成果，只公布足夠保護私隱的合計資料。  作用／限制：增進公眾信任及政策學習；避免公布可識別兒童或個別遊客的細節。","glossary":[{"id":"gloss:for:137:1","english":"annual report","chinese":"年度報告"},{"id":"gloss:for:137:2","english":"public figures","chinese":"公開數字"},{"id":"gloss:for:137:3","english":"privacy protection","chinese":"私隱保障"},{"id":"gloss:for:137:4","english":"share results","chinese":"分享成果"},{"id":"gloss:for:137:5","english":"public trust","chinese":"公眾信任"}]},{"id":"arg:for:138","number":138,"angle":"L｜成效評估、長期改進及生態治理","title":"定期檢查環境改善是否只是把鴿群趕往其他地方 [生態評估][跨地區合作]","description":"誰負責／怎樣做：漁護署與附近場地管理者比較周邊鳥群活動，避免只把一處聚集轉移到鄰近街道或住宅。  作用／限制：防止問題轉移；需要專業觀察而非任意清除野鴿。","glossary":[{"id":"gloss:for:138:1","english":"nearby area","chinese":"附近地方"},{"id":"gloss:for:138:2","english":"move the problem","chinese":"轉移問題"},{"id":"gloss:for:138:3","english":"bird movement","chinese":"雀鳥活動"},{"id":"gloss:for:138:4","english":"wider view","chinese":"更廣視角"},{"id":"gloss:for:138:5","english":"long-term effect","chinese":"長遠影響"}]},{"id":"arg:for:139","number":139,"angle":"L｜成效評估、長期改進及生態治理","title":"把安全觀鳥經驗整理成可轉用的景點管理工具包 [知識共享][長遠規劃]","description":"誰負責／怎樣做：康文署、漁護署與旅發局把有效告示、導遊文字、巡查表及評估方法整理供其他景點選用。  作用／限制：減少每區重新設計成本；新場地仍須檢查各自法例和動物種類。","glossary":[{"id":"gloss:for:139:1","english":"ready-made guide","chinese":"現成指引"},{"id":"gloss:for:139:2","english":"share good ideas","chinese":"分享良好做法"},{"id":"gloss:for:139:3","english":"other beaches","chinese":"其他泳灘"},{"id":"gloss:for:139:4","english":"save time","chinese":"節省時間"},{"id":"gloss:for:139:5","english":"local needs","chinese":"地方需要"}]}],"against":[{"id":"arg:against:140","number":140,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"過重依賴罰款可能忽略真正的理解不足 [反對觀點][教育取捨]","description":"反對理由／受影響者：遊客可能根本沒有看見告示，若政府只增加罰款而不改善入場提示，會減少守規則的機會。  政策取捨：保留依法處理違規的必要性，同時把事前可理解的提醒列為政策成效之一。","glossary":[{"id":"gloss:against:140:1","english":"lack of knowledge","chinese":"缺乏知識"},{"id":"gloss:against:140:2","english":"strong penalty","chinese":"嚴厲罰款"},{"id":"gloss:against:140:3","english":"clear guidance","chinese":"清晰指引"},{"id":"gloss:against:140:4","english":"fair warning sign","chinese":"公平警示"},{"id":"gloss:against:140:5","english":"understand the law","chinese":"理解法律"}]},{"id":"arg:against:141","number":141,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"5,000元定額罰款對不同收入者的負擔不同 [反對觀點][公平]","description":"反對理由／受影響者：低收入家庭可能較難承受同額金錢處罰，令人質疑處罰的比例與公平。  政策取捨：金額已屬現行法例；政策辯論可討論長遠檢討，但不能由場地人員私自減額。","glossary":[{"id":"gloss:against:141:1","english":"same fine","chinese":"相同罰款"},{"id":"gloss:against:141:2","english":"low income","chinese":"低收入"},{"id":"gloss:against:141:3","english":"financial burden","chinese":"財政負擔"},{"id":"gloss:against:141:4","english":"fair result","chinese":"公平結果"},{"id":"gloss:against:141:5","english":"legal rule","chinese":"法律規定"}]},{"id":"arg:against:142","number":142,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"執法人員不可能目睹每一次短暫撒糧 [反對觀點][執行困難]","description":"反對理由／受影響者：遊客餵鴿可能只需數秒，全天巡邏仍會錯過，更多人手也未必與成效成比例。  政策取捨：在客觀證據足夠的黑點集中巡查，並依靠事前預防降低違規。","glossary":[{"id":"gloss:against:142:1","english":"quick action","chinese":"短暫動作"},{"id":"gloss:against:142:2","english":"miss an event","chinese":"錯過事件"},{"id":"gloss:against:142:3","english":"limited patrol","chinese":"有限巡查"},{"id":"gloss:against:142:4","english":"staff shortage","chinese":"人手不足"},{"id":"gloss:against:142:5","english":"early prevention","chinese":"及早預防"}]},{"id":"arg:against:143","number":143,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"鳥隻靠近人群不等於有人違法餵飼 [反對觀點][誤判]","description":"反對理由／受影響者：鳥群可能因其他食物來源、休息地或自然行為靠近遊客，僅憑聚集推斷違規會冤枉他人。  政策取捨：以具體動作核實才執法；鳥群數量可用來選巡查位置但不是定罪證據。","glossary":[{"id":"gloss:against:143:1","english":"bird gathering","chinese":"雀鳥聚集"},{"id":"gloss:against:143:2","english":"wrong guess","chinese":"錯誤猜測"},{"id":"gloss:against:143:3","english":"real action","chinese":"實際行為"},{"id":"gloss:against:143:4","english":"check carefully","chinese":"審慎核實"},{"id":"gloss:against:143:5","english":"fair evidence","chinese":"公平證據"}]},{"id":"arg:against:144","number":144,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"以網民猜測的國籍訂政策會造成歧視 [反對觀點][平等]","description":"反對理由／受影響者：從影片不能證實遊客來源，若對某類口音或外觀者加強盤查，可能損害平等及香港旅遊形象。  政策取捨：以可見違規與客觀風險指標決定措施，讓本地與海外遊客適用同一規則。","glossary":[{"id":"gloss:against:144:1","english":"nationality","chinese":"國籍"},{"id":"gloss:against:144:2","english":"unfair bias","chinese":"不公平偏見"},{"id":"gloss:against:144:3","english":"same rules","chinese":"相同規則"},{"id":"gloss:against:144:4","english":"visitor respect","chinese":"尊重遊客"},{"id":"gloss:against:144:5","english":"judge actions","chinese":"按行為判斷"}]},{"id":"arg:against:145","number":145,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"把兒童面貌廣泛轉發會造成長期網絡傷害 [反對觀點][兒童私隱]","description":"反對理由／受影響者：即使成年人不滿意孩子捉鳥，公開清晰面孔及姓名亦可能令未成年人長期被搜尋和辱罵。  政策取捨：可討論動物福利並向部門舉報，但傳播內容應減少可識別資料。","glossary":[{"id":"gloss:against:145:1","english":"online harm","chinese":"網絡傷害"},{"id":"gloss:against:145:2","english":"child privacy","chinese":"兒童私隱"},{"id":"gloss:against:145:3","english":"share carefully","chinese":"審慎分享"},{"id":"gloss:against:145:4","english":"hide identity","chinese":"遮蓋身分"},{"id":"gloss:against:145:5","english":"respect a child","chinese":"尊重兒童"}]},{"id":"arg:against:146","number":146,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"把鳥糞風險直接說成禽流感爆發會製造恐慌 [反對觀點][科學準確]","description":"反對理由／受影響者：疾病風險值得預防，但新聞未證實涉事鴿子帶有禽流感，也未有當事人感染證據。  政策取捨：採用衞生防護中心建議而不誇大病情。","glossary":[{"id":"gloss:against:146:1","english":"health concern","chinese":"健康關注"},{"id":"gloss:against:146:2","english":"disease risk","chinese":"疾病風險"},{"id":"gloss:against:146:3","english":"no confirmed case","chinese":"沒有確診個案"},{"id":"gloss:against:146:4","english":"accurate facts","chinese":"準確事實"},{"id":"gloss:against:146:5","english":"avoid fear","chinese":"避免恐慌"}]},{"id":"arg:against:147","number":147,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"過多禁令告示可能破壞自然景觀 [反對觀點][旅遊體驗]","description":"反對理由／受影響者：若海灘每隔數步便是一塊警告牌，遊客可能覺得景點像受嚴格管制的地方。  政策取捨：集中放在決策點並測試理解度，保留自然景觀。","glossary":[{"id":"gloss:against:147:1","english":"too many notices","chinese":"過多告示"},{"id":"gloss:against:147:2","english":"natural view","chinese":"自然景色"},{"id":"gloss:against:147:3","english":"visitor feeling","chinese":"遊客感受"},{"id":"gloss:against:147:4","english":"keep signs simple","chinese":"保持標示簡潔"},{"id":"gloss:against:147:5","english":"right location","chinese":"合適位置"}]},{"id":"arg:against:148","number":148,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"全天閉路電視可能侵犯無違規遊客的私隱 [反對觀點][私隱]","description":"反對理由／受影響者：泳灘涉及家庭活動和個人休閒，密集攝錄可能取得大量不相關影像。  政策取捨：只有在必要且相稱時才研究限量監測，並依法保護個資。","glossary":[{"id":"gloss:against:148:1","english":"all-day cameras","chinese":"全天攝錄"},{"id":"gloss:against:148:2","english":"personal privacy","chinese":"個人私隱"},{"id":"gloss:against:148:3","english":"unrelated people","chinese":"無關人士"},{"id":"gloss:against:148:4","english":"recording risk","chinese":"錄影風險"},{"id":"gloss:against:148:5","english":"limited use","chinese":"有限使用"}]},{"id":"arg:against:149","number":149,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"人工智能識別有可能錯把進食當作餵鳥 [反對觀點][科技誤判]","description":"反對理由／受影響者：系統可能見到遊客手持食物和鳥群靠近，卻不清楚是否真的向鳥撒糧。  政策取捨：技術只提示人工檢查，不能自動裁定違法。","glossary":[{"id":"gloss:against:149:1","english":"computer mistake","chinese":"電腦錯誤"},{"id":"gloss:against:149:2","english":"hold food","chinese":"手持食物"},{"id":"gloss:against:149:3","english":"false alarm","chinese":"錯誤警報"},{"id":"gloss:against:149:4","english":"human check","chinese":"人工檢查"},{"id":"gloss:against:149:5","english":"fair decision","chinese":"公平判斷"}]},{"id":"arg:against:150","number":150,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"影像長期保存會增加外洩與濫用風險 [反對觀點][資料安全]","description":"反對理由／受影響者：即使開始為防餵鴿收集影片，日後可能有人想改作其他目的或不當分享。  政策取捨：訂資料用途、存取、刪除和正式調查例外的明確規則。","glossary":[{"id":"gloss:against:150:1","english":"data leak","chinese":"資料外洩"},{"id":"gloss:against:150:2","english":"safe storage","chinese":"安全儲存"},{"id":"gloss:against:150:3","english":"use of videos","chinese":"影片用途"},{"id":"gloss:against:150:4","english":"delete data","chinese":"刪除資料"},{"id":"gloss:against:150:5","english":"set limits","chinese":"設定界線"}]},{"id":"arg:against:151","number":151,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"旅遊業會擔心額外講解令行程延誤 [反對觀點][營運成本]","description":"反對理由／受影響者：導遊每天處理交通、集合、入場與購物，新增長篇禁餵課堂會擠壓遊覽時間。  政策取捨：將提醒壓縮至30秒並供官方現成圖卡，減少重複準備。","glossary":[{"id":"gloss:against:151:1","english":"tour schedule","chinese":"旅遊行程"},{"id":"gloss:against:151:2","english":"time pressure","chinese":"時間壓力"},{"id":"gloss:against:151:3","english":"short talk","chinese":"短講"},{"id":"gloss:against:151:4","english":"ready-made card","chinese":"現成圖卡"},{"id":"gloss:against:151:5","english":"keep on time","chinese":"準時進行"}]},{"id":"arg:against:152","number":152,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"旅監局不能任意把自願指引變成新的牌照義務 [反對觀點][法律權限]","description":"反對理由／受影響者：持牌旅行社及導遊固然可配合宣傳，但任何新增強制條件必須符合《旅遊業條例》與適用程序。  政策取捨：先採自願培訓；如需強制則須合法諮詢與評估。","glossary":[{"id":"gloss:against:152:1","english":"legal powers","chinese":"法定權力"},{"id":"gloss:against:152:2","english":"new requirement","chinese":"新增要求"},{"id":"gloss:against:152:3","english":"voluntary rule","chinese":"自願規則"},{"id":"gloss:against:152:4","english":"fair process","chinese":"公平程序"},{"id":"gloss:against:152:5","english":"industry views","chinese":"業界意見"}]},{"id":"arg:against:153","number":153,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"不參團的自由行遊客可能收不到導遊提醒 [反對觀點][覆蓋不足]","description":"反對理由／受影響者：若所有教育資源只給旅行社，酒店住客及獨立遊客就可能漏掉資訊。  政策取捨：須同時保留現場標示、旅發局網頁及其他接觸點。","glossary":[{"id":"gloss:against:153:1","english":"independent travel","chinese":"自由行"},{"id":"gloss:against:153:2","english":"travel group","chinese":"旅行團"},{"id":"gloss:against:153:3","english":"missing information","chinese":"缺少資訊"},{"id":"gloss:against:153:4","english":"visitor access","chinese":"遊客獲取資訊"},{"id":"gloss:against:153:5","english":"different channels","chinese":"不同渠道"}]},{"id":"arg:against:154","number":154,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"商戶可能不願承擔印刷與額外清潔費 [反對觀點][成本分擔]","description":"反對理由／受影響者：餐飲商戶或小販利潤有限，政府若無償要求他們增加管理工作，可能增加營商困難。  政策取捨：以免費素材及適用合約處理，不能把公共責任全部推給商戶。","glossary":[{"id":"gloss:against:154:1","english":"shop costs","chinese":"商戶成本"},{"id":"gloss:against:154:2","english":"small business","chinese":"小商戶"},{"id":"gloss:against:154:3","english":"free materials","chinese":"免費素材"},{"id":"gloss:against:154:4","english":"shared costs","chinese":"分擔成本"},{"id":"gloss:against:154:5","english":"reasonable request","chinese":"合理要求"}]},{"id":"arg:against:155","number":155,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"清潔改善可能治標不治本 [反對觀點][根本原因]","description":"反對理由／受影響者：即使天天清走鳥糞，只要仍有人撒糧，鴿群仍可能返回並再次留下污染。  政策取捨：需同時處理違規餵飼和食物殘留，不能單靠清潔評估成功。","glossary":[{"id":"gloss:against:155:1","english":"surface problem","chinese":"表面問題"},{"id":"gloss:against:155:2","english":"root cause","chinese":"根本原因"},{"id":"gloss:against:155:3","english":"repeat problem","chinese":"重複問題"},{"id":"gloss:against:155:4","english":"food source","chinese":"食物來源"},{"id":"gloss:against:155:5","english":"long-term answer","chinese":"長遠答案"}]},{"id":"arg:against:156","number":156,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"強行驅逐鳥群可能造成其他動物福利問題 [反對觀點][動物保護]","description":"反對理由／受影響者：不適當的噪音、追逐及物理措施可能令雀鳥受驚或受傷，亦影響海灘寧靜。  政策取捨：先由專業人員評估低傷害方法，不以趕走鳥作唯一目標。","glossary":[{"id":"gloss:against:156:1","english":"loud noise","chinese":"巨大噪音"},{"id":"gloss:against:156:2","english":"scared birds","chinese":"受驚雀鳥"},{"id":"gloss:against:156:3","english":"physical harm","chinese":"身體傷害"},{"id":"gloss:against:156:4","english":"gentle method","chinese":"溫和方法"},{"id":"gloss:against:156:5","english":"expert advice","chinese":"專家建議"}]},{"id":"arg:against:157","number":157,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"只治理淺水灣可能把聚集問題轉往周邊地區 [反對觀點][問題轉移]","description":"反對理由／受影響者：鳥群和餵飼者可能改到另一段海灘或附近街道，令統計上的淺水灣改善掩蓋整體變差。  政策取捨：需檢查鄰近場地而非只看單一指標。","glossary":[{"id":"gloss:against:157:1","english":"move elsewhere","chinese":"轉往別處"},{"id":"gloss:against:157:2","english":"nearby places","chinese":"附近地方"},{"id":"gloss:against:157:3","english":"hidden cost","chinese":"隱藏成本"},{"id":"gloss:against:157:4","english":"whole area","chinese":"整個地區"},{"id":"gloss:against:157:5","english":"check nearby","chinese":"檢查附近"}]},{"id":"arg:against:158","number":158,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"過度依賴義工可能令前線承受衝突風險 [反對觀點][人員安全]","description":"反對理由／受影響者：義工沒有法定搜查或罰款權，卻可能被遊客當成執法人員而發生爭執。  政策取捨：限制義工只做教育及通報，必要時由正式人員接手。","glossary":[{"id":"gloss:against:158:1","english":"volunteer safety","chinese":"義工安全"},{"id":"gloss:against:158:2","english":"no legal power","chinese":"沒有法定權力"},{"id":"gloss:against:158:3","english":"public argument","chinese":"公眾爭執"},{"id":"gloss:against:158:4","english":"clear role","chinese":"清晰角色"},{"id":"gloss:against:158:5","english":"call staff","chinese":"通知職員"}]},{"id":"arg:against:159","number":159,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"一段短片可能令政策過度回應個別事件 [反對觀點][證據不足]","description":"反對理由／受影響者：單一新聞能揭示風險，但不足以證明全港遊客普遍有同一行為，也不能證明某方案一定有效。  政策取捨：先蒐集基線資料，再考慮擴大政策。","glossary":[{"id":"gloss:against:159:1","english":"single event","chinese":"個別事件"},{"id":"gloss:against:159:2","english":"strong evidence","chinese":"有力證據"},{"id":"gloss:against:159:3","english":"avoid overreaction","chinese":"避免過度反應"},{"id":"gloss:against:159:4","english":"collect facts","chinese":"收集事實"},{"id":"gloss:against:159:5","english":"careful planning","chinese":"審慎規劃"}]},{"id":"arg:against:160","number":160,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"劃出過大禁入區會損害公眾享用沙灘的權利 [反對觀點][公平使用]","description":"反對理由／受影響者：若為減少鴿群聚集而長期圍起大面積泳灘，守規則的遊客也受限制。  政策取捨：只在有特別風險及法定依據下採短期、最小範圍安排。","glossary":[{"id":"gloss:against:160:1","english":"public access","chinese":"公眾使用權"},{"id":"gloss:against:160:2","english":"restricted area","chinese":"限制區域"},{"id":"gloss:against:160:3","english":"open beach","chinese":"開放泳灘"},{"id":"gloss:against:160:4","english":"short period","chinese":"短暫期間"},{"id":"gloss:against:160:5","english":"fair use","chinese":"公平使用"}]},{"id":"arg:against:161","number":161,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"只統計罰款張數可能鼓勵不必要執法 [反對觀點][政策誘因]","description":"反對理由／受影響者：如果部門以發單數量作成績，職員可能把時間放在容易開單的場景而非真正的健康與福利改善。  政策取捨：評估須同時看違規率、動物接觸、環境改善與公平投訴。","glossary":[{"id":"gloss:against:161:1","english":"fine numbers","chinese":"罰款張數"},{"id":"gloss:against:161:2","english":"wrong target","chinese":"錯誤目標"},{"id":"gloss:against:161:3","english":"staff pressure","chinese":"員工壓力"},{"id":"gloss:against:161:4","english":"real improvement","chinese":"真正改善"},{"id":"gloss:against:161:5","english":"balanced review","chinese":"平衡評估"}]},{"id":"arg:against:162","number":162,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"試行前後的變化未必由政策造成 [反對觀點][研究限制]","description":"反對理由／受影響者：天氣、海灘活動及旅行團數量都會改變，即使餵飼次數下降也不能立即歸因於標示。  政策取捨：應以相近時段、比較地點及透明資料作審慎分析。","glossary":[{"id":"gloss:against:162:1","english":"weather effect","chinese":"天氣影響"},{"id":"gloss:against:162:2","english":"visitor change","chinese":"遊客變化"},{"id":"gloss:against:162:3","english":"cause and effect","chinese":"因果關係"},{"id":"gloss:against:162:4","english":"compare fairly","chinese":"公平比較"},{"id":"gloss:against:162:5","english":"study limits","chinese":"研究限制"}]},{"id":"arg:against:163","number":163,"angle":"M｜最強反對意見、成本及意外後果（政策壓力測試）","title":"疫情式警告及嚴厲態度可能損害香港友善旅遊形象 [反對觀點][溝通取捨]","description":"反對理由／受影響者：如果所有宣傳都強調疾病與處罰，守規矩旅客可能覺得被預先當成違法者。  政策取捨：採友善語氣說明理由，同時明確列出不得餵鳥的法例。","glossary":[{"id":"gloss:against:163:1","english":"friendly city","chinese":"友善城市"},{"id":"gloss:against:163:2","english":"public image","chinese":"公眾形象"},{"id":"gloss:against:163:3","english":"respect visitors","chinese":"尊重遊客"},{"id":"gloss:against:163:4","english":"avoid fear","chinese":"避免恐懼"},{"id":"gloss:against:163:5","english":"clear rules","chinese":"清楚規則"}]}],"structures":[{"id":"structure:1","number":1,"english":"From my point of view, ...","purpose":"提出立場"},{"id":"structure:2","number":2,"english":"I believe ... because ...","purpose":"提出觀點與理由"},{"id":"structure:3","number":3,"english":"The main problem is that ...","purpose":"指出核心問題"},{"id":"structure:4","number":4,"english":"We need to think about ...","purpose":"引出需要考慮的因素"},{"id":"structure:5","number":5,"english":"One reason for this is ...","purpose":"解釋原因"},{"id":"structure:6","number":6,"english":"This matters because ...","purpose":"說明重要性"},{"id":"structure:7","number":7,"english":"For example, ...","purpose":"引入例子"},{"id":"structure:8","number":8,"english":"In this case, ...","purpose":"連結新聞個案"},{"id":"structure:9","number":9,"english":"If ..., ... may ...","purpose":"推測可能後果"},{"id":"structure:10","number":10,"english":"This could lead to ...","purpose":"推論進一步影響"},{"id":"structure:11","number":11,"english":"The first step should be to ...","purpose":"提出先後次序"},{"id":"structure:12","number":12,"english":"One possible solution is to ...","purpose":"提出可行方案"},{"id":"structure:13","number":13,"english":"The government could work with ... to ...","purpose":"提出跨方合作"},{"id":"structure:14","number":14,"english":"Instead of ..., we could ...","purpose":"提出替代方法"},{"id":"structure:15","number":15,"english":"This would help ... to ...","purpose":"解釋方案作用"},{"id":"structure:16","number":16,"english":"A possible problem is ...","purpose":"提醒實施問題"},{"id":"structure:17","number":17,"english":"Although ... is important, ...","purpose":"先承認另一方觀點"},{"id":"structure:18","number":18,"english":"I agree up to a point, but ...","purpose":"部分同意後提出反駁"},{"id":"structure:19","number":19,"english":"We should balance ... with ...","purpose":"權衡不同目標"},{"id":"structure:20","number":20,"english":"Overall, I think ...","purpose":"綜合收結"}]}],"resources":[{"title":"教材概覽與思考題","markdown":"**Policy brainstorming | Tourism × Public Health × Animal Protection × Resource Limits**  \n**繁體中文政策解釋 × B1–B2 英文詞彙｜2026 年 11 月 22 日｜Markdown 教學版**\n\n> **思考題：**假設你是負責管理香港熱門旅遊景點的政府官員，面對遊客違規餵飼及捕捉野鴿的情況，你會如何制定有效的管理方案，在有限執法資源下改善公共衞生、保障動物福利，同時維持良好的旅遊體驗？\n>\n> **教學原則：**本稿追求**獨立機制與不同持份者**，而非重複「多宣傳、多罰款」；每個正式論點包含 **[政策類型]、執行者與操作、效果與界線，以及剛好五組 B1–B2 英中 Glossary**。英文詞彙的 CEFR 難度屬編輯選詞判斷，沒有假稱逐詞取得官方分級證書。"},{"title":"0｜新聞事實與不可越過的界線","markdown":"- **【報道內容】**2026 年 11 月 21 日，媒體報道一段據稱攝於淺水灣泳灘的影片：有人向野鴿撒糧、鴿群聚集；有男童捉鴿供拍照，其後將雀鳥拋起放走，報道稱過程中有羽毛掉落。**這不是已完成的警方或漁護署調查結論。** [S01]\n- **【不明資料】**影片中人士的國籍、是否跟團、餵飼物品成分、雀鳥是否受傷、執法結果，均不可僅憑網民留言認定。不要將個別行為推廣成某地旅客的共同特徵。\n- **【公共衞生】**接觸雀鳥、排泄物或沾污環境有潛在健康風險；衞生防護中心建議避免直接接觸，接觸後以肥皂洗手。**本新聞並未證實禽流感或任何感染個案。** [S09]\n- **【政策目標】**把原本可能發生的「餵飼→鴿群聚集→捉鳥合照→鳥糞或食物殘留→投訴及清潔成本」風險鏈，分別在**遊客抵達前、進場時、現場行為、求助及事後評估**五個時點處理。"},{"title":"1｜現行制度與法律：不可把舊制度冒充新政策","markdown":"| 已核實事實 | 政策含義／不可偷換 | 依據 |\n|---|---|---|\n| **2024 年 8 月 1 日**起，全港禁止未經許可餵飼野生動物及野鴿。 | 不是只在淺水灣實施，也不是僅針對遊客。 | [S02] |\n| 非法餵飼可獲發 **HK$5,000 定額罰款通知書**；如經檢控定罪，最高可罰 **HK$100,000 及監禁一年**。 | 定額罰款與檢控的最高刑罰屬不同法律處理路徑，不可混作「首次違規必罰十萬」。 | [S02][S03] |\n| 自 **2024 年 9 月 1 日**起，執法人員可就非法餵飼**不先口頭警告而直接執法**。 | 現場教育是預防，不等於每宗已發生違規都必須先勸告。 | [S03] |\n| 漁護署、警務處及**獲委任**的食環署、康文署、房屋署人員在適用範圍內可執行禁餵規定。 | 「獲委任」是關鍵；酒店員工、導遊及一般義工不能自行發出法定罰款。 | [S02] |\n| **淺水灣泳灘由康文署管理**。 | 康文署是泳灘日常設施及管理主責；房屋署負責轄下屋邨，不應被安排成淺水灣泳灘常駐巡查主責。 | [S04] |\n| 漁護署與相關部門已採按風險巡查、跨部門合作，以及部分地點 AI 監測試點。 | 「重新配置人手、檢討擴展」是建議；「首次提出 AI 監察」不是。 | [S05] |\n| **野鴿禁餵**與**捉鳥／虐待動物**是不同法律問題。第170章保護適用的野生雀鳥；第169章針對造成不必要痛苦的行為。 | 影片顯示抓起雀鳥，不自動證明已構成某項法定罪行；須由合適部門依雀鳥法定身分、行為、證據和相關條文判斷。 | [S07][S08] |\n| **1823** 可接收懷疑非法餵飼舉報並轉介跟進。 | 建議是縮短及清晰化分流，不是虛構新設熱線。 | [S14] |"},{"title":"2｜跨部門與非政府持份者：誰做甚麼？","markdown":"| 機構／持份者 | 現有或合理角色 | **具體可做** | 權限與限制 |\n|---|---|---|---|\n| **康樂及文化事務署（康文署）** | 淺水灣泳灘場地管理；獲委任人員可就禁餵執法 | 調整標示、清潔與巡查，收集現場情況，與漁護署聯合執法 | 不是每一名場地員工都自動有法定執法身分 |\n| **漁農自然護理署（漁護署）** | 禁餵法例、野生動物管理及相關執法；動物健康監察 | 設計風險熱點地圖、執法人員指引、必要時檢視雀鳥健康及個案轉介 | 不應將每次網上影片當成已定罪事實 |\n| **食物環境衞生署（食環署）** | 依管轄處理公共環境衞生及獲委任禁餵執法 | 協調毗鄰公眾地方食物殘渣／垃圾問題，與康文署交接 | 不替康文署管理其泳灘的一切設施 |\n| **香港警務處** | 適用的禁餵執法、罪案及涉嫌殘酷對待動物調查 | 有威脅、衝突或疑似虐待動物時依法跟進 | 一般場地提醒及清潔不需要每次由警方處理 |\n| **房屋署** | 獲委任人員在其管理場景處理禁餵；與跨部門小組交換經驗 | 分享屋邨黑點有效做法 | 不是淺水灣泳灘的常規管理者 |\n| **環境及生態局** | 跨部門政策統籌 | 訂防餵飼、衞生及生態整體目標與資源優次 | 不代替法定執法人員現場決定 |\n| **文化體育及旅遊局／旅遊事務署** | 旅遊政策協調 | 與旅發局、旅監局及業界研究遊客教育 | 不是《野生動物保護條例》日常執法單位 |\n| **旅遊業監管局（旅監局）** | 依法規管持牌旅行社及導遊 | 在其職權內提供培訓指引、核查持牌業界做法 | 不能直接向所有獨立遊客發禁餵罰款；額外牌照義務需依法審議 |\n| **香港旅遊發展局（旅發局）** | 旅遊資訊及宣傳 | 旅客出發前提醒、非接觸式賞鳥及拍照建議 | 不是刑事或禁餵執法機關 |\n| **衞生署衞生防護中心** | 公眾健康資訊 | 提供接觸雀鳥、手部清潔及疾病風險的準確資訊 | 不應把未確認的個案說成疫症 |\n| **南區民政事務處** | 區內部門、居民及商戶協作 | 召開短會了解居民投訴與遊客高峰 | 不擁有獨立禁餵罰款權 |\n| **1823** | 政府查詢與投訴轉介 | 接收位置、時間及簡短證據，再轉交合適部門 | 不是即時野鳥救援或危急事故救護電話 |\n| **旅行社及持牌導遊** | 團體資訊、行程及安全提醒 | 集合前說明「不餵、不捉」並提醒家長看顧兒童 | 導遊不能代警員查身分、罰款或強制搜身 |\n| **酒店、旅遊平台及交通營辦商** | 旅客出發前資訊觸點 | 房卡、訂票確認頁、入港資訊及遊客地圖加入簡短提醒 | 需要合作及適當成本安排 |\n| **食肆、攤檔及物業管理公司** | 食物和廢物管理 | 蓋好垃圾桶、迅速處理殘渣、提醒顧客 | 可提醒／聯絡部門，不能冒充執法人員 |\n| **家長、教師及活動領隊** | 兒童看顧及教育 | 教導遠距離觀察、不抓鳥拍照 | 不以公開羞辱兒童代替教育或法定程序 |\n| **動物福利團體、鳥類學者及合資格救援者** | 科普、救援及專業建議 | 評估雀鳥受傷、提供遠距離觀鳥方法 | 不承擔任意捕捉或普遍警務職能 |\n| **本地居民、游客、市民義工** | 舉報、守規則、提供現場意見 | 不自行執法、不追捕動物、不公開兒童容貌 | 保留公平、私隱及人身安全界線 |"},{"title":"3｜政策類型標籤（可複選）","markdown":"`[教育]` 向遊客說清楚；`[資訊提醒]` 在決策時點提示；`[公共服務]` 提供設施及支援；`[巡查]` 管理人手；`[執法]` 依法處理；`[處罰]` 違規後果；`[誘因]` 鼓勵自願合作；`[規管]` 訂明責任或程序；`[合作]` 部門及業界協調；`[場地設計]` 改變活動空間；`[動物保護]` 減少對雀鳥傷害；`[衞生]` 減少排泄物、污染及接觸；`[科技]` 補助辨識而非取代判斷；`[私隱]` 控制資料收集；`[評估]` 驗證效果；`[試行]` 小規模試用；`[財務安排]` 事先決定誰付費；`[程序公平]` 申訴、核實與一致標準。\n\n**政策狀態：**下文除非明確註明「既有」或「現行制度延伸」，一律視為**供討論的新建議／試點**；不能把提案當作已獲批准的香港政策。"},{"title":"4｜優先行動：不增加大量編制的六星期試行方案（示例）","markdown":"| 時間 | 負責者 | 操作安排 | 預期作用／驗收方法 |\n|---|---|---|---|\n| **第 1 週** | 康文署、漁護署、食環署 | 分清泳灘與鄰接地點；記下 3 個高風險時段及可見行為 | 先確定哪裏需要資源，不預設全天大量執法 |\n| **第 2 週** | 康文署、旅發局、旅行社／酒店 | 在實際入口及聚集點放雙語圖像標示；增加導遊上車提醒 | 實地看是否被注意；不是只計印了多少張海報 |\n| **第 3–4 週** | 康文署獲委任人員、漁護署及有需要的警方 | 依投訴與觀察作**短時段精準巡查**，在有足夠證據時按現行法例處理 | 比較違規、重複聚集及每人時投入，不預設「先警告」義務 |\n| **第 3–5 週** | 康文署、場地商戶、義工 | 降低易得食物殘渣、提供安全拍照點、更新洗手與垃圾設施 | 查看鳥糞／垃圾是否減少、訪客是否仍能觀光 |\n| **第 6 週** | 漁護署主導政策回顧、康文署及相關部門參與 | 用同一時段及相近地點比較前後數據；公開不含身分的簡短結果 | 決定延長、調整或停止試行，而非以罰款收入為成敗 |\n\n**資源安排：**先利用既有巡查路線與旅遊資訊接觸點；新增標示、培訓和小型調查按部門既有採購／支出程序決定。六星期、熱點數目與分工表均為**教學方案**，非政府公布安排。"},{"title":"5.0｜政策類別與數量索引","markdown":"| 類別 | 視角 | 政策／論點數 |\n|---|---|---:|\n| A | 現場標示與即時勸導：在決定餵飼之前介入 | 12 |\n| B | 旅遊旅程：旅行社、導遊、酒店與旅發局 | 12 |\n| C | 家庭、兒童、教育與無接觸拍照 | 10 |\n| D | 有限人手下的巡查、執法與程序公平 | 15 |\n| E | 野鴿福利、捕捉行為及專業救援 | 11 |\n| F | 環境衞生、食物殘渣和公共健康 | 12 |\n| G | 景點空間、設施及遊客體驗設計 | 11 |\n| H | 商戶、旅遊業與非金錢／經濟誘因 | 10 |\n| I | 市民報告、社區互助與公眾參與 | 11 |\n| J | 科技、數據、監控邊界與私隱 | 11 |\n| K | 具名政府分工、跨部門合作與資源配置 | 12 |\n| L | 成效評估、長期改進及生態治理 | 12 |\n| M | 最強反對意見、成本及意外後果（政策壓力測試） | 24 |\n| **合計** | **政策 139 ＋ 反對／限制 24** | **163** |\n\n*每項五組 Glossary，合共 **815 組**。本目標不為任何論點設定硬性上限；已逐項檢查不同因果或持份者。*\n\n\n### A｜現場標示與即時勸導：在決定餵飼之前介入\n\n\n#### 001. 在泳灘入口以一眼讀懂的圖文列明禁餵與罰則 [教育][資訊提醒]\n\n**誰負責／怎樣做：**康文署在淺水灣主要入口設「不餵鴿／5,000元定額罰款」圖像告示，漁護署提供統一法律文字。  **作用／限制：**在行為發生前提醒，比事後追人更省人手；罰則須區分定額罰款與法院最高刑罰。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| entry sign | 入口標示 |\n| feeding ban | 餵飼禁令 |\n| fixed penalty | 定額罰款 |\n| visitor rules | 遊客規則 |\n| clear message | 清晰訊息 |\n\n#### 002. 把「不捉鳥拍照」與「不餵飼」分開提示 [教育][動物保護]\n\n**誰負責／怎樣做：**康文署以兩幅簡單插圖展示「不給食物」及「不抓起雀鳥」，漁護署核對法律和動物福利文字。  **作用／限制：**有人可能知道禁餵卻以為可以抱鳥合照；兩種行為的法律判斷仍須分開。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| do not touch | 不要觸碰 |\n| catch a bird | 捕捉雀鳥 |\n| safe photos | 安全拍照 |\n| animal care | 動物照顧 |\n| follow the rules | 遵守規則 |\n\n#### 003. 將告示設在遊客真正停下來的位置 [場地設計][資訊提醒]\n\n**誰負責／怎樣做：**康文署先觀察遊客在哪些涼亭、長椅及拍照點撒糧，再把小型告示放在相關路線而非僅在辦公室入口。  **作用／限制：**提高看見機會而不需要新增大量人員；標示不能阻塞逃生或行動不便人士通道。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| popular spot | 熱門位置 |\n| easy to notice | 容易留意 |\n| walking path | 步行路徑 |\n| visitor stop | 遊客停留點 |\n| open access | 暢通通道 |\n\n#### 004. 按假日人流移動便攜式提示牌 [時間管理][試行]\n\n**誰負責／怎樣做：**康文署於周末及長假按巡場紀錄移動可重用提示牌，平日移回真正有需要的位置。  **作用／限制：**避免在人少時長期佔用設施；需防海風推倒牌架。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| holiday crowd | 假日人潮 |\n| portable sign | 可移動告示 |\n| move the sign | 移動告示 |\n| busy period | 繁忙時段 |\n| safe position | 安全位置 |\n\n#### 005. 用繁簡中文與英文配合圖示提醒 [教育][平等]\n\n**誰負責／怎樣做：**康文署與旅發局製作可讀的繁體、簡體中文及英文短句，並以圖像照顧不熟悉文字的遊客。  **作用／限制：**針對語言障礙而非猜測任何人的國籍；不同版本必須表達相同法律要求。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| language choice | 語言選擇 |\n| simple English | 簡單英文 |\n| picture signs | 圖像標示 |\n| read the notice | 閱讀告示 |\n| equal access | 平等獲取資訊 |\n\n#### 006. 在沙灘近食物區提醒先收好食物 [衞生][資訊提醒]\n\n**誰負責／怎樣做：**康文署與相關食肆營辦者在外賣及休憩區張貼「食物不要放在鴿子可取之處」提示。  **作用／限制：**減少食物落地與意外引來鴿群；不能把所有正常進食一律視為非法餵飼。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| cover your food | 蓋好食物 |\n| food leftovers | 食物殘渣 |\n| keep the area clean | 保持地方清潔 |\n| avoid attracting birds | 避免吸引雀鳥 |\n| picnic area | 野餐區 |\n\n#### 007. 以三步驟口號取代密集法例文字 [教育][資訊提醒]\n\n**誰負責／怎樣做：**漁護署與康文署統一用「看鳥、拍照、不餵不捉」作旅客語言，再在旁附正式法例連結。  **作用／限制：**短訊容易記住；口號不可取代完整法定告示或扭曲相關法律。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| watch from afar | 從遠處觀看 |\n| enjoy the view | 欣賞景色 |\n| keep your distance | 保持距離 |\n| easy steps | 簡單步驟 |\n| remember the rule | 記住規則 |\n\n#### 008. 在高峰時段安排短而固定的廣播 [資訊提醒][時間管理]\n\n**誰負責／怎樣做：**康文署如現場設備合適，可在下午人潮高峰播放15秒普通話、粵語及英文提醒，不循環轟炸遊客。  **作用／限制：**能同時通知較多人；廣播太密會損害泳灘寧靜及景點體驗。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| short message | 簡短訊息 |\n| public announcement | 公眾廣播 |\n| busy hours | 繁忙時間 |\n| too much noise | 過量噪音 |\n| quiet beach | 寧靜泳灘 |\n\n#### 009. 一線員工使用統一而有禮貌的提醒句 [培訓][程序公平]\n\n**誰負責／怎樣做：**康文署培訓場地職員先保持安全距離、指出規則、邀請停止行為，再按職權通知獲委任執法人員。  **作用／限制：**減少衝突和前線員工自行作法律裁判；遇威脅即退出並尋求支援。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| polite reminder | 有禮貌提醒 |\n| frontline staff | 前線員工 |\n| calm voice | 平靜語氣 |\n| ask for help | 尋求協助 |\n| avoid conflict | 避免衝突 |\n\n#### 010. 設立「一分鐘懂禁餵」官方網頁連結 [科技][資訊提醒]\n\n**誰負責／怎樣做：**康文署在場地告示附漁護署官方短連結及 QR 碼，內容同時介紹罰則、衞生與安全拍照方法。  **作用／限制：**讓有需要的人自行查詳情；基本禁令仍須在牌面可見，不能強迫使用手機。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| official website | 官方網站 |\n| QR code | 二維碼 |\n| more details | 更多資料 |\n| phone access | 手機存取 |\n| no app needed | 不需安裝應用程式 |\n\n#### 011. 對殘缺或被遮擋的告示採用固定檢查表 [場地管理][評估]\n\n**誰負責／怎樣做：**康文署讓現有巡場人員每周檢查告示是否被樹葉遮擋、風雨損壞或褪色，集中一次維修。  **作用／限制：**資訊有效程度取決於能否看見；避免只計設置數量。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| weekly check | 每周檢查 |\n| broken sign | 損壞告示 |\n| clear view | 清楚視野 |\n| repair quickly | 盡快維修 |\n| checklist | 檢查清單 |\n\n#### 012. 設立小型「文明觀鳥」流動攤位 [教育][試行]\n\n**誰負責／怎樣做：**漁護署、康文署與合資格自然教育團體在少數假日設30分鐘簡介點，向家庭示範遠距觀鳥。  **作用／限制：**把規則轉為愉快體驗；先試高峰日，不宜全年長期占用人手。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| short talk | 短講 |\n| bird watching | 觀鳥 |\n| family learning | 家庭學習 |\n| weekend activity | 周末活動 |\n| helpful advice | 實用建議 |\n\n### B｜旅遊旅程：旅行社、導遊、酒店與旅發局\n\n\n#### 013. 把禁餵提醒放進旅行社的出發前訊息 [教育][旅遊協作]\n\n**誰負責／怎樣做：**持牌旅行社在行程確認電郵或集合通知加入一行「香港公共地方不要餵野鴿」；旅監局可向業界發參考指引。  **作用／限制：**讓旅客到場前已知規則；新強制牌照義務須另按法律程序審議。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| travel plan | 旅行計劃 |\n| trip message | 行程訊息 |\n| before arrival | 抵達前 |\n| travel agency | 旅行社 |\n| know the rules | 了解規則 |\n\n#### 014. 導遊抵達景點前作30秒示範說明 [培訓][旅遊協作]\n\n**誰負責／怎樣做：**持牌導遊在旅遊巴駛近淺水灣前，以簡短口語指出禁餵、切勿抱鳥合照，以及垃圾投放位置。  **作用／限制：**比到場後多人同時解釋有效率；導遊只是提醒者，不是執法人員。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| tour guide | 導遊 |\n| group talk | 團體簡介 |\n| short reminder | 簡短提醒 |\n| bus journey | 巴士旅程 |\n| safe visit | 安全遊覽 |\n\n#### 015. 導遊收到官方一頁式景點規則卡 [資訊提醒][合作]\n\n**誰負責／怎樣做：**旅監局與漁護署、康文署合作提供可打印圖卡給業界，由導遊向團員轉發。  **作用／限制：**降低每位導遊自行查法例的成本；須按最新法例更新版本。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| one-page guide | 一頁指引 |\n| printable card | 可列印卡片 |\n| travel group | 旅行團 |\n| updated information | 更新資訊 |\n| share the guide | 分享指引 |\n\n#### 016. 在旅行團集合點明確告知家長兒童禁抓野鳥 [兒童教育][旅遊協作]\n\n**誰負責／怎樣做：**旅行團領隊於下車前提醒家長看顧孩子，並說明抓鳥玩耍會嚇怕動物和帶來接觸風險。  **作用／限制：**把注意力放在看顧和安全；不得對未確認涉事兒童作公開指責。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| watch your child | 看顧子女 |\n| young visitors | 年幼遊客 |\n| do not catch birds | 不要抓鳥 |\n| parent reminder | 家長提醒 |\n| animal safety | 動物安全 |\n\n#### 017. 旅發局在熱門景點介紹頁附「守護景點」資訊 [旅遊協作][資訊公開]\n\n**誰負責／怎樣做：**旅發局在淺水灣旅遊網頁或合適宣傳材料列出三個易明守則，連到漁護署正式資料。  **作用／限制：**訪客規劃行程時先接收資訊；旅發局負責宣傳，並非罰款執行。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| visitor website | 遊客網頁 |\n| place guide | 景點指南 |\n| plan a trip | 規劃旅程 |\n| visitor advice | 遊客建議 |\n| travel information | 旅遊資訊 |\n\n#### 018. 在酒店前台提供小型安全旅遊卡 [合作][資訊提醒]\n\n**誰負責／怎樣做：**淺水灣及港島酒店可自願把主要景點的禁餵、環保及求助資料放在前台或電子入住訊息。  **作用／限制：**接觸不參團的遊客；不可假定所有酒店願意無成本承擔宣傳。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| hotel desk | 酒店前台 |\n| welcome card | 迎賓卡 |\n| guest information | 住客資訊 |\n| local advice | 本地建議 |\n| helpful tips | 實用提示 |\n\n#### 019. 在跨境交通接觸點延續已有禁餵宣傳 [資訊提醒][合作]\n\n**誰負責／怎樣做：**漁護署已曾在口岸、港鐵及跨境巴士刊登相關訊息；可與運輸業界檢討應在哪些假期重播。  **作用／限制：**將資源投向新增遊客高峰，而非誤稱這項宣傳尚未出現。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| border point | 邊境口岸 |\n| holiday travel | 假期旅遊 |\n| public transport | 公共交通 |\n| remind visitors | 提醒遊客 |\n| seasonal message | 季節性訊息 |\n\n#### 020. 旅遊巴公司在常去景點的車窗貼提示 [合作][資訊提醒]\n\n**誰負責／怎樣做：**旅遊巴營辦商可自願在車門內側放小貼紙，提醒團員下車後不餵鳥、不留下零食。  **作用／限制：**在下車的一刻提醒；須避免遮擋車窗視線。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| coach bus | 旅遊巴 |\n| door notice | 車門提示 |\n| before getting off | 下車之前 |\n| safe travel | 安全旅行 |\n| keep windows clear | 保持車窗清晰 |\n\n#### 021. 在旅遊行程中加入「遠距看野鳥」替代活動 [旅遊設計][教育]\n\n**誰負責／怎樣做：**旅行社與自然教育導遊可安排望遠鏡觀鳥及海灘景觀解說，取代以餵食吸引鳥隻的拍照玩法。  **作用／限制：**保留自然接觸的吸引力；避免動物被過量人流追逐。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| bird watching | 觀鳥 |\n| use binoculars | 使用望遠鏡 |\n| seaside view | 海濱景色 |\n| nature tour | 自然導賞 |\n| watch from a distance | 遠距觀看 |\n\n#### 022. 為自由行遊客準備可下載的景點規則地圖 [公共服務][資訊公開]\n\n**誰負責／怎樣做：**康文署與旅發局提供簡單地圖，標示公共廁所、洗手處、垃圾桶及官方禁餵資訊。  **作用／限制：**不只服務旅行團；地圖應保留離線可讀版本。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| free map | 免費地圖 |\n| public toilet | 公廁 |\n| washing area | 洗手位置 |\n| download a map | 下載地圖 |\n| independent visitor | 自由行遊客 |\n\n#### 023. 在社交平台景點介紹中放置不餵鳥拍照提示 [平台協作][教育]\n\n**誰負責／怎樣做：**旅發局與願意合作的旅遊內容創作者發布不餵鳥也能拍出美照的短片，附官方禁餵資訊。  **作用／限制：**回應遊客想拍照的動機；宣傳內容不得暗示觸摸野鴿很安全。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| travel video | 旅遊短片 |\n| photo advice | 拍照建議 |\n| social media | 社交媒體 |\n| share good habits | 分享良好習慣 |\n| official link | 官方連結 |\n\n#### 024. 以實際旅客提問改進多語言旅遊訊息 [評估][服務設計]\n\n**誰負責／怎樣做：**旅發局與旅監局定期收集導遊及訪客最常問的三個問題，交漁護署核對答案再更新材料。  **作用／限制：**以真實理解困難修訂資訊；勿為調查收集不必要的身分資料。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| visitor questions | 遊客問題 |\n| common mistakes | 常見錯誤 |\n| clear answers | 清楚答案 |\n| improve the guide | 改善指引 |\n| protect details | 保護個人資料 |\n\n### C｜家庭、兒童、教育與無接觸拍照\n\n\n#### 025. 用兒童語言說明「好心餵鳥也可能傷害鳥」 [兒童教育][動物保護]\n\n**誰負責／怎樣做：**學校、家長和自然教育團體以簡單圖畫解釋野鴿會自行找食物，並非需要遊客餵養。  **作用／限制：**處理兒童可能源於好奇和善意的動機；不把所有孩子視為故意違規者。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| good intentions | 好意 |\n| find food | 尋找食物 |\n| wild bird | 野鳥 |\n| simple drawing | 簡單圖畫 |\n| care for animals | 愛護動物 |\n\n#### 026. 親子遊覽前訂立「看得到、不摸到」約定 [家長責任][預防]\n\n**誰負責／怎樣做：**家長在沙灘入口與孩子約定保持距離、不追逐、不抓鳥，並說明遇鳥靠近時慢慢退後。  **作用／限制：**在突發興奮之前訂規則更容易執行；成人須以自身行為示範。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| family agreement | 家庭約定 |\n| keep a distance | 保持距離 |\n| do not chase | 不要追逐 |\n| step back | 向後退 |\n| set an example | 以身作則 |\n\n#### 027. 讓兒童用望遠鏡或畫畫代替抓鳥 [活動替代][教育]\n\n**誰負責／怎樣做：**自然教育團體與康文署合作舉辦短時段免費繪鳥活動或借出觀鳥工具。  **作用／限制：**回應「想靠近動物」的好奇心；設備借用須有管理與維護安排。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| draw a bird | 畫鳥 |\n| look closely | 仔細觀察 |\n| borrow equipment | 借用器材 |\n| creative activity | 創意活動 |\n| learn about nature | 學習自然知識 |\n\n#### 028. 家長主動阻止以雀鳥作真人拍照道具 [家長責任][動物保護]\n\n**誰負責／怎樣做：**家長及同行成人在有人試圖捉鳥時先勸孩子放手、退後，必要時請場地職員協助。  **作用／限制：**成年人的即場引導可阻止繼續傷害；不要以暴力搶奪雀鳥或圍觀刺激。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| object for photos | 拍照道具 |\n| ask a child to stop | 請孩子停止 |\n| adult guidance | 成人指導 |\n| stay calm | 保持冷靜 |\n| get staff help | 尋求職員協助 |\n\n#### 029. 學校戶外考察前加入一分鐘野鳥禮儀 [校本教育][預防]\n\n**誰負責／怎樣做：**學校和戶外教育機構在出發清單加入不餵飼、不觸碰、帶走垃圾三項守則。  **作用／限制：**讓守規則成為校外學習一部分；校方不能保證每位家庭遊客已接受教育。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| school trip | 學校考察 |\n| field visit | 戶外參觀 |\n| group rules | 團體守則 |\n| take litter home | 帶走垃圾 |\n| outdoor learning | 戶外學習 |\n\n#### 030. 以家庭遊戲卡教孩子辨識安全與不安全行為 [兒童教育][活動替代]\n\n**誰負責／怎樣做：**旅發局可與教育團體提供免費圖卡，讓孩子選出「遠距拍照」「撒糧」「抱鳥」的不同後果。  **作用／限制：**用參與式學習代替訓斥；答案須與實際法律及衞生建議一致。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| learning game | 學習遊戲 |\n| picture card | 圖像卡 |\n| safe action | 安全行為 |\n| make a choice | 作出選擇 |\n| explain the answer | 解釋答案 |\n\n#### 031. 對涉事兒童採取尊重而不公開羞辱的處理 [程序公平][兒童保障]\n\n**誰負責／怎樣做：**前線職員先制止有風險的行為、尋找同行成人並記錄必要事實；涉嫌違法交依法有權的部門處理。  **作用／限制：**保護兒童尊嚴與程序公平；不能以網上「人肉搜尋」代替調查。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| respect children | 尊重兒童 |\n| private talk | 私下交談 |\n| adult support | 成人支援 |\n| fair process | 公平程序 |\n| avoid public shame | 避免公開羞辱 |\n\n#### 032. 教育同行成人不要以動物掙扎為娛樂 [教育][動物保護]\n\n**誰負責／怎樣做：**動物福利團體與導遊在家長短講中說明羽毛脫落、驚嚇及不當抓握可能造成風險，並建議改拍自然景觀。  **作用／限制：**同時處理拍照者和拍照協助者的行為；不憑一段影片診斷實際傷勢。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| bird movement | 雀鳥動作 |\n| rough handling | 粗暴抓握 |\n| animal stress | 動物受驚 |\n| safe photo | 安全照片 |\n| change the activity | 改變活動方式 |\n\n#### 033. 由青少年義工設計同齡人喜歡的「不餵鳥」創意海報 [公眾參與][教育]\n\n**誰負責／怎樣做：**學校、青年中心與康文署舉辦小型設計活動，評選後在獲批准場地展示。  **作用／限制：**增強年輕人的參與感；海報必須提供正確規則，而非嘲弄遊客。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| young volunteers | 青年義工 |\n| poster design | 海報設計 |\n| creative message | 創意訊息 |\n| school project | 學校項目 |\n| respect visitors | 尊重遊客 |\n\n#### 034. 為有特殊學習需要的家庭提供圖像指引 [無障礙][兒童保障]\n\n**誰負責／怎樣做：**康文署與特殊教育及社福團體調整圖片大小和句子長度，方便不同能力兒童理解保持距離。  **作用／限制：**改善真正的資訊可達性；不應假定某類兒童更容易違規。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| visual guide | 視覺指引 |\n| different needs | 不同需要 |\n| simple pictures | 簡單圖片 |\n| easy instructions | 易明指示 |\n| include everyone | 照顧所有人 |\n\n### D｜有限人手下的巡查、執法與程序公平\n\n\n#### 035. 把巡查集中在有實際證據的餵飼黑點 [巡查][資源分配]\n\n**誰負責／怎樣做：**漁護署與康文署以1823投訴、現場觀察、鳥群聚集和鳥糞情況，選出需要加強處理的泳灘位置。  **作用／限制：**用相同準則分配有限人手；單次網上影片不足以代表全年問題。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| problem area | 問題地點 |\n| risk level | 風險程度 |\n| local reports | 地區報告 |\n| site check | 現場檢查 |\n| limited staff | 有限人手 |\n\n#### 036. 採短時段機動巡查而非全天駐守 [時間管理][巡查]\n\n**誰負責／怎樣做：**康文署獲委任人員在周末旅遊團抵達及下午聚集時段巡查，漁護署按情報支援特別行動。  **作用／限制：**把人員放在違規較可能發生時；時間安排應定期改變以防被刻意避開。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| short patrol | 短時巡查 |\n| peak hours | 高峰時間 |\n| change shifts | 調整更次 |\n| use staff wisely | 善用人手 |\n| site visits | 實地巡查 |\n\n#### 037. 把泳灘管理與法定執法角色寫成雙層流程 [培訓][程序公平]\n\n**誰負責／怎樣做：**康文署一般場地員工可提示及通報；只有適用及獲委任的執法人員按現行法例調查及處理。  **作用／限制：**避免普通清潔員或救生員被誤要求開罰單；各自權限須在值勤卡上清楚。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| staff role | 員工角色 |\n| legal powers | 法定權力 |\n| report a case | 通報個案 |\n| clear duties | 清晰職責 |\n| proper action | 恰當行動 |\n\n#### 038. 在多次發生同類事件時安排漁護署與康文署聯合行動 [合作][執法]\n\n**誰負責／怎樣做：**漁護署可提供法例及鳥類知識，康文署提供泳灘現場動線與管理資料，雙方按需要排班。  **作用／限制：**以聯合行動處理較複雜黑點；不是每一次餵飼都要召集多部門。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| joint visit | 聯合巡查 |\n| share information | 分享資料 |\n| work together | 合作 |\n| special patrol | 特別巡查 |\n| clear task | 清晰任務 |\n\n#### 039. 只在跨越泳灘管理邊界時與食環署交接 [跨部門合作][資源分配]\n\n**誰負責／怎樣做：**康文署處理其泳灘內問題，食環署依自身管轄處理毗鄰食物及公眾環境衞生，雙方建立轉介聯絡點。  **作用／限制：**防止因「這地方不歸我管」而延誤；也避免同一位置兩隊重複巡查。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| area boundary | 區域界線 |\n| shared work | 共同工作 |\n| nearby street | 附近街道 |\n| avoid overlap | 避免重複 |\n| contact person | 聯絡人 |\n\n#### 040. 向房屋署借鑑屋邨禁餵經驗而不借錯職權 [部門合作][培訓]\n\n**誰負責／怎樣做：**漁護署在跨部門工作組分享房屋署屋邨黑點標示、執法時間等經驗，由康文署按泳灘條件改用。  **作用／限制：**重用已有經驗節省設計成本；房屋署不因此成為淺水灣泳灘的主責機關。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| learn from others | 向他人學習 |\n| housing estate | 公共屋邨 |\n| useful ideas | 實用做法 |\n| adapt the plan | 調整方案 |\n| different setting | 不同場景 |\n\n#### 041. 將「目擊疑似餵飼」與「證據足以採取行動」分開 [執法][程序公平]\n\n**誰負責／怎樣做：**獲委任執法人員按法律記錄時間、地點及可見行為，核實是否涉及實際餵飼，再採取合適程序。  **作用／限制：**保障公平並減少爭議；鳥隻靠近旅客不等於旅客一定餵飼。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| check the facts | 核實事實 |\n| actual action | 實際行為 |\n| fair decision | 公平決定 |\n| possible mistake | 可能誤判 |\n| clear record | 清楚紀錄 |\n\n#### 042. 執法當場提供簡明語言解釋與書面資料 [處罰][程序公平][資訊提醒]\n\n**誰負責／怎樣做：**獲委任執法人員依法發出通知書時，同時提供可取得的繁簡中文、英文求助及程序資訊。  **作用／限制：**讓遊客理解下一步而非因語言差異失去公平；不得隨意承諾可豁免罰款。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| written notice | 書面通知 |\n| understand the rule | 理解規則 |\n| language help | 語言協助 |\n| next step | 下一步 |\n| legal process | 法律程序 |\n\n#### 043. 將預防勸導與違規後執法清楚分開 [教育][執法][處罰]\n\n**誰負責／怎樣做：**康文署在入口先做公眾教育；對已發現的非法餵飼，獲授權人員按自2024年9月起的現行安排依法處理。  **作用／限制：**避免錯教「首次只會警告」；亦保留在事前友善提醒的空間。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| prevent problems | 預防問題 |\n| give a reminder | 作出提醒 |\n| break the rule | 違反規則 |\n| official action | 官方行動 |\n| different stages | 不同階段 |\n\n#### 044. 投訴先按「正在發生」或「事後影片」分流 [案件分流][公共服務]\n\n**誰負責／怎樣做：**1823把即時目擊、事後片段及清潔投訴分開轉介，康文署與漁護署按風險決定跟進優先次序。  **作用／限制：**減少多部門收到同一堆資料；影片仍要核對時地與真偽。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| live report | 即時報告 |\n| old video | 過往影片 |\n| sort cases | 分類個案 |\n| urgent case | 緊急個案 |\n| follow-up action | 跟進行動 |\n\n#### 045. 遇現場威脅或暴力才按需要請警方支援 [執法][人員安全]\n\n**誰負責／怎樣做：**康文署場地職員如面對恐嚇或衝突，應離開危險位置並通知警方；平常禁餵問題先走合適部門程序。  **作用／限制：**保護前線人員並避免把簡單告示工作警務化；警方仍依個案與權力處理。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| staff safety | 員工安全 |\n| call the police | 聯絡警方 |\n| serious threat | 嚴重威脅 |\n| stay safe | 保持安全 |\n| avoid fighting | 避免打鬥 |\n\n#### 046. 依行為而非口音或旅行團外觀決定巡查 [平等][程序公平]\n\n**誰負責／怎樣做：**各部門以客觀行為、時間及地點作依據，不對特定國籍、語言或年齡群體預設違規。  **作用／限制：**提高執法可信度；也避免忽略本地居民的非法餵飼。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| same rules for all | 人人適用同一規則 |\n| fair treatment | 公平對待 |\n| no unfair bias | 沒有不公平偏見 |\n| watch actions | 觀察行為 |\n| local and foreign visitors | 本地及外地遊客 |\n\n#### 047. 為被錯誤識別的人提供簡明查詢與覆核指引 [程序公平][資訊公開]\n\n**誰負責／怎樣做：**相關執法部門清楚告知法定通知書上的查詢、爭議處理和適用程序，而非由場地員工自行撤銷處分。  **作用／限制：**減少誤會及不合理投訴成本；必須按法律既有程序作決定。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| ask a question | 提出查詢 |\n| check a decision | 覆核決定 |\n| wrong report | 錯誤報告 |\n| supporting facts | 相關事實 |\n| right process | 正確程序 |\n\n#### 048. 不以罰款數量作前線員工的唯一績效 [評估][誘因]\n\n**誰負責／怎樣做：**漁護署、康文署同時衡量違規觀察率、清潔負擔、遊客理解及投訴處理，不設定必須開單的數量目標。  **作用／限制：**避免為求數字而過度執法；又可監察是否完全沒有跟進。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| performance measure | 表現指標 |\n| fair target | 合理目標 |\n| number of cases | 個案數量 |\n| better results | 更佳結果 |\n| avoid pressure | 避免壓力 |\n\n#### 049. 定期比較假日和非假日巡查效果 [評估][資源配置]\n\n**誰負責／怎樣做：**漁護署與康文署在相近時段記錄每百名遊客的疑似餵飼情況，分辨人流增加與行為增加。  **作用／限制：**防止只看總投訴數便錯分配人手；抽樣方法與誤差要公開。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| weekend pattern | 周末模式 |\n| weekday visit | 平日到訪 |\n| fair comparison | 公平比較 |\n| visitor numbers | 遊客人數 |\n| check results | 檢查結果 |\n\n### E｜野鴿福利、捕捉行為及專業救援\n\n\n#### 050. 為餵飼、抓鳥與可能造成痛苦的行為建立不同處理路徑 [動物保護][程序公平]\n\n**誰負責／怎樣做：**漁護署與警方分別核實相關行為在第170章或第169章下是否符合法律要件，康文署保存現場基本資料。  **作用／限制：**避免錯把禁餵罰款直接套到所有捉鳥行為；調查前不宣布有人已犯虐待罪。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| different actions | 不同行為 |\n| animal harm | 動物受害 |\n| legal check | 法律核實 |\n| clear evidence | 清楚證據 |\n| separate cases | 分開處理個案 |\n\n#### 051. 設立發現疑似受傷野鳥的簡短轉介流程 [動物保護][公共服務]\n\n**誰負責／怎樣做：**康文署職員遠距記錄雀鳥是否無法站立、持續流血或飛行困難，按漁護署指引聯絡合適救援渠道。  **作用／限制：**減少圍觀者反覆抓起檢查；前線不應自行診斷或治療。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| injured bird | 受傷雀鳥 |\n| keep a distance | 保持距離 |\n| call for help | 致電求助 |\n| trained rescue | 受訓救援 |\n| do not handle | 不要自行觸碰 |\n\n#### 052. 由合資格動物救援者而非遊客處理受傷雀鳥 [動物保護][合作]\n\n**誰負責／怎樣做：**漁護署與愛護動物協會及其他合資格救援團體協調適用轉介資料，確保救援者按個案安全處理。  **作用／限制：**降低二次傷害與接觸風險；民間團體資源有限，不應當作免費常駐政府人手。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| qualified help | 合資格協助 |\n| rescue service | 救援服務 |\n| animal first aid | 動物急救 |\n| safe handling | 安全處理 |\n| limited support | 有限支援 |\n\n#### 053. 不讓普通場地職員為趕走鴿群而追捕牠們 [員工培訓][動物保護]\n\n**誰負責／怎樣做：**康文署寫明職員以清理食物來源及提醒遊客為主；涉及捉鳥、移走受傷動物時交專業人員。  **作用／限制：**避免由錯誤處理衍生新傷害；也維持工作安全。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| chase birds | 追逐雀鳥 |\n| remove food | 清走食物 |\n| staff instructions | 員工指示 |\n| avoid injuries | 避免受傷 |\n| expert support | 專業支援 |\n\n#### 054. 對捉鳥合照行為提供替代拍照方式 [教育][動物保護]\n\n**誰負責／怎樣做：**康文署、導遊及商戶引導遊客拍攝自然飛翔的鴿子或沙灘景色，而不是把鳥抓起供擺姿勢。  **作用／限制：**保留拍照樂趣並減少驚嚇；不鼓勵靠餵食令鳥隻集中。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| natural photo | 自然照片 |\n| birds in flight | 飛翔雀鳥 |\n| without touching | 不需觸碰 |\n| safe memory | 安全回憶 |\n| enjoy nature | 享受大自然 |\n\n#### 055. 為動物福利志願者訂明「只教育、不自行執法」 [合作][程序公平]\n\n**誰負責／怎樣做：**自然團體義工可示範遠距觀鳥與轉介受傷雀鳥，不可強迫查身分、扣留遊客或沒收食物。  **作用／限制：**善用公民力量又不擴張權力；須訓練面對衝突時退後求助。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| volunteer role | 義工角色 |\n| give advice | 提供建議 |\n| legal limits | 法律界線 |\n| ask staff for help | 向職員求助 |\n| respect others | 尊重他人 |\n\n#### 056. 拒絕把毒餌或傷害性驅鳥方法當作便宜捷徑 [動物保護][環境管理]\n\n**誰負責／怎樣做：**康文署與漁護署先研究減少食物殘渣、自然覓食和人群接觸，任何特殊控制措施都需專業與法律評估。  **作用／限制：**保護其他鳥類、寵物和孩童；不能因人手不足便採取不人道方法。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| poison bait | 毒餌 |\n| safe methods | 安全方法 |\n| other animals | 其他動物 |\n| avoid harm | 避免傷害 |\n| long-term plan | 長遠計劃 |\n\n#### 057. 以專業觀察而不是社交影片推斷雀鳥傷勢 [評估][動物保護]\n\n**誰負責／怎樣做：**漁護署可在必要時請合資格人員評估行為對雀鳥的影響，並只對已取得的資料作結論。  **作用／限制：**羽毛掉落值得關注，但不等於已證實骨折或患病。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| check for injury | 檢查傷勢 |\n| expert opinion | 專業意見 |\n| video evidence | 影片證據 |\n| unknown condition | 未知情況 |\n| careful judgment | 審慎判斷 |\n\n#### 058. 將不接觸動物的規則延伸至其他景點 [教育][跨地區合作]\n\n**誰負責／怎樣做：**漁護署及旅發局把「不餵、不捉、不追逐」原則用於其他野鳥或野生動物出沒的旅遊點，並按物種調整資訊。  **作用／限制：**建立一致旅遊禮儀；不能把所有動物的法例或風險當作完全相同。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| other attractions | 其他景點 |\n| respect wildlife | 尊重野生動物 |\n| different species | 不同物種 |\n| travel habits | 旅遊習慣 |\n| local rules | 本地規則 |\n\n#### 059. 先確認雀鳥身分及法定分類才討論捕捉罪名 [程序公平][動物保護]\n\n**誰負責／怎樣做：**漁護署依法判斷個案涉及的雀鳥是否落入相關條文保護範圍，警方在有足夠證據時協助調查。  **作用／限制：**禁餵野鴿不自動等於每一種抓鴿方式構成同一罪名；法律用詞須精確。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| bird type | 雀鳥種類 |\n| legal status | 法律地位 |\n| check the law | 核對法律 |\n| case details | 個案細節 |\n| avoid assumptions | 避免假設 |\n\n#### 060. 考慮在公眾教育中加入野鳥遇困時的求救方法 [動物保護][教育]\n\n**誰負責／怎樣做：**漁護署、康文署、動物福利團體在告示提示遊客發現生病、受傷或死亡雀鳥時保持距離及使用官方求助途徑。  **作用／限制：**避免熱心遊客自行帶走野鳥；不同情況應按專業指示處理。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| sick bird | 患病雀鳥 |\n| dead bird | 死亡雀鳥 |\n| keep away | 遠離 |\n| report the problem | 報告問題 |\n| proper help | 適當協助 |\n\n### F｜環境衞生、食物殘渣和公共健康\n\n\n#### 061. 把高峰後清理食物殘渣納入固定工作次序 [衞生][時間管理]\n\n**誰負責／怎樣做：**康文署安排現有清潔承辦商在旅遊巴集中離開後先處理有食物殘渣的區域，再進行一般沙灘清潔。  **作用／限制：**減少再吸引鴿群；高峰後清潔不能替代即場制止非法餵飼。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| food scraps | 食物殘渣 |\n| clean-up time | 清理時間 |\n| after the crowd | 人群離開後 |\n| remove leftovers | 清走剩食 |\n| clean beach | 清潔沙灘 |\n\n#### 062. 在小食店附近使用有蓋垃圾桶 [衞生][設施改善]\n\n**誰負責／怎樣做：**康文署與場地小食店研究在允許的地方放有蓋而易使用的垃圾桶，避免野鴿直接啄到剩食。  **作用／限制：**減少餵飼以外的食物來源；垃圾桶位置不可阻路或吸引其他害蟲。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| covered bin | 有蓋垃圾桶 |\n| food waste | 食物廢物 |\n| near the shop | 店舖附近 |\n| keep pests away | 避免引來蟲鼠 |\n| easy to use | 容易使用 |\n\n#### 063. 小食店在售賣外賣時提醒顧客保管食物 [商戶合作][衞生]\n\n**誰負責／怎樣做：**場地餐飲營辦者可在收據或取餐處貼提醒，請顧客不要把零食撒到地上或故意餵鳥。  **作用／限制：**從食物來源減少聚集；不會要求食肆職員充當巡邏員。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| takeaway food | 外賣食物 |\n| food counter | 取餐處 |\n| shop reminder | 商戶提示 |\n| keep food covered | 把食物蓋好 |\n| avoid litter | 避免亂丟垃圾 |\n\n#### 064. 把鳥糞重點清潔和一般垃圾分開安排 [衞生][人員保護]\n\n**誰負責／怎樣做：**康文署要求承辦商使用合適清潔方法及防護裝備處理鳥糞較多的路段，避免不當掃起塵埃。  **作用／限制：**既保護遊客也保護清潔工；不靠一般遊客自行清理污染物。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| bird droppings | 鳥糞 |\n| cleaning workers | 清潔工人 |\n| protective clothing | 防護衣物 |\n| safe cleaning | 安全清潔 |\n| avoid dust | 避免塵埃 |\n\n#### 065. 檢查洗手設施有沒有肥皂及清水 [衞生][公共服務]\n\n**誰負責／怎樣做：**康文署在泳灘公共洗手間加強日常檢查，將肥皂、供水及水龍頭故障列為即時報修項目。  **作用／限制：**讓意外接觸鳥隻或環境的人能立即清潔；手部衞生不能取代避免觸碰。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| soap and water | 肥皂與清水 |\n| wash your hands | 洗手 |\n| working tap | 正常水龍頭 |\n| public toilet | 公廁 |\n| check supplies | 檢查物資 |\n\n#### 066. 在雀鳥聚集點附近設清晰洗手方向指示 [資訊提醒][衞生]\n\n**誰負責／怎樣做：**康文署在合理位置加簡單路牌，指向現有洗手間，而不是另建大量洗手站。  **作用／限制：**使用既有設施降低成本；路牌須避免鼓勵遊客靠近雀鳥。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| washing area | 洗手位置 |\n| direction sign | 方向指示 |\n| nearby toilet | 附近洗手間 |\n| clean hands | 清潔雙手 |\n| low-cost step | 低成本措施 |\n\n#### 067. 避免將鳥糞污染與禽流感確診混為一談 [健康教育][資訊公開]\n\n**誰負責／怎樣做：**衞生署衞生防護中心提供簡短科學資訊，由康文署與旅遊業轉載「避免接觸、洗手、按需要求醫」等建議。  **作用／限制：**降低不必要恐慌；不可說新聞個案已出現禽流感。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| health risk | 健康風險 |\n| confirmed illness | 已確診疾病 |\n| health advice | 健康建議 |\n| stay informed | 掌握資訊 |\n| avoid panic | 避免恐慌 |\n\n#### 068. 按風險安排鳥類疾病監察而非每宗餵飼都抽驗 [公共衞生][資源分配]\n\n**誰負責／怎樣做：**漁護署依其動物健康監察職能評估何時需要現場檢查或採樣，並按專業程序通知相關部門。  **作用／限制：**節省檢測與人力；無檢測結果不代表風險為零或已發生感染。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| health testing | 健康檢測 |\n| sample collection | 樣本收集 |\n| expert decision | 專業決定 |\n| test results | 檢測結果 |\n| use resources wisely | 善用資源 |\n\n#### 069. 清潔員收到疑似受傷或死亡鳥隻資訊時先轉介 [員工培訓][衞生]\n\n**誰負責／怎樣做：**清潔承辦商收到現場報告，應先按康文署及漁護署程序處理，避免自行徒手拾起雀鳥或屍體。  **作用／限制：**保障清潔員健康與動物處理安全；不要把救護任務強加給非合資格員工。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| cleaning team | 清潔團隊 |\n| report safely | 安全通報 |\n| dead animal | 動物屍體 |\n| protect workers | 保護工人 |\n| trained staff | 受訓人員 |\n\n#### 070. 在鄰近街道與泳灘交界設垃圾責任線 [部門合作][衞生]\n\n**誰負責／怎樣做：**康文署、食環署與有關物業管理人先畫清各自清潔範圍，再設快速通知方法處理跨界食物殘渣。  **作用／限制：**防止餵飼食物被風帶出管理範圍後無人跟進；不需要重建整套政府架構。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| street cleaning | 街道清潔 |\n| beach area | 泳灘範圍 |\n| shared boundary | 共同邊界 |\n| quick contact | 快速聯絡 |\n| clear responsibility | 明確責任 |\n\n#### 071. 用固定樣區記錄鳥糞與垃圾變化 [評估][衞生]\n\n**誰負責／怎樣做：**康文署挑選數個具有代表性的地面位置，每周以同一時段記錄污染程度，而不以有多少照片作判斷。  **作用／限制：**可檢驗措施是否有效；須考慮天氣與人流變化。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| regular checks | 定期檢查 |\n| same location | 相同地點 |\n| amount of waste | 廢物數量 |\n| weekly change | 每周變化 |\n| measure progress | 衡量進展 |\n\n#### 072. 把清潔工時和重複污染納入成本分析 [財務安排][評估]\n\n**誰負責／怎樣做：**康文署在不披露員工個資的前提下，比較新增清潔工時與被避免的污染情況，決定是否需要改變垃圾設施。  **作用／限制：**幫助在有限預算中選工具；不應因成本壓力令員工無薪加班。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| cleaning cost | 清潔成本 |\n| working hours | 工作時數 |\n| money saved | 節省金錢 |\n| fair workload | 合理工作量 |\n| better planning | 更佳規劃 |\n\n### G｜景點空間、設施及遊客體驗設計\n\n\n#### 073. 提供不用餵鳥也能拍得好照片的觀景點 [場地設計][旅遊體驗]\n\n**誰負責／怎樣做：**康文署與旅發局選取遠離鴿群的海景位置，標示適合拍照的方向與時段。  **作用／限制：**減少以撒糧召集鴿群作拍照道具的誘因；不阻擋其他正常遊客。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| photo spot | 拍照點 |\n| sea view | 海景 |\n| good background | 好背景 |\n| safe distance | 安全距離 |\n| visitor enjoyment | 遊客樂趣 |\n\n#### 074. 以海灘生態小知識牌替代餵鳥互動 [教育][場地設計]\n\n**誰負責／怎樣做：**康文署、漁護署與鳥類研究團體在主要觀景路線介紹常見海岸雀鳥及正確觀察距離。  **作用／限制：**讓「看見動物」成為學習體驗；物種介紹必須經專業核對。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| coastal birds | 海岸雀鳥 |\n| learning board | 學習資訊板 |\n| local nature | 本地自然 |\n| interesting facts | 有趣知識 |\n| observe birds | 觀察雀鳥 |\n\n#### 075. 移除容易積聚食物碎屑的角落設計 [衞生][場地改善]\n\n**誰負責／怎樣做：**康文署在例行維修時檢查椅下、檯邊和垃圾桶後方是否積食物殘渣，選容易清洗的物料替換。  **作用／限制：**減少無意間吸引鴿群；不需要大規模重建泳灘。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| food crumbs | 食物碎屑 |\n| easy to clean | 容易清潔 |\n| public bench | 公共長椅 |\n| small repair | 小型維修 |\n| keep food away | 清走食物 |\n\n#### 076. 在兒童遊樂區維持清楚的動物觀察界線 [兒童安全][場地設計]\n\n**誰負責／怎樣做：**康文署以矮標示或地面圖案提醒家長讓孩子遠距觀看鳥隻，不把鳥群引入遊樂區。  **作用／限制：**降低兒童追捉與鳥糞接觸風險；不得以高圍欄破壞暢通與沙灘空間。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| play area | 遊樂區 |\n| ground marking | 地面標記 |\n| child-friendly sign | 兒童友善告示 |\n| keep a gap | 保持距離 |\n| open space | 開放空間 |\n\n#### 077. 使用短期活動攤位作替代攝影道具 [旅遊體驗][誘因]\n\n**誰負責／怎樣做：**主辦方可在大型活動日擺放鳥類插畫或海灘造型拍照板，讓旅客與圖案合照而不接觸活鳥。  **作用／限制：**提供可分享的旅遊照片；避免製造一次性大量廢物。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| photo board | 拍照板 |\n| bird picture | 鳥類圖片 |\n| fun activity | 趣味活動 |\n| live animal | 活生生動物 |\n| reusable material | 可重用物料 |\n\n#### 078. 讓路牌不遮擋海景及無障礙通道 [無障礙][旅遊體驗]\n\n**誰負責／怎樣做：**康文署在放置禁餵提示牌前，檢查輪椅通道、盲道、沙灘入口及拍照視野。  **作用／限制：**兼顧公共教育與使用景點權利；不是放越多牌越好。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| wheelchair access | 輪椅通道 |\n| clear path | 暢通路徑 |\n| sea view | 海景 |\n| sign position | 路牌位置 |\n| shared space | 共享空間 |\n\n#### 079. 在鴿群高度集中的時段採柔性人流引導 [人流管理][動物保護]\n\n**誰負責／怎樣做：**康文署可讓職員以指示牌帶遊客使用附近其他觀景路線，避免一群人同時追逐雀鳥。  **作用／限制：**減少人鳥擠在同一角落；不得因一般鳥群出現便無限期封閉大片沙灘。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| crowd movement | 人流移動 |\n| another route | 另一條路線 |\n| guide people | 引導人群 |\n| bird group | 鳥群 |\n| avoid crowding | 避免擁擠 |\n\n#### 080. 評估現有欄杆及建築位置是否形成鳥糞落點 [設施檢討][衞生]\n\n**誰負責／怎樣做：**康文署在定期保養中檢查座位上方的安全與清潔問題；如考慮改善設計，先請漁護署評估是否影響鳥隻。  **作用／限制：**優化遊人使用空間；任何防鳥設施須安全及不傷鳥。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| public seating | 公共座位 |\n| building edge | 建築邊緣 |\n| safe design | 安全設計 |\n| clean area | 潔淨區域 |\n| bird-friendly | 對雀鳥友善的 |\n\n#### 081. 按季節更改觀鳥與清潔資訊位置 [時間管理][評估]\n\n**誰負責／怎樣做：**康文署根據不同月份鳥群活動和遊客路線的觀察，調整臨時路牌與清潔重點。  **作用／限制：**避免同一配置全年不變；不能只靠主觀印象推定季節原因。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| seasonal change | 季節變化 |\n| monthly review | 每月檢討 |\n| visitor route | 遊客路線 |\n| move information | 調整資訊位置 |\n| record changes | 記錄變化 |\n\n#### 082. 設遠觀雀鳥的簡易觀景框而非投餌區 [替代活動][動物保護]\n\n**誰負責／怎樣做：**康文署與自然教育團體試用不需近距接觸的取景框，讓家庭拍鳥群遠景。  **作用／限制：**將觀鳥需求轉成不打擾活動；裝置不可引導遊客走進鳥群中心。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| viewing frame | 取景框 |\n| long-distance photo | 遠距照片 |\n| watch quietly | 安靜觀察 |\n| safe viewpoint | 安全觀景位置 |\n| no feeding | 不餵飼 |\n\n#### 083. 讓不熟悉景點的人容易找到場地服務台 [公共服務][場地設計]\n\n**誰負責／怎樣做：**康文署在泳灘入口及網頁標明查詢位置、洗手間、求助方法，讓遊客遇上鳥群接近時知道找誰。  **作用／限制：**提高安全感與友善度；服務台不能提供臨床診斷或法定豁免。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| help desk | 服務台 |\n| ask for directions | 查詢方向 |\n| public service | 公共服務 |\n| easy to find | 容易找到 |\n| visitor support | 遊客支援 |\n\n### H｜商戶、旅遊業與非金錢／經濟誘因\n\n\n#### 084. 為願意張貼官方禁餵資訊的商戶提供可重用素材 [非金錢誘因][合作]\n\n**誰負責／怎樣做：**漁護署和康文署製作電子版圖卡，供附近餐廳、小食店及酒店自願展示。  **作用／限制：**讓一個訊息在多個地方出現而減少印刷開支；不能強迫未屬相關合約的商戶承擔新法律責任。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| free materials | 免費素材 |\n| shop window | 商店櫥窗 |\n| shared message | 共同訊息 |\n| save printing costs | 節省印刷費 |\n| voluntary help | 自願協助 |\n\n#### 085. 於政府場地小食亭合約中清晰列出防殘食安排 [合約管理][衞生]\n\n**誰負責／怎樣做：**康文署在適用的新合約或續約條件中訂明垃圾桶清理、食物殘渣管理及通報方法。  **作用／限制：**把部分清潔責任落到最容易處理食物的經營者；不得無故追溯更改已訂合約。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| food stall | 食物攤檔 |\n| service contract | 服務合約 |\n| waste control | 廢物管理 |\n| keep records | 保留紀錄 |\n| fair terms | 公平條款 |\n\n#### 086. 鼓勵旅遊業採用「不接觸野生動物」遊程承諾 [自願守則][旅遊協作]\n\n**誰負責／怎樣做：**旅行社與導遊協會可自願加入不餵鳥、不誘拍抱鳥合照的旅遊承諾，旅監局提供正確資訊作參考。  **作用／限制：**建立業界共同做法；自願標誌不可冒稱政府核發安全認證。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| travel promise | 旅遊承諾 |\n| responsible travel | 負責任旅遊 |\n| group rules | 團體守則 |\n| join a scheme | 參加計劃 |\n| honest label | 真實標示 |\n\n#### 087. 將安全觀鳥活動加入酒店與景點套票 [商業誘因][旅遊設計]\n\n**誰負責／怎樣做：**酒店與旅遊營辦商可推出自然導賞或遠距觀鳥活動，替代以餵飼吸引鳥群的玩法。  **作用／限制：**讓遵守禁令仍有產品價值；活動價格要讓一般家庭負擔得起。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| tour package | 旅遊套票 |\n| nature walk | 自然步行 |\n| bird watching | 觀鳥 |\n| family price | 家庭價格 |\n| new experience | 新體驗 |\n\n#### 088. 讓附近店舖以優惠鼓勵自備水和減少垃圾 [經濟誘因][衞生]\n\n**誰負責／怎樣做：**商戶可自願在不影響經營的情況下提供可重用水樽補水等優惠，降低一次性食品包裝留在沙灘的機會。  **作用／限制：**減少垃圾與鴿群食源；優惠應由參與者自願承擔成本。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| refill a bottle | 補充水樽 |\n| reuse a cup | 重用杯子 |\n| small discount | 小額折扣 |\n| less waste | 減少廢物 |\n| shop offer | 商戶優惠 |\n\n#### 089. 贊助商資助小型教育活動但不得干預法例執行 [財務安排][合作]\n\n**誰負責／怎樣做：**地方商戶或贊助者可按透明安排提供海報與導賞材料，由康文署或合適主辦方控制內容。  **作用／限制：**減輕公帑壓力；贊助不能換取特殊放寬、商業獨佔或不公平曝光。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| local sponsor | 本地贊助者 |\n| support education | 支持教育 |\n| public money | 公帑 |\n| fair access | 公平參與 |\n| clear agreement | 清晰協議 |\n\n#### 090. 給清潔承辦商設「污染改善」而非「罰款數量」指標 [合約管理][評估]\n\n**誰負責／怎樣做：**康文署在適用合約內以清潔完成時間、食物殘留和工人安全作評核，避免將違規餵飼責任全推予清潔工。  **作用／限制：**鼓勵真正改善環境；指標須考慮遊客量及意外天氣。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| cleaning quality | 清潔質素 |\n| fair target | 合理指標 |\n| worker safety | 工人安全 |\n| service review | 服務檢討 |\n| good results | 良好成果 |\n\n#### 091. 與景點攝影服務商共同宣傳不抱鳥合照 [商業合作][動物保護]\n\n**誰負責／怎樣做：**商業攝影者如在適用場地依法營運，可向客人提供海景、夕陽及無接觸野鳥取景範例。  **作用／限制：**替代抱鳥擺拍的即時收益動機；不認定現場一定存在持牌商業攝影者。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| photo service | 攝影服務 |\n| sunset photo | 日落照片 |\n| safe picture | 安全照片 |\n| customer choice | 顧客選擇 |\n| new photo idea | 新拍照構思 |\n\n#### 092. 檢討是否有人在景點售賣供餵鳥使用的食物 [巡查][商戶合作]\n\n**誰負責／怎樣做：**康文署與食環署按權責確認是否有商販宣傳以餵鴿為用途的商品，先核實事實再依法處理適用營商行為。  **作用／限制：**處理可能鼓勵違規的銷售訊息；不能假定新聞有商販供應鳥糧。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| selling food | 出售食物 |\n| shop product | 商店商品 |\n| check the facts | 核實事實 |\n| business rules | 營商規則 |\n| avoid wrong claims | 避免錯誤指稱 |\n\n#### 093. 先小規模測試商戶合作是否真正減少餵飼 [試行][評估]\n\n**誰負責／怎樣做：**康文署與商戶協會在少數門店試行收據提示與食物包裝提醒，再觀察接觸點附近的行為變化。  **作用／限制：**用證據決定是否擴大；不可只憑商戶自評作結論。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| small trial | 小型試驗 |\n| shop partners | 合作店舖 |\n| customer reminder | 顧客提示 |\n| test the idea | 測試構思 |\n| review the change | 檢討變化 |\n\n### I｜市民報告、社區互助與公眾參與\n\n\n#### 094. 在告示清楚寫明1823是違規餵飼通報途徑 [公共服務][資訊提醒]\n\n**誰負責／怎樣做：**康文署使用漁護署確認的聯絡資訊，讓居民及旅客知道可透過1823交代位置和發生時間。  **作用／限制：**把資料送到正確渠道；有即時人身危險須另按情況求救。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| public hotline | 公共熱線 |\n| report a case | 報告個案 |\n| exact location | 確實位置 |\n| time of event | 事件時間 |\n| contact details | 聯絡資料 |\n\n#### 095. 為目擊者提供五項以內的簡單報告欄位 [服務設計][程序公平]\n\n**誰負責／怎樣做：**1823及相關部門若優化表格，只問地點、時間、行為、是否正在發生及可選證據，不要求猜測國籍。  **作用／限制：**提高報告可用性並減少私隱風險；不要求市民冒險跟蹤涉事者。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| short form | 簡短表格 |\n| place and time | 地點和時間 |\n| what happened | 發生甚麼事 |\n| optional photo | 可選相片 |\n| protect privacy | 保障私隱 |\n\n#### 096. 明確呼籲公眾不要與違規者爭吵或追逐 [公眾教育][人身安全]\n\n**誰負責／怎樣做：**警方、康文署及居民團體提醒市民可通知職員或1823，不應為阻止餵鳥而包圍、推撞遊客。  **作用／限制：**避免原本的衞生事件演變成肢體衝突；嚴重威脅按情況報警。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| stay calm | 保持冷靜 |\n| avoid a fight | 避免爭執 |\n| tell the staff | 通知職員 |\n| safe reporting | 安全通報 |\n| public safety | 公共安全 |\n\n#### 097. 不鼓勵網民公開未成年人的清晰樣貌 [私隱][兒童保障]\n\n**誰負責／怎樣做：**教育團體與平台使用者可提醒分享者遮蓋兒童面貌和其他可識別資料，讓有關部門依法調查。  **作用／限制：**防止持續網絡羞辱；保留合法投訴與公共議題討論空間。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| hide a face | 遮蓋面貌 |\n| young person | 未成年人 |\n| online sharing | 網上分享 |\n| private details | 私人資料 |\n| avoid shame | 避免羞辱 |\n\n#### 098. 由居民協助指出真正反覆出現問題的地點 [公眾參與][評估]\n\n**誰負責／怎樣做：**南區居民及商戶透過民政事務處或1823提出反覆出現的時段和位置，供漁護署與康文署交叉核對。  **作用／限制：**利用在地知識改善巡查；投訴多不一定等於違規率高。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| local knowledge | 本地知識 |\n| regular problem | 反覆問題 |\n| resident feedback | 居民意見 |\n| check reports | 核對報告 |\n| better patrols | 更佳巡查 |\n\n#### 099. 成立少量受訓「旅遊友善提醒義工」 [義工合作][教育]\n\n**誰負責／怎樣做：**社區組織與康文署在合理安排下招募義工，在節慶向遊客派官方資訊，不要求盤問或搜查。  **作用／限制：**把執法人手留給有法律權力的工作；義工需要清楚撤退和求助規則。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| trained volunteer | 受訓義工 |\n| give leaflets | 派發單張 |\n| help visitors | 協助遊客 |\n| clear limits | 清楚界線 |\n| ask for backup | 尋求支援 |\n\n#### 100. 定期與動物福利團體審核教育文字 [合作][動物保護]\n\n**誰負責／怎樣做：**漁護署邀請合資格動物福利團體檢查「餵鳥造成甚麼改變」等教材，避免恐嚇或錯誤健康說法。  **作用／限制：**增強資訊準確度；民間團體建議不自動取代政府專業判斷。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| animal experts | 動物專家 |\n| check the message | 檢查訊息 |\n| correct facts | 正確事實 |\n| public lesson | 公眾課程 |\n| shared learning | 共同學習 |\n\n#### 101. 邀請旅客為告示做「看懂測試」 [公眾參與][評估]\n\n**誰負責／怎樣做：**康文署與旅發局在不記名情況下請不同語言遊客用自己的話解釋規則，再修正標示。  **作用／限制：**重點是理解程度而非海報數目；測試不能造成遊客被迫停留。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| visitor test | 遊客測試 |\n| understand signs | 理解標示 |\n| anonymous answer | 匿名回答 |\n| change the words | 修改字句 |\n| easy reading | 容易閱讀 |\n\n#### 102. 讓附近商戶分享「食物殘渣最多何時出現」 [商戶合作][衞生]\n\n**誰負責／怎樣做：**康文署與食肆、清潔員建立簡單通報，例如午餐後或旅遊巴停靠時段，避免重複人手巡場。  **作用／限制：**從營運時段預判衞生風險；不把商戶分享誤當成法定違規證據。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| meal time | 用餐時間 |\n| busy shop | 繁忙商店 |\n| food waste | 食物廢物 |\n| shop report | 商戶報告 |\n| plan cleaning | 安排清潔 |\n\n#### 103. 讓鳥類觀察者提供非侵入式資料 [公民科學][生態保護]\n\n**誰負責／怎樣做：**鳥類愛好者可協助記錄特定區域的鴿群大小和活動時間，不追逐、捕捉或誘餌吸引鳥群。  **作用／限制：**提供觀察角度而非取代正式調查；志願數據需交叉核實。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| bird count | 雀鳥點算 |\n| watch quietly | 安靜觀察 |\n| record time | 記錄時間 |\n| share findings | 分享觀察結果 |\n| no bait | 不使用誘餌 |\n\n#### 104. 在高風險節假日加強與居民的事前溝通 [社區協作][時間管理]\n\n**誰負責／怎樣做：**南區民政事務處協調康文署與居民團體，在長假前公布巡查重點及1823渠道，收集場地管理意見。  **作用／限制：**減少居民不知向誰反映；討論不應變成排斥遊客。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| holiday notice | 節假日通知 |\n| local meeting | 地區會議 |\n| resident concerns | 居民關注 |\n| shared plan | 共同計劃 |\n| welcome visitors | 歡迎遊客 |\n\n### J｜科技、數據、監控邊界與私隱\n\n\n#### 105. 只在持續黑點研究限量使用監察設備 [科技][試行]\n\n**誰負責／怎樣做：**漁護署可參考2025至2026年在其他地點的AI監察試點，先核實淺水灣是否有足夠反覆違規及必要性。  **作用／限制：**技術應節省巡查時間；不能因單段新聞片就宣稱需全灘密集監控。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| security camera | 保安攝錄機 |\n| small trial | 小型試驗 |\n| repeated cases | 重複個案 |\n| real need | 實際需要 |\n| check the plan | 檢查方案 |\n\n#### 106. 把鳥群數量分析與個人身分辨認分開 [私隱][科技]\n\n**誰負責／怎樣做：**漁護署若採技術輔助，優先研究鳥群聚集或可疑活動的整體訊號，不主動建立遊客人臉名冊。  **作用／限制：**達到資源規劃目的而減少私隱侵入；任何個人資料處理須符合法律。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| bird numbers | 鳥隻數量 |\n| people's faces | 人們面孔 |\n| private data | 私人資料 |\n| collect less data | 收集較少資料 |\n| public safety | 公共安全 |\n\n#### 107. 攝錄區域放明顯告示並公開負責部門 [資訊公開][私隱]\n\n**誰負責／怎樣做：**如經必要性評估確需錄影，管理者應張貼用途、負責單位及查詢方法，遵守私隱專員相關指引。  **作用／限制：**讓市民知情；不能把「公開地方」等同可無限制攝錄。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| camera notice | 攝錄告示 |\n| who is in charge | 誰負責 |\n| clear purpose | 清楚用途 |\n| personal privacy | 個人私隱 |\n| public place | 公共地方 |\n\n#### 108. 設定保存及刪除影片的合理期限 [私隱][程序公平]\n\n**誰負責／怎樣做：**負責部門按適用法律及實際調查需要制定影片保存、限制存取及刪除安排，並留下調閱紀錄。  **作用／限制：**降低資料外洩風險；如涉正式調查須依法保留必要證據。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| keep records | 保存紀錄 |\n| delete old files | 刪除舊檔 |\n| safe storage | 安全儲存 |\n| access control | 存取限制 |\n| legal reason | 法律理由 |\n\n#### 109. 技術只提示異常，最終違規判斷保留人工核實 [科技][程序公平]\n\n**誰負責／怎樣做：**漁護署利用系統協助定位可能餵飼事件，獲委任執法人員再依可核實證據作決定。  **作用／限制：**避免把投食、正常進食或鳥群靠近誤判為同一回事；技術不可自動開罰單。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| computer alert | 電腦警示 |\n| human review | 人工覆核 |\n| possible error | 可能錯誤 |\n| real evidence | 真實證據 |\n| final decision | 最終決定 |\n\n#### 110. 測試監察系統對不同光線與人潮的錯誤率 [評估][科技]\n\n**誰負責／怎樣做：**漁護署只在批准的試驗中比較陽光、雨天與多人場景的誤報，必要時調整而非直接擴大。  **作用／限制：**避免浪費執法人手追逐假警報；試驗須披露限制。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| false alarm | 錯誤警報 |\n| bright light | 強光 |\n| rainy day | 雨天 |\n| crowded area | 人多地區 |\n| improve the system | 改善系統 |\n\n#### 111. 為市民提供無須拍人臉的通報選項 [私隱][公共服務]\n\n**誰負責／怎樣做：**1823或相關部門可接受以文字說明地點和時間，必要照片只拍行為及場地，不鼓勵對準兒童面孔。  **作用／限制：**減少網絡公開與個資風險；有實際刑事調查時由合法程序處理證據。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| text report | 文字報告 |\n| no face photo | 不拍面孔 |\n| child privacy | 兒童私隱 |\n| necessary proof | 必要證明 |\n| safe sharing | 安全分享 |\n\n#### 112. 使用不含個人身分的熱點地圖安排巡查 [數據分析][巡查]\n\n**誰負責／怎樣做：**漁護署與康文署整合時間、位置及類別等統計，定期更新巡查次序，不建立遊客追蹤檔案。  **作用／限制：**提高資源分配效率；若資料量少須防誤導。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| simple map | 簡單地圖 |\n| busy times | 繁忙時段 |\n| problem spots | 問題位置 |\n| anonymous figures | 匿名數字 |\n| plan patrols | 規劃巡查 |\n\n#### 113. 讓遊客可在不開手機程式下取得同樣資訊 [無障礙][資訊提醒]\n\n**誰負責／怎樣做：**康文署保留實體告示和紙本資訊，數碼地圖只是補充，並非唯一遵守規則的方法。  **作用／限制：**避免對沒有智能電話的老人或旅客不公平；也減少應用程式資料收集。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| paper guide | 紙本指引 |\n| no phone needed | 不需手機 |\n| equal service | 平等服務 |\n| easy access | 容易使用 |\n| digital option | 數碼選項 |\n\n#### 114. 以匿名觀察衡量標示是否真的改變行為 [評估][試行]\n\n**誰負責／怎樣做：**康文署在相近時段比較改牌前後的餵飼次數及旅客理解，而非採全面個人追蹤。  **作用／限制：**取得政策效果資訊而減少侵犯私隱；要同時計算人流與天氣。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| before and after | 前後比較 |\n| visitor count | 遊客數目 |\n| track changes | 追蹤變化 |\n| no names needed | 不需姓名 |\n| careful study | 審慎研究 |\n\n#### 115. 為監察技術建立停止使用的門檻 [私隱][問責]\n\n**誰負責／怎樣做：**漁護署與相關資料管理者在試驗開始前訂明如誤報高、成效低或私隱風險過大便停止試行。  **作用／限制：**避免技術一裝就永久擴張；停用準則與責任人應可查閱。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| stop the trial | 停止試驗 |\n| review period | 檢討期 |\n| privacy risk | 私隱風險 |\n| poor results | 成效不佳 |\n| clear limit | 清楚限制 |\n\n### K｜具名政府分工、跨部門合作與資源配置\n\n\n#### 116. 由康文署擔任淺水灣泳灘的現場行動負責方 [部門分工][場地管理]\n\n**誰負責／怎樣做：**康文署南區場地管理人員維持一張簡易工作表，記錄標示、清潔、巡場與轉介情況。  **作用／限制：**使遊客及其他部門知道向誰查詢；不將所有法律調查責任轉給一般泳灘員工。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| site manager | 場地管理者 |\n| daily tasks | 每日工作 |\n| clear contact | 清楚聯絡點 |\n| beach services | 泳灘服務 |\n| work record | 工作紀錄 |\n\n#### 117. 由漁護署主導禁餵規則、執法人員訓練與專業支援 [部門分工][執法]\n\n**誰負責／怎樣做：**漁護署為跨部門人員提供最新法例說明及標準記錄方式，並對有爭議雀鳥案件提供適用專業協助。  **作用／限制：**減少不同部門用詞及做法不一致；不代表每宗輕微投訴都要派漁護署專員。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| legal guidance | 法律指引 |\n| staff training | 員工培訓 |\n| common rules | 共同規則 |\n| expert advice | 專業建議 |\n| fair action | 公平處理 |\n\n#### 118. 由食環署處理所管轄公眾地方的食物與衞生問題 [部門分工][衞生]\n\n**誰負責／怎樣做：**食環署按適用職責處理泳灘外附近街道的垃圾、相關環境衞生及商販問題，與康文署互通發現。  **作用／限制：**防止管理邊界造成清潔漏洞；不得把泳灘內一切設施歸食環署負責。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| street hygiene | 街道衞生 |\n| food waste | 食物廢物 |\n| nearby area | 毗鄰地區 |\n| share reports | 分享報告 |\n| clear boundary | 清楚界線 |\n\n#### 119. 由警方處理有暴力、公共秩序或疑似虐待動物的升級個案 [部門分工][公共安全]\n\n**誰負責／怎樣做：**康文署及漁護署在遇威脅、阻撓或合理懷疑虐待動物時，按正式途徑聯絡警方依法調查。  **作用／限制：**把警力留給需警務權力的個案；一般鳥群聚集不等於刑事緊急事故。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| police support | 警方支援 |\n| serious conflict | 嚴重衝突 |\n| possible cruelty | 疑似殘酷行為 |\n| legal investigation | 法律調查 |\n| use the right service | 使用正確服務 |\n\n#### 120. 由環境及生態局定期檢視跨部門成果與整體資源 [政策統籌][評估]\n\n**誰負責／怎樣做：**環境及生態局可透過既有工作組了解漁護署、康文署、食環署和房屋署的禁餵經驗，研究是否調整全港優次。  **作用／限制：**處理跨區政策協調，而非由局方直接代替前線執法。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| overall plan | 整體計劃 |\n| shared goals | 共同目標 |\n| department review | 部門檢討 |\n| public spending | 公共開支 |\n| long-term results | 長遠成果 |\n\n#### 121. 由文化體育及旅遊局／旅遊事務署協調旅遊業教育策略 [旅遊統籌][合作]\n\n**誰負責／怎樣做：**旅遊事務署與旅發局、旅監局及相關業界商討如何在旅遊路線和導遊資訊中加入不餵鳥守則。  **作用／限制：**把旅遊安全與遊客體驗連起來；不新增未經授權的罰款權。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| tourism policy | 旅遊政策 |\n| travel partners | 旅遊合作夥伴 |\n| visitor advice | 遊客指引 |\n| protect the image | 維護形象 |\n| joint planning | 共同規劃 |\n\n#### 122. 由旅監局按持牌業界制度提供可行培訓指引 [行業規管][培訓]\n\n**誰負責／怎樣做：**旅監局可向持牌旅行社及導遊發出經漁護署核實的景點守則資料，並研究是否應納入業界專業教育。  **作用／限制：**向真正陪同團客的人傳遞知識；若新增強制責任須另審法律依據及諮詢。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| licensed guide | 持牌導遊 |\n| industry rules | 行業規則 |\n| guide training | 導遊培訓 |\n| travel safety | 旅遊安全 |\n| new duty | 新增責任 |\n\n#### 123. 由旅發局改善面向散客與境外訪客的訊息 [旅遊宣傳][教育]\n\n**誰負責／怎樣做：**旅發局在官方旅遊介紹及合適社交宣傳中附上簡明禁餵和自然拍照建議，連接漁護署官方網站。  **作用／限制：**照顧沒有導遊的自由行旅客；旅發局不處理罰單。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| independent travellers | 自由行旅客 |\n| visitor guide | 旅客指南 |\n| online information | 網上資訊 |\n| clear link | 清晰連結 |\n| safe visit | 安全旅遊 |\n\n#### 124. 讓房屋署在跨部門小組分享屋邨黑點管理經驗 [跨部門合作][資源分配]\n\n**誰負責／怎樣做：**房屋署提供其管理場景內的有效告示、居民溝通和巡查經驗，供康文署依泳灘情況參考。  **作用／限制：**共享方法而不混淆權力；不同場地未必可直接複製。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| housing team | 房屋管理團隊 |\n| share lessons | 分享經驗 |\n| local methods | 本地方法 |\n| change for the beach | 因應泳灘調整 |\n| learn together | 共同學習 |\n\n#### 125. 由衞生防護中心核對所有健康風險宣傳 [科學溝通][公共衞生]\n\n**誰負責／怎樣做：**衞生署衞生防護中心提供接觸雀鳥、洗手及求醫的科學用語，讓其他部門引用。  **作用／限制：**避免因網上恐慌而錯誤宣稱疫病已發生；醫療判斷仍依實際情況。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| health message | 健康訊息 |\n| science-based advice | 以科學為本的建議 |\n| wash with soap | 用肥皂清洗 |\n| medical help | 醫療協助 |\n| avoid false claims | 避免錯誤說法 |\n\n#### 126. 由南區民政事務處聯繫居民與旅遊商戶處理地區摩擦 [地區合作][公眾參與]\n\n**誰負責／怎樣做：**南區民政事務處按其協調角色召集康文署、居民、酒店及商戶代表，收集噪音、人流及清潔方面的意見。  **作用／限制：**減少只看遊客或居民一方的資訊；不以會議取代實際巡查與法定執法。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| local meeting | 地區會議 |\n| resident views | 居民意見 |\n| shop owners | 商戶 |\n| visitor needs | 遊客需要 |\n| find common ground | 尋找共同點 |\n\n#### 127. 由1823和相關部門建立清晰的跨單位轉介回覆 [行政協作][公共服務]\n\n**誰負責／怎樣做：**1823把疑似非法餵飼送合適執法部門、把泳灘清潔送場地管理者、把疑似虐待動物送適當機關；回覆可用通用狀態說明。  **作用／限制：**減少重複投訴及迷失在部門間；不得向無關第三方公開調查資料。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| pass on a case | 轉介個案 |\n| correct office | 正確部門 |\n| reply to the public | 回覆公眾 |\n| shared process | 共同流程 |\n| protect case details | 保護個案資料 |\n\n### L｜成效評估、長期改進及生態治理\n\n\n#### 128. 先做六星期示範試行再決定是否長期化 [試行][評估]\n\n**誰負責／怎樣做：**康文署和漁護署在淺水灣選定假日安排、現場告示及精準巡查，六星期後與先前資料比較。  **作用／限制：**降低大規模改革成本；六星期為教學假設，非已公布官方計劃。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| six-week trial | 六星期試行 |\n| test period | 測試期 |\n| start small | 從小規模開始 |\n| review results | 檢討結果 |\n| decide later | 稍後決定 |\n\n#### 129. 選取一個相近區域作觀察比較 [評估][研究]\n\n**誰負責／怎樣做：**康文署於人流與環境較相近的泳灘或沙灘區域記錄基本情況，與試點變化比較。  **作用／限制：**避免將天氣或假日造成的改變錯當政策成果；必須尊重不同場地條件。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| comparison area | 比較區域 |\n| similar conditions | 相似條件 |\n| fair test | 公平測試 |\n| weather changes | 天氣變化 |\n| check the cause | 核查原因 |\n\n#### 130. 以違規比率而非投訴總數評估成效 [評估][數據]\n\n**誰負責／怎樣做：**漁護署與康文署用相同時間與觀察方法估算每百名遊客的餵飼次數，而不只比較全部舉報數量。  **作用／限制：**避免人流增加自然帶來較多投訴的錯覺；數據仍可能受抽樣限制。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| rate of cases | 個案比率 |\n| visitor numbers | 遊客人數 |\n| total complaints | 投訴總數 |\n| fair measure | 公平衡量 |\n| data limits | 資料限制 |\n\n#### 131. 把雀鳥受傷與受驚報告納入成效評估 [動物保護][評估]\n\n**誰負責／怎樣做：**漁護署與動物福利專家檢視可核實的受傷轉介及人鳥直接接觸情況，不只看有沒有罰款。  **作用／限制：**確保政策真正改善動物福利；沒有通報不代表沒有傷害。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| injury report | 受傷報告 |\n| bird care | 雀鳥照顧 |\n| direct contact | 直接接觸 |\n| animal safety | 動物安全 |\n| hidden problems | 隱藏問題 |\n\n#### 132. 以旅客理解度與整體滿意度一同評估 [旅遊評估][公眾參與]\n\n**誰負責／怎樣做：**旅發局與康文署用不記名簡短問卷問遊客是否懂得禁餵、能否享受景色及尋得洗手間。  **作用／限制：**避免只追求阻止違規而忽視友善旅遊；問卷不能冒充全港民意。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| visitor feedback | 遊客意見 |\n| enjoy the trip | 享受旅程 |\n| understand the rule | 理解規則 |\n| short survey | 簡短問卷 |\n| balanced results | 平衡結果 |\n\n#### 133. 按各部門投入人時比較不同方法的成本 [財務評估][資源分配]\n\n**誰負責／怎樣做：**康文署與漁護署比較標示、短巡查、教育攤位及清潔改善所用工時，避免無限追加同一措施。  **作用／限制：**讓有限資源投向有用機制；不能純以最便宜判斷是否保障動物。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| staff hours | 員工工時 |\n| total cost | 總成本 |\n| value for money | 物有所值 |\n| useful action | 有效行動 |\n| limited budget | 有限預算 |\n\n#### 134. 每季更新標示而不是不斷增添新牌 [資源管理][評估]\n\n**誰負責／怎樣做：**康文署在既有保養安排中檢視遊客是否看得懂、告示是否損壞，先改文字或位置再考慮新增數量。  **作用／限制：**防止資訊過多造成忽略；有需要的法律資訊不能省掉。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| quarterly review | 每季檢討 |\n| too many signs | 過多告示 |\n| repair a notice | 維修告示 |\n| update wording | 更新字句 |\n| avoid waste | 避免浪費 |\n\n#### 135. 訂出試點擴大與停止條件 [問責][試行]\n\n**誰負責／怎樣做：**環境及生態局與執行部門可事先說明哪些指標改善才擴至其他景點，以及何種成本或私隱問題會令試點終止。  **作用／限制：**避免措施只增不減；需向公眾交代改變理由。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| expand a trial | 擴大試點 |\n| stop a project | 停止項目 |\n| clear reasons | 清楚原因 |\n| public report | 公開報告 |\n| responsible decision | 負責任決定 |\n\n#### 136. 把旅遊旺季和季節因素列入人手安排 [時間管理][資源分配]\n\n**誰負責／怎樣做：**康文署、漁護署按長假、天氣及到訪人流調整宣傳和巡查，不依一宗事件固定全年高強度。  **作用／限制：**把資源使用與風險相配；熱門時段資料須定期更新。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| travel season | 旅遊旺季 |\n| busy weekend | 繁忙周末 |\n| staff planning | 人手安排 |\n| weather conditions | 天氣情況 |\n| flexible plan | 彈性計劃 |\n\n#### 137. 公開不包括個人身分的簡短年度成效報告 [資訊公開][問責]\n\n**誰負責／怎樣做：**漁護署可與相關部門整理巡查、舉報、清潔和教育成果，只公布足夠保護私隱的合計資料。  **作用／限制：**增進公眾信任及政策學習；避免公布可識別兒童或個別遊客的細節。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| annual report | 年度報告 |\n| public figures | 公開數字 |\n| privacy protection | 私隱保障 |\n| share results | 分享成果 |\n| public trust | 公眾信任 |\n\n#### 138. 定期檢查環境改善是否只是把鴿群趕往其他地方 [生態評估][跨地區合作]\n\n**誰負責／怎樣做：**漁護署與附近場地管理者比較周邊鳥群活動，避免只把一處聚集轉移到鄰近街道或住宅。  **作用／限制：**防止問題轉移；需要專業觀察而非任意清除野鴿。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| nearby area | 附近地方 |\n| move the problem | 轉移問題 |\n| bird movement | 雀鳥活動 |\n| wider view | 更廣視角 |\n| long-term effect | 長遠影響 |\n\n#### 139. 把安全觀鳥經驗整理成可轉用的景點管理工具包 [知識共享][長遠規劃]\n\n**誰負責／怎樣做：**康文署、漁護署與旅發局把有效告示、導遊文字、巡查表及評估方法整理供其他景點選用。  **作用／限制：**減少每區重新設計成本；新場地仍須檢查各自法例和動物種類。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| ready-made guide | 現成指引 |\n| share good ideas | 分享良好做法 |\n| other beaches | 其他泳灘 |\n| save time | 節省時間 |\n| local needs | 地方需要 |\n\n### M｜最強反對意見、成本及意外後果（政策壓力測試）\n\n\n#### 140. 過重依賴罰款可能忽略真正的理解不足 [反對觀點][教育取捨]\n\n**反對理由／受影響者：**遊客可能根本沒有看見告示，若政府只增加罰款而不改善入場提示，會減少守規則的機會。  **政策取捨：**保留依法處理違規的必要性，同時把事前可理解的提醒列為政策成效之一。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| lack of knowledge | 缺乏知識 |\n| strong penalty | 嚴厲罰款 |\n| clear guidance | 清晰指引 |\n| fair warning sign | 公平警示 |\n| understand the law | 理解法律 |\n\n#### 141. 5,000元定額罰款對不同收入者的負擔不同 [反對觀點][公平]\n\n**反對理由／受影響者：**低收入家庭可能較難承受同額金錢處罰，令人質疑處罰的比例與公平。  **政策取捨：**金額已屬現行法例；政策辯論可討論長遠檢討，但不能由場地人員私自減額。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| same fine | 相同罰款 |\n| low income | 低收入 |\n| financial burden | 財政負擔 |\n| fair result | 公平結果 |\n| legal rule | 法律規定 |\n\n#### 142. 執法人員不可能目睹每一次短暫撒糧 [反對觀點][執行困難]\n\n**反對理由／受影響者：**遊客餵鴿可能只需數秒，全天巡邏仍會錯過，更多人手也未必與成效成比例。  **政策取捨：**在客觀證據足夠的黑點集中巡查，並依靠事前預防降低違規。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| quick action | 短暫動作 |\n| miss an event | 錯過事件 |\n| limited patrol | 有限巡查 |\n| staff shortage | 人手不足 |\n| early prevention | 及早預防 |\n\n#### 143. 鳥隻靠近人群不等於有人違法餵飼 [反對觀點][誤判]\n\n**反對理由／受影響者：**鳥群可能因其他食物來源、休息地或自然行為靠近遊客，僅憑聚集推斷違規會冤枉他人。  **政策取捨：**以具體動作核實才執法；鳥群數量可用來選巡查位置但不是定罪證據。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| bird gathering | 雀鳥聚集 |\n| wrong guess | 錯誤猜測 |\n| real action | 實際行為 |\n| check carefully | 審慎核實 |\n| fair evidence | 公平證據 |\n\n#### 144. 以網民猜測的國籍訂政策會造成歧視 [反對觀點][平等]\n\n**反對理由／受影響者：**從影片不能證實遊客來源，若對某類口音或外觀者加強盤查，可能損害平等及香港旅遊形象。  **政策取捨：**以可見違規與客觀風險指標決定措施，讓本地與海外遊客適用同一規則。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| nationality | 國籍 |\n| unfair bias | 不公平偏見 |\n| same rules | 相同規則 |\n| visitor respect | 尊重遊客 |\n| judge actions | 按行為判斷 |\n\n#### 145. 把兒童面貌廣泛轉發會造成長期網絡傷害 [反對觀點][兒童私隱]\n\n**反對理由／受影響者：**即使成年人不滿意孩子捉鳥，公開清晰面孔及姓名亦可能令未成年人長期被搜尋和辱罵。  **政策取捨：**可討論動物福利並向部門舉報，但傳播內容應減少可識別資料。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| online harm | 網絡傷害 |\n| child privacy | 兒童私隱 |\n| share carefully | 審慎分享 |\n| hide identity | 遮蓋身分 |\n| respect a child | 尊重兒童 |\n\n#### 146. 把鳥糞風險直接說成禽流感爆發會製造恐慌 [反對觀點][科學準確]\n\n**反對理由／受影響者：**疾病風險值得預防，但新聞未證實涉事鴿子帶有禽流感，也未有當事人感染證據。  **政策取捨：**採用衞生防護中心建議而不誇大病情。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| health concern | 健康關注 |\n| disease risk | 疾病風險 |\n| no confirmed case | 沒有確診個案 |\n| accurate facts | 準確事實 |\n| avoid fear | 避免恐慌 |\n\n#### 147. 過多禁令告示可能破壞自然景觀 [反對觀點][旅遊體驗]\n\n**反對理由／受影響者：**若海灘每隔數步便是一塊警告牌，遊客可能覺得景點像受嚴格管制的地方。  **政策取捨：**集中放在決策點並測試理解度，保留自然景觀。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| too many notices | 過多告示 |\n| natural view | 自然景色 |\n| visitor feeling | 遊客感受 |\n| keep signs simple | 保持標示簡潔 |\n| right location | 合適位置 |\n\n#### 148. 全天閉路電視可能侵犯無違規遊客的私隱 [反對觀點][私隱]\n\n**反對理由／受影響者：**泳灘涉及家庭活動和個人休閒，密集攝錄可能取得大量不相關影像。  **政策取捨：**只有在必要且相稱時才研究限量監測，並依法保護個資。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| all-day cameras | 全天攝錄 |\n| personal privacy | 個人私隱 |\n| unrelated people | 無關人士 |\n| recording risk | 錄影風險 |\n| limited use | 有限使用 |\n\n#### 149. 人工智能識別有可能錯把進食當作餵鳥 [反對觀點][科技誤判]\n\n**反對理由／受影響者：**系統可能見到遊客手持食物和鳥群靠近，卻不清楚是否真的向鳥撒糧。  **政策取捨：**技術只提示人工檢查，不能自動裁定違法。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| computer mistake | 電腦錯誤 |\n| hold food | 手持食物 |\n| false alarm | 錯誤警報 |\n| human check | 人工檢查 |\n| fair decision | 公平判斷 |\n\n#### 150. 影像長期保存會增加外洩與濫用風險 [反對觀點][資料安全]\n\n**反對理由／受影響者：**即使開始為防餵鴿收集影片，日後可能有人想改作其他目的或不當分享。  **政策取捨：**訂資料用途、存取、刪除和正式調查例外的明確規則。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| data leak | 資料外洩 |\n| safe storage | 安全儲存 |\n| use of videos | 影片用途 |\n| delete data | 刪除資料 |\n| set limits | 設定界線 |\n\n#### 151. 旅遊業會擔心額外講解令行程延誤 [反對觀點][營運成本]\n\n**反對理由／受影響者：**導遊每天處理交通、集合、入場與購物，新增長篇禁餵課堂會擠壓遊覽時間。  **政策取捨：**將提醒壓縮至30秒並供官方現成圖卡，減少重複準備。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| tour schedule | 旅遊行程 |\n| time pressure | 時間壓力 |\n| short talk | 短講 |\n| ready-made card | 現成圖卡 |\n| keep on time | 準時進行 |\n\n#### 152. 旅監局不能任意把自願指引變成新的牌照義務 [反對觀點][法律權限]\n\n**反對理由／受影響者：**持牌旅行社及導遊固然可配合宣傳，但任何新增強制條件必須符合《旅遊業條例》與適用程序。  **政策取捨：**先採自願培訓；如需強制則須合法諮詢與評估。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| legal powers | 法定權力 |\n| new requirement | 新增要求 |\n| voluntary rule | 自願規則 |\n| fair process | 公平程序 |\n| industry views | 業界意見 |\n\n#### 153. 不參團的自由行遊客可能收不到導遊提醒 [反對觀點][覆蓋不足]\n\n**反對理由／受影響者：**若所有教育資源只給旅行社，酒店住客及獨立遊客就可能漏掉資訊。  **政策取捨：**須同時保留現場標示、旅發局網頁及其他接觸點。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| independent travel | 自由行 |\n| travel group | 旅行團 |\n| missing information | 缺少資訊 |\n| visitor access | 遊客獲取資訊 |\n| different channels | 不同渠道 |\n\n#### 154. 商戶可能不願承擔印刷與額外清潔費 [反對觀點][成本分擔]\n\n**反對理由／受影響者：**餐飲商戶或小販利潤有限，政府若無償要求他們增加管理工作，可能增加營商困難。  **政策取捨：**以免費素材及適用合約處理，不能把公共責任全部推給商戶。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| shop costs | 商戶成本 |\n| small business | 小商戶 |\n| free materials | 免費素材 |\n| shared costs | 分擔成本 |\n| reasonable request | 合理要求 |\n\n#### 155. 清潔改善可能治標不治本 [反對觀點][根本原因]\n\n**反對理由／受影響者：**即使天天清走鳥糞，只要仍有人撒糧，鴿群仍可能返回並再次留下污染。  **政策取捨：**需同時處理違規餵飼和食物殘留，不能單靠清潔評估成功。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| surface problem | 表面問題 |\n| root cause | 根本原因 |\n| repeat problem | 重複問題 |\n| food source | 食物來源 |\n| long-term answer | 長遠答案 |\n\n#### 156. 強行驅逐鳥群可能造成其他動物福利問題 [反對觀點][動物保護]\n\n**反對理由／受影響者：**不適當的噪音、追逐及物理措施可能令雀鳥受驚或受傷，亦影響海灘寧靜。  **政策取捨：**先由專業人員評估低傷害方法，不以趕走鳥作唯一目標。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| loud noise | 巨大噪音 |\n| scared birds | 受驚雀鳥 |\n| physical harm | 身體傷害 |\n| gentle method | 溫和方法 |\n| expert advice | 專家建議 |\n\n#### 157. 只治理淺水灣可能把聚集問題轉往周邊地區 [反對觀點][問題轉移]\n\n**反對理由／受影響者：**鳥群和餵飼者可能改到另一段海灘或附近街道，令統計上的淺水灣改善掩蓋整體變差。  **政策取捨：**需檢查鄰近場地而非只看單一指標。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| move elsewhere | 轉往別處 |\n| nearby places | 附近地方 |\n| hidden cost | 隱藏成本 |\n| whole area | 整個地區 |\n| check nearby | 檢查附近 |\n\n#### 158. 過度依賴義工可能令前線承受衝突風險 [反對觀點][人員安全]\n\n**反對理由／受影響者：**義工沒有法定搜查或罰款權，卻可能被遊客當成執法人員而發生爭執。  **政策取捨：**限制義工只做教育及通報，必要時由正式人員接手。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| volunteer safety | 義工安全 |\n| no legal power | 沒有法定權力 |\n| public argument | 公眾爭執 |\n| clear role | 清晰角色 |\n| call staff | 通知職員 |\n\n#### 159. 一段短片可能令政策過度回應個別事件 [反對觀點][證據不足]\n\n**反對理由／受影響者：**單一新聞能揭示風險，但不足以證明全港遊客普遍有同一行為，也不能證明某方案一定有效。  **政策取捨：**先蒐集基線資料，再考慮擴大政策。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| single event | 個別事件 |\n| strong evidence | 有力證據 |\n| avoid overreaction | 避免過度反應 |\n| collect facts | 收集事實 |\n| careful planning | 審慎規劃 |\n\n#### 160. 劃出過大禁入區會損害公眾享用沙灘的權利 [反對觀點][公平使用]\n\n**反對理由／受影響者：**若為減少鴿群聚集而長期圍起大面積泳灘，守規則的遊客也受限制。  **政策取捨：**只在有特別風險及法定依據下採短期、最小範圍安排。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| public access | 公眾使用權 |\n| restricted area | 限制區域 |\n| open beach | 開放泳灘 |\n| short period | 短暫期間 |\n| fair use | 公平使用 |\n\n#### 161. 只統計罰款張數可能鼓勵不必要執法 [反對觀點][政策誘因]\n\n**反對理由／受影響者：**如果部門以發單數量作成績，職員可能把時間放在容易開單的場景而非真正的健康與福利改善。  **政策取捨：**評估須同時看違規率、動物接觸、環境改善與公平投訴。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| fine numbers | 罰款張數 |\n| wrong target | 錯誤目標 |\n| staff pressure | 員工壓力 |\n| real improvement | 真正改善 |\n| balanced review | 平衡評估 |\n\n#### 162. 試行前後的變化未必由政策造成 [反對觀點][研究限制]\n\n**反對理由／受影響者：**天氣、海灘活動及旅行團數量都會改變，即使餵飼次數下降也不能立即歸因於標示。  **政策取捨：**應以相近時段、比較地點及透明資料作審慎分析。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| weather effect | 天氣影響 |\n| visitor change | 遊客變化 |\n| cause and effect | 因果關係 |\n| compare fairly | 公平比較 |\n| study limits | 研究限制 |\n\n#### 163. 疫情式警告及嚴厲態度可能損害香港友善旅遊形象 [反對觀點][溝通取捨]\n\n**反對理由／受影響者：**如果所有宣傳都強調疾病與處罰，守規矩旅客可能覺得被預先當成違法者。  **政策取捨：**採友善語氣說明理由，同時明確列出不得餵鳥的法例。\n\n**Glossary（B1–B2，5 組）**\n\n| English | 繁體中文 |\n|---|---|\n| friendly city | 友善城市 |\n| public image | 公眾形象 |\n| respect visitors | 尊重遊客 |\n| avoid fear | 避免恐懼 |\n| clear rules | 清楚規則 |"},{"title":"6｜從不同角度組合政策（不是固定唯一答案）","markdown":"| 政策包 | 適合情境 | 包括的操作 | 必須留意 |\n|---|---|---|---|\n| **A｜低成本先做** | 遊客多、預算緊 | 標示設在決策點、旅行社抵達前提醒、現有清潔路線加強、1823 易見、培訓一線人員 | 不可把紙上宣傳當成實際效果 |\n| **B｜高峰時段精準巡查** | 假日或網上影片反覆顯示同一地點 | 康文署獲委任人員＋漁護署按高風險時段巡查、保存合適證據、依法處理 | 不能對所有遊客作任意搜查或按國籍選擇執法 |\n| **C｜良好旅遊體驗** | 景點希望減少遊客與動物接觸但保留拍照 | 非接觸拍照點、觀鳥遠距離標示、導遊講解、酒店和商戶宣傳 | 不應把「可拍照」變成「誘使鴿群聚集」 |\n| **D｜長期生態與衞生** | 黑點持續、鳥糞或食物殘渣累積 | 定期清潔、垃圾設施、專業雀鳥觀察、可比較的成效資料 | 不以大規模傷害動物作便捷解決方案 |\n\n**如果只有很少資源：**先優化現有康文署管理與漁護署巡查的**時間和位置**，再將旅遊提醒放到既有的旅行社／景點資訊渠道；不要未有證據就開設全天新巡邏隊或大規模監控系統。"},{"title":"8｜主題詞彙：59 個關鍵詞，各五種 B1–B2 近義或改寫表達","markdown":"> **使用提醒：**以下包括真正近義詞與**語境相近的改寫**，並非所有詞在法律、醫療或語法上完全可互換。用於寫作前，須按句意選擇。\n\n| Thematic keyword | 繁體中文 | 五種近義或改寫表達 |\n|---|---|---|\n| **illegal feeding** | 違規餵飼 | feeding against the law；breaking the feeding rule；giving food illegally；feeding where it is banned；feeding without permission |\n| **feral pigeons** | 野鴿 | street pigeons；free-living pigeons；pigeons in public areas；pigeons living outside；pigeons around the city |\n| **animal protection** | 動物保障 | animal care；keeping animals safe；protecting birds；preventing animal harm；care for wildlife |\n| **animal harm** | 傷害動物 | injury to animals；harm to birds；causing pain to animals；rough treatment of animals；unsafe handling of birds |\n| **public health** | 公共衞生 | people's health；health in public places；community health；public hygiene；keeping visitors healthy |\n| **public hygiene** | 公共環境衞生 | clean public areas；clean streets and beaches；public cleanliness；hygiene in shared spaces；keeping the area clean |\n| **food waste** | 食物殘渣 | leftover food；food remains；unused food；food thrown away；food scraps |\n| **bird droppings** | 鳥糞 | bird waste；bird mess；waste left by birds；droppings on the ground；dirty areas caused by birds |\n| **risk** | 風險 | danger；possible harm；safety concern；chance of harm；something that may go wrong |\n| **prevention** | 預防 | early action；stopping problems early；avoiding harm；risk reduction；steps to prevent problems |\n| **warning sign** | 警示牌 | notice sign；public warning；information board；rule reminder；safety notice |\n| **clear rules** | 清晰規則 | simple rules；easy-to-follow rules；public rules；well-explained rules；rules people can understand |\n| **visitor guidance** | 遊客指引 | tourist advice；visitor information；travel advice；simple instructions；help for visitors |\n| **multilingual information** | 多語言資訊 | information in several languages；language choices；translated signs；more than one language；easy language support |\n| **education** | 教育 | learning；public teaching；awareness lessons；school activities；visitor lessons |\n| **public awareness** | 公眾意識 | public understanding；knowing the rules；visitor knowledge；awareness of the risks；understanding the problem |\n| **wildlife** | 野生動物 | wild animals；animals living outside；nature and animals；local wild birds；birds in nature |\n| **tourism** | 旅遊業 | travel；visitor activities；holiday travel；tourist visits；the travel industry |\n| **tourist experience** | 遊客體驗 | visitor experience；holiday experience；enjoying the visit；quality of a trip；travel experience |\n| **visitor satisfaction** | 遊客滿意度 | visitor feedback；happy visitors；quality of the visit；positive visitor experience；visitor opinions |\n| **tour guide** | 導遊 | travel guide；group guide；person leading a tour；tour leader；travel group leader |\n| **tour group** | 旅行團 | travel group；group of visitors；organised tour；holiday group；guided group |\n| **local residents** | 本地居民 | people living nearby；neighbours；local people；area residents；people in the community |\n| **beach visitors** | 泳灘訪客 | people at the beach；beach users；people visiting the shore；seaside visitors；people enjoying the beach |\n| **family visitors** | 家庭遊客 | visiting families；parents and children；family groups；families on holiday；family tourists |\n| **child safety** | 兒童安全 | keeping children safe；safe activities for children；children's well-being；family safety；protecting young visitors |\n| **safe distance** | 安全距離 | enough space；keep your distance；stand back from animals；watch from far away；do not get too close |\n| **close contact** | 近距離接觸 | direct contact；touching animals；being too close；physical contact；close interaction |\n| **photo opportunity** | 拍照機會 | picture spot；photo place；good place for pictures；photo chance；place to take photos |\n| **nature watching** | 自然觀察 | bird watching；watching wildlife；looking at nature；observing birds；watching from a distance |\n| **visitor behaviour** | 遊客行為 | actions of visitors；what visitors do；tourist actions；behaviour in public；how people act |\n| **rule-breaking** | 違反規則 | breaking rules；not following the rules；illegal action；acting against the rules；failure to follow the rules |\n| **law enforcement** | 執法 | applying the law；official action；making sure rules are followed；carrying out the law；legal action against rule-breakers |\n| **patrol** | 巡查 | regular checks；site checks；officer visits；walking inspections；checks around the area |\n| **fine** | 罰款 | money penalty；financial penalty；payment for breaking a rule；fixed penalty；penalty payment |\n| **report a problem** | 舉報問題 | make a report；tell the staff；inform the department；send a complaint；report what happened |\n| **public complaint** | 公眾投訴 | visitor complaint；resident concern；public report；complaint from a visitor；feedback about a problem |\n| **hotspot** | 黑點 | problem area；busy trouble spot；place with repeated problems；high-risk location；area needing attention |\n| **staff training** | 員工培訓 | worker training；staff lessons；learning for staff；practice for employees；training sessions |\n| **teamwork** | 團隊合作 | working together；shared work；cooperation；working as a team；joint effort |\n| **cross-department work** | 跨部門合作 | work between departments；departments working together；joint government work；shared department action；working across offices |\n| **resource limits** | 資源限制 | limited staff；limited money；budget limits；not enough staff；shortage of resources |\n| **cost** | 成本 | expense；money needed；spending；financial cost；cost of the work |\n| **fair treatment** | 公平對待 | equal treatment；respectful treatment；same rules for everyone；fair process；fair decisions |\n| **privacy** | 私隱 | personal privacy；private information；personal space；right to keep things private；protection of personal details |\n| **personal information** | 個人資料 | personal details；private details；information about a person；contact information；identity details |\n| **CCTV cameras** | 閉路電視 | security cameras；video cameras；recording cameras；public safety cameras；camera systems |\n| **data collection** | 資料收集 | gathering information；recording facts；collecting details；keeping useful records；getting basic figures |\n| **measuring results** | 衡量成效 | checking results；looking at changes；measuring progress；seeing what works；reviewing the outcome |\n| **trial plan** | 試行方案 | pilot plan；small test；trial programme；short test period；test run |\n| **long-term change** | 長遠改變 | lasting improvement；change over time；long-term results；future improvement；continued progress |\n| **community help** | 社區互助 | local support；help from residents；neighbourhood support；community action；people helping together |\n| **animal rescue** | 動物救援 | helping injured animals；wildlife rescue；care for injured birds；animal first aid by experts；rescue work for birds |\n| **professional help** | 專業協助 | expert help；trained support；help from specialists；qualified support；help from experienced staff |\n| **health advice** | 健康建議 | health guidance；safety advice；public health tips；advice on staying well；health information |\n| **cleaning schedule** | 清潔安排 | cleaning plan；regular cleaning；cleaning timetable；planned cleaning；clean-up times |\n| **waste bins** | 垃圾桶 | rubbish bins；covered bins；bins for waste；trash containers；public waste bins |\n| **hand washing** | 洗手 | wash your hands；clean your hands；hand cleaning；washing with soap；good hand hygiene |\n| **risk-based planning** | 按風險安排 | planning around risk；focus on problem areas；use staff where needed；match work to risks；give attention to busy spots |\n\n### 六組容易混淆的詞義\n\n- **Feed a pigeon / touch a pigeon / catch a pigeon：**餵飼、觸碰、捕捉是不同動作；相關法律要件與證據不可一概而論。\n- **A fixed penalty / a maximum court penalty：**定額罰款與被檢控定罪後的最高刑罰是兩條不同處理路徑。\n- **Public health risk / confirmed infection：**潛在公共衞生風險不是已確診感染。\n- **A tourist / a tour group member：**遊客不必然參加旅行團；任何人都不能僅憑影片或留言確定國籍。\n- **A warning sign / a legal warning：**預防性告示不等於執法時必須先作口頭警告。\n- **Animal welfare concern / proven animal cruelty：**關注雀鳥福利不等於已證明構成虐待動物罪。"},{"title":"9｜政策成效、成本與公平性：驗收表","markdown":"| 目標 | 可使用的資料（須匿名或只保留必要資訊） | 切忌直接推斷 |\n|---|---|---|\n| 減少餵飼 | 指定時段觀察到的餵飼次數／人流、重複黑點 | 發出越多罰款，就一定代表問題更嚴重或政策更成功 |\n| 野鴿福祉 | 受傷報告、專業救援轉介、遊客直接接觸次數 | 影片有羽毛掉落就能確定特定傷勢或刑事罪名 |\n| 公共衞生 | 鳥糞覆蓋、食物殘渣、清潔時間、投訴分佈 | 接觸雀鳥就等於已感染禽流感 |\n| 旅遊體驗 | 遊客是否理解標示、照片與觀景替代方案使用率 | 遊客數下降就必然因為禁餵措施 |\n| 行政效率 | 每人時巡查發現的有效個案、轉介時間、部門重複工作 | 只追求高罰款額就是最佳資源使用 |\n| 公平及私隱 | 投訴處理、語言可達性、CCTV 資料保存與刪除 | 網民猜測的國籍等同可用的違規證據 |"},{"title":"10｜來源、教材依據與法律狀態（核對至 2026-11-22）","markdown":"### 10.1 公開來源\n\n\n- **[S01] 2026-11-21《星島頭條》新聞原文：** <https://www.stheadline.com/breaking-news/3639689/%E6%9C%89%E7%89%87%E6%B7%BA%E6%B0%B4%E7%81%A3%E6%B3%B3%E7%81%98%E9%87%8E%E9%B4%BF%E8%81%9A%E9%9B%86-%E9%81%8A%E5%AE%A2%E6%92%92%E7%B3%A7%E6%8D%89%E9%B4%BF%E5%90%88%E7%85%A7-%E7%B6%B2%E6%B0%91%E8%A1%9E%E7%94%9F%E6%84%8F%E8%AD%98%E5%92%81%E5%B7%AE>\n- **[S02] 漁護署：全港禁餵野生動物及野鴿、法例及各部門執法分工：** <https://www.afcd.gov.hk/english/conservation/con_fau/con_fau_wild_the.html>\n- **[S03] 漁護署：2024-09-01 起對非法餵飼直接執法：** <https://www.afcd.gov.hk/english/publications/publications_press/pr3037.html>\n- **[S04] 康文署：淺水灣泳灘屬南區公眾泳灘：** <https://www.lcsd.gov.hk/en/beach/index/beach-location-hk/beach-address-south.html>\n- **[S05] 香港政府 2026-06-24：野鴿黑點、跨部門執法、AI 試驗及餵飼定額罰款資料：** <https://www.info.gov.hk/gia/general/202606/24/P2026062400267p.htm>\n- **[S06] 香港政府 2026-09-30：訪客宣傳、口岸及港鐵反餵飼資訊：** <https://www.info.gov.hk/gia/general/202609/30/P2026093000304.htm>\n- **[S07] 漁護署：雀鳥保護，《野生動物保護條例》第170章：** <https://www.afcd.gov.hk/english/conservation/hkbiodiversity/speciesgroup/speciesgroup_birds.html>\n- **[S08] 香港政府：第169章虐待動物罪的要件與漁護署、警方分工：** <https://www.info.gov.hk/gia/general/202502/26/P2025022600208.htm>\n- **[S09] 衞生防護中心：與雀鳥及排泄物避免接觸、接觸後洗手：** <https://www.chp.gov.hk/en/healthtopics/content/24/13.html>\n- **[S10] 文化體育及旅遊局：旅遊事務署、旅監局職能：** <https://www.cstb.gov.hk/en/policies/tourism.html>\n- **[S11] 香港政府 2026-10-07：旅監局、旅行社及導遊規管與跨部門合作：** <https://www.info.gov.hk/gia/general/202610/07/P2026100700257.htm>\n- **[S12] 私隱專員公署：CCTV 攝錄應有合理用途及清楚告示：** <https://www.pcpd.org.hk/english/whatsnew/20251103a.html>\n- **[S13] 愛護動物協會：發現受傷野鳥時避免自行處理、尋求專業協助：** <https://www.spca.org.hk/zh-hant/help-advice/pawprint-magazine/issue-120-what-to-do-if-you-find-a-baby-bird/>\n- **[S14] 漁護署：遇非法餵飼可致電 1823 舉報：** <https://www.afcd.gov.hk/english/quarantine/qua_live/qua_live_dontfeed/qua_live_dontfeed.html>\n\n### 10.2 上載教材的具體使用\n\n- **《News Discussion Manual(2).pdf》**：依照「不限數量的新機制探索」、「有效性六問」、「每論點緊接五組英中詞彙」、「功能導向句式」與「避免重複」的編輯流程。\n- **《News 2(4).pdf》／《News Discussion 1 - (2).pdf》**：沿用角度分類、獨立連續編號、標題＋2–4句簡明機制和每點 Glossary 的教材結構；因本題是政策設計，改以具體執行者與操作作為論點內容。\n- **《Policy System Study - Book 1 (General).pdf》**：將資訊不對稱、負外部性、公共服務、規管、誘因、跨部門協調及政策評估等方向轉化為具體工具。\n- **《(4) Golden_Manual_Edmund_Sir_v1_0 - Porposal Ideas Brainstoring High Level Thinking.pdf》**：強調特定責任者、實際觸發點、可執行做法、合理機制、可衡量結果與反作用力。\n- **其他 Golden Manual／三冊 Civics Vocabulary**：用繁體中文解釋原因、用英文教可遷移詞彙；核對每項職權、避免偏見和不當指控；**遵照最新指令把 Glossary 調整為 B1–B2**。\n\n### 10.3 品質驗收與政策邊界\n\n\n- [x] 已有 **163** 個獨立論點（**139** 項政策、**24** 項反對／限制）。\n- [x] **815 組英中 Glossary**；每點正下方剛好五組。\n- [x] **20 個**各有用途的 B1–B2 英文句式，未加例句。\n- [x] **59** 個主題詞，各五項改寫，共 **295** 項。\n- [x] 政府部門和非政府持份者分清；只有具法定權力的獲委任人員才可執法。\n- [x] 將現行法規、可選擇的加強措施與新的管理倡議分清。\n- [x] 未將「網民猜測旅客來源」當成已核實事實。\n- [x] 未將「抓鴿、羽毛掉落」直接等同於刑事罪名已成立。\n- [x] 未將疾病風險說成已發生禽流感個案。\n- [x] 有資源、誤判、私隱、旅遊體驗、勞工與動物福利等反對觀點。\n- [x] 文件為 **Markdown（.md）**，方便轉換為課堂講義。\n\n**法律、動物救護及公共衞生資訊為政策教育用途，不構成個案法律或醫療意見。正式執法、傷病雀鳥救援及任何需加設監控的措施，應循相關法律與機構程序進行。**"}],"source_document":"HK_Repulse_Bay_Pigeon_Tourism_Public_Health_Policy_Brainstorm_B1_B2.md","language_level":"B1–B2"}$content$::jsonb;
  v_image bytea := decode($image$$image$, 'base64');
begin
  select id into v_id
  from public.policy_discussion_articles
  where title = $title$淺水灣泳灘野鴿聚集 遊客撒糧捉鴿合照$title$ and deleted_at is null
  order by created_at
  limit 1;

  if v_id is null then
    insert into public.policy_discussion_articles(
      title, brief, source_url, content, image_mime, image_bytes, hidden, sort_order
    ) values (
      $title$淺水灣泳灘野鴿聚集 遊客撒糧捉鴿合照$title$,
      $brief$網上流傳影片顯示，多名男女及兒童在淺水灣泳灘違規餵飼野鴿，引來大批鴿群聚集。一名約10歲男童更徒手捕捉野鴿，讓同行女子拍照，隨後將鴿子拋高放生，期間有羽毛掉落。**不少網民估計涉事人士是參加旅遊團的內地遊客**，猛烈批評其缺乏公共衞生及動物保護意識，並擔心接觸野鴿可能增加疾病傳播風險。根據香港現行法例，非法餵飼野鴿可被處以5,000港元定額罰款，最高刑罰為罰款10萬元及監禁一年。$brief$,
      $url$https://www.stheadline.com/breaking-news/3639689/$url$,
      v_content,
      'image/png',
      v_image,
      false,
      (select coalesce(min(sort_order), 0) - 1 from public.policy_discussion_articles)
    ) returning id into v_id;
  else
    update public.policy_discussion_articles
    set brief = $brief$網上流傳影片顯示，多名男女及兒童在淺水灣泳灘違規餵飼野鴿，引來大批鴿群聚集。一名約10歲男童更徒手捕捉野鴿，讓同行女子拍照，隨後將鴿子拋高放生，期間有羽毛掉落。**不少網民估計涉事人士是參加旅遊團的內地遊客**，猛烈批評其缺乏公共衞生及動物保護意識，並擔心接觸野鴿可能增加疾病傳播風險。根據香港現行法例，非法餵飼野鴿可被處以5,000港元定額罰款，最高刑罰為罰款10萬元及監禁一年。$brief$,
        source_url = $url$https://www.stheadline.com/breaking-news/3639689/$url$,
        content = v_content,
        image_mime = 'image/png',
        image_bytes = v_image,
        hidden = false,
        updated_at = now()
    where id = v_id;
  end if;
end;
$seed$;

commit;
